_ROLLOUT_DUMP_EXECUTOR = None
_ROLLOUT_DUMP_EXECUTOR_LOCK = threading.Lock()


def _get_rollout_dump_executor():
    global _ROLLOUT_DUMP_EXECUTOR
    if _ROLLOUT_DUMP_EXECUTOR is None:
        with _ROLLOUT_DUMP_EXECUTOR_LOCK:
            if _ROLLOUT_DUMP_EXECUTOR is None:
                _ROLLOUT_DUMP_EXECUTOR = ThreadPoolExecutor(
                    max_workers=1,
                    thread_name_prefix="rollout-dump",
                )
    return _ROLLOUT_DUMP_EXECUTOR


def _write_generation_jsonl(filename, base_data, artifacts):
    n = len(base_data["input"])
    with open(filename, "w") as f:
        for i in range(n):
            entry = {key: values[i] for key, values in base_data.items()}
            if artifacts is not None and i < len(artifacts):
                entry.update(artifacts[i])
            f.write(json.dumps(_json_safe(entry), ensure_ascii=False))
            f.write("\n")


def _report_rollout_dump_failure(future):
    exc = future.exception()
    if exc is not None:
        print(f"Async rollout dump failed: {type(exc).__name__}: {exc}")


class _ZeroSignalGRPOBatch(RuntimeError):
    """Internal control flow for a valid rollout batch with no trainable group."""

    def __init__(self, metrics: Optional[dict[str, float]] = None) -> None:
        super().__init__("GRPO batch contains no non-zero selected advantages")
        self.metrics = dict(metrics or {})


def _json_safe(value: Any):
    if isinstance(value, torch.Tensor):
        return value.detach().cpu().tolist()
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, dict):
        return {str(k): _json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(v) for v in value]
    return value


def _filter_row_aligned_non_tensor_batch(
    non_tensor_batch: dict[str, Any],
    keep_rows: torch.Tensor,
) -> dict[str, Any]:
    """Filter row-aligned metadata while preserving scalar/shared entries."""

    keep_np = keep_rows.detach().cpu().bool().numpy()
    row_count = int(keep_np.shape[0])
    keep_indices = np.flatnonzero(keep_np).tolist()
    filtered: dict[str, Any] = {}
    for key, value in non_tensor_batch.items():
        if isinstance(value, np.ndarray) and value.ndim > 0 and value.shape[0] == row_count:
            filtered[key] = value[keep_np]
        elif isinstance(value, list) and len(value) == row_count:
            filtered[key] = [value[index] for index in keep_indices]
        elif isinstance(value, tuple) and len(value) == row_count:
            filtered[key] = tuple(value[index] for index in keep_indices)
        else:
            filtered[key] = value
    return filtered


def _index_row_aligned_non_tensor_batch(
    non_tensor_batch: dict[str, Any],
    row_indices: list[int],
    *,
    row_count: int,
) -> dict[str, Any]:
    indexed: dict[str, Any] = {}
    index_np = np.asarray(row_indices, dtype=np.int64)
    for key, value in non_tensor_batch.items():
        if (
            isinstance(value, np.ndarray)
            and value.ndim > 0
            and value.shape[0] == row_count
        ):
            indexed[key] = value[index_np]
        elif isinstance(value, list) and len(value) == row_count:
            indexed[key] = [value[index] for index in row_indices]
        elif isinstance(value, tuple) and len(value) == row_count:
            indexed[key] = tuple(value[index] for index in row_indices)
        else:
            indexed[key] = value
    return indexed


def _cost_balanced_row_permutation(
    row_costs: torch.Tensor,
    *,
    num_ranks: int,
) -> tuple[list[int], list[float], list[int]]:
    """Order rows so contiguous DP chunks are capacity- and cost-balanced."""
    costs = row_costs.detach().cpu().double().view(-1)
    row_count = int(costs.numel())
    num_ranks = max(int(num_ranks), 1)
    base = row_count // num_ranks
    remainder = row_count % num_ranks
    capacities = [
        base + (1 if rank < remainder else 0)
        for rank in range(num_ranks)
    ]
    assignments: list[list[int]] = [[] for _ in range(num_ranks)]
    rank_costs = [0.0] * num_ranks
    for row_index in sorted(
        range(row_count),
        key=lambda index: (-float(costs[index].item()), index),
    ):
        candidates = [
            rank
            for rank in range(num_ranks)
            if len(assignments[rank]) < capacities[rank]
        ]
        rank = min(
            candidates,
            key=lambda candidate: (
                rank_costs[candidate],
                len(assignments[candidate]),
                candidate,
            ),
        )
        assignments[rank].append(row_index)
        rank_costs[rank] += float(costs[row_index].item())
    permutation = [
        row_index
        for assignment in assignments
        for row_index in assignment
    ]
    return permutation, rank_costs, [
        len(assignment) for assignment in assignments
    ]


def _owner_align_gpu_replay_lease_rows(
    item_batch: TensorDict,
    non_tensor_batch: dict[str, Any],
    *,
    actor_data_parallel_size: int,
    sequence_parallel_size: int = 1,
    row_assignments: list[list[int]] | None = None,
) -> tuple[TensorDict, dict[str, Any], dict[str, float]]:
    """Keep one-shot CUDA IPC rows in their producer SP group."""
    sc_key = "_packed_sparse_sc_gpu_leases"
    logits_key = "_packed_sparse_logits_gpu_leases"
    sc_rows = non_tensor_batch.get(sc_key)
    if not isinstance(sc_rows, np.ndarray):
        return item_batch, non_tensor_batch, {
            "trace_all_ce/gpu_lease_owner_alignment": 0.0,
            "trace_all_ce/gpu_lease_ghost_rows": 0.0,
        }
    row_count = len(item_batch)
    if len(sc_rows) != row_count:
        raise RuntimeError(
            "GPU replay lease rows are not aligned with TensorDict rows"
        )
    actor_data_parallel_size = max(
        int(actor_data_parallel_size),
        1,
    )
    sequence_parallel_size = max(
        int(sequence_parallel_size),
        1,
    )
    actor_world_size = (
        actor_data_parallel_size * sequence_parallel_size
    )
    if row_assignments is None:
        assignments: list[list[int]] = [
            [] for _ in range(actor_data_parallel_size)
        ]
        for row_index, row_descriptors in enumerate(sc_rows.tolist()):
            if not isinstance(row_descriptors, list) or not row_descriptors:
                raise RuntimeError(
                    "non-ghost GPU replay row is missing self-conditioning leases"
                )
            owner_ranks = {
                int(descriptor.get("producer_replica_rank", -1))
                for descriptor in row_descriptors
                if isinstance(descriptor, dict)
            }
            if len(owner_ranks) != 1:
                raise RuntimeError(
                    "packed replay row spans multiple producer GPUs: "
                    f"row={row_index} owners={sorted(owner_ranks)}"
                )
            owner_rank = next(iter(owner_ranks))
            if not 0 <= owner_rank < actor_world_size:
                raise RuntimeError(
                    "GPU replay producer rank is outside actor world: "
                    f"row={row_index} owner={owner_rank} "
                    f"world={actor_world_size}"
                )
            owner_dp_rank = owner_rank // sequence_parallel_size
            assignments[owner_dp_rank].append(row_index)
    else:
        assignments = [
            [int(row_index) for row_index in assignment]
            for assignment in row_assignments
        ]
        if len(assignments) != actor_data_parallel_size:
            raise RuntimeError(
                "GPU replay row assignments do not match actor DP: "
                f"{len(assignments)} != {actor_data_parallel_size}"
            )
        assigned_rows = [
            row_index
            for assignment in assignments
            for row_index in assignment
        ]
        if sorted(assigned_rows) != list(range(row_count)):
            raise RuntimeError(
                "GPU replay row assignments must cover every row exactly once"
            )

    max_rows = max((len(rows) for rows in assignments), default=0)
    if max_rows <= 0:
        raise RuntimeError("GPU replay owner alignment has no real rows")
    aligned_rows = (
        (
            max_rows
            + sequence_parallel_size
            - 1
        )
        // sequence_parallel_size
    ) * sequence_parallel_size
    template_index = next(
        row_index
        for rows in assignments
        for row_index in rows
    )
    output_indices: list[int] = []
    output_is_ghost: list[bool] = []
    output_sc_rows: list[list[dict[str, Any]]] = []
    logits_rows = non_tensor_batch.get(logits_key)
    logits_values = (
        logits_rows.tolist()
        if isinstance(logits_rows, np.ndarray)
        else None
    )
    output_logits_rows: list[list[dict[str, Any]]] = []
    rank_row_counts = [len(rows) for rows in assignments]
    for rank_rows in assignments:
        for row_index in rank_rows:
            output_indices.append(row_index)
            output_is_ghost.append(False)
            output_sc_rows.append(sc_rows[row_index])
            if logits_values is not None:
                output_logits_rows.append(logits_values[row_index])
        for _ in range(aligned_rows - len(rank_rows)):
            output_indices.append(template_index)
            output_is_ghost.append(True)
            output_sc_rows.append([])
            if logits_values is not None:
                output_logits_rows.append([])

    expanded = item_batch[
        torch.as_tensor(output_indices, dtype=torch.long)
    ].clone()
    ghost_mask = torch.tensor(
        output_is_ghost,
        dtype=torch.bool,
        device=expanded["response_mask"].device,
    )
    if bool(ghost_mask.any()):
        expanded["responses"][ghost_mask] = -100
        for key in (
            "response_mask",
            "response_future_steps_mask",
            "response_current_step_mask",
            "rollout_quality_mask",
        ):
            if key in expanded:
                expanded[key][ghost_mask] = False
        if "signed_trace_ce_role" in expanded:
            expanded["signed_trace_ce_role"][ghost_mask] = 0
        if "causal_wrong_ce_role" in expanded:
            expanded["causal_wrong_ce_role"][ghost_mask] = 0
        if "step_maps" in expanded:
            expanded["step_maps"][ghost_mask] = -1
        for key in (
            "rollout_self_conditioning_signal_block_starts",
            "rollout_self_conditioning_signal_block_lengths",
            "rollout_logits_source_hidden_block_starts",
            "rollout_logits_source_hidden_block_lengths",
        ):
            if key in expanded:
                expanded[key][ghost_mask] = 0
        if "_packed_row_cost" in expanded:
            expanded["_packed_row_cost"][ghost_mask] = 0
    expanded["_packed_row_is_ghost"] = ghost_mask

    indexed_non_tensor = _index_row_aligned_non_tensor_batch(
        non_tensor_batch,
        output_indices,
        row_count=row_count,
    )
    sc_array = np.empty((len(output_sc_rows),), dtype=object)
    sc_array[:] = output_sc_rows
    indexed_non_tensor[sc_key] = sc_array
    if logits_values is not None:
        logits_array = np.empty(
            (len(output_logits_rows),),
            dtype=object,
        )
        logits_array[:] = output_logits_rows
        indexed_non_tensor[logits_key] = logits_array
    manifests = indexed_non_tensor.get("_packed_row_manifests")
    if isinstance(manifests, np.ndarray):
        updated_manifests = []
        for manifest, is_ghost in zip(
            manifests.tolist(),
            output_is_ghost,
            strict=True,
        ):
            if isinstance(manifest, dict) and is_ghost:
                manifest = dict(manifest)
                manifest["pages"] = []
                manifest["active_label_tokens"] = 0
                manifest["underfill_shard_kind"] = "gpu_lease_ghost"
            updated_manifests.append(manifest)
        indexed_non_tensor["_packed_row_manifests"] = np.asarray(
            updated_manifests,
            dtype=object,
        )
    ghost_rows = sum(output_is_ghost)
    return expanded, indexed_non_tensor, {
        "trace_all_ce/gpu_lease_owner_alignment": 1.0,
        "trace_all_ce/gpu_lease_rows_before": float(row_count),
        "trace_all_ce/gpu_lease_rows_after": float(len(expanded)),
        "trace_all_ce/gpu_lease_ghost_rows": float(ghost_rows),
        "trace_all_ce/gpu_lease_rank_rows_min": float(
            min(rank_row_counts)
        ),
        "trace_all_ce/gpu_lease_rank_rows_max": float(
            max(rank_row_counts)
        ),
    }


def _relay_gpu_replay_lease_rows_to_dp(
    non_tensor_batch: dict[str, Any],
    *,
    rank_row_counts: list[int],
    sequence_parallel_size: int,
    relay_table,
) -> tuple[dict[str, Any], dict[str, float]]:
    """Rewrite cost-balanced lease pages as target-rank GPU-local leases."""
    from sglang.srt.dllm.algorithm.sdar_gpu_replay_lease import (
        relay_gpu_replay_lease,
    )

    sequence_parallel_size = max(int(sequence_parallel_size), 1)
    target_dp_ranks = [
        rank
        for rank, row_count in enumerate(rank_row_counts)
        for _ in range(int(row_count))
    ]
    relayed_batch = dict(non_tensor_batch)
    relay_count = 0
    same_gpu_count = 0
    relay_bytes = 0
    for key in (
        "_packed_sparse_sc_gpu_leases",
        "_packed_sparse_logits_gpu_leases",
    ):
        rows = non_tensor_batch.get(key)
        if not isinstance(rows, np.ndarray):
            continue
        if len(rows) != len(target_dp_ranks):
            raise RuntimeError(
                "GPU replay relay rank mapping does not match rows: "
                f"{key}={len(rows)} targets={len(target_dp_ranks)}"
            )
        output_rows = []
        for target_dp_rank, descriptors in zip(
            target_dp_ranks,
            rows.tolist(),
            strict=True,
        ):
            if not isinstance(descriptors, list):
                raise RuntimeError(
                    f"GPU replay relay row for {key} is not a list"
                )
            output_descriptors = []
            target_device = (
                target_dp_rank * sequence_parallel_size
            )
            for descriptor in descriptors:
                source_rank = int(
                    descriptor.get("producer_replica_rank", -1)
                )
                output = relay_gpu_replay_lease(
                    descriptor,
                    target_device_index=target_device,
                    target_table=relay_table,
                )
                output_descriptors.append(output)
                if source_rank == target_device:
                    same_gpu_count += 1
                else:
                    relay_count += 1
                    relay_bytes += int(
                        descriptor.get("nbytes", 0) or 0
                    )
            output_rows.append(output_descriptors)
        output_array = np.empty((len(output_rows),), dtype=object)
        output_array[:] = output_rows
        relayed_batch[key] = output_array
    return relayed_batch, {
        "trace_all_ce/gpu_lease_relay_pages": float(relay_count),
        "trace_all_ce/gpu_lease_same_gpu_pages": float(
            same_gpu_count
        ),
        "trace_all_ce/gpu_lease_relay_bytes": float(relay_bytes),
    }


def _expand_hybrid_packed_rows_for_underfill(
    item_batch: TensorDict,
    non_tensor_batch: dict[str, Any],
    *,
    actor_data_parallel_size: int,
    block_size: int,
    fallback_mode: str = "block_only",
) -> tuple[TensorDict, dict[str, Any], dict[str, float]]:
    """Split underfilled packed rows into exact-label data-parallel subrows."""
    row_count = len(item_batch)
    actor_data_parallel_size = max(int(actor_data_parallel_size), 1)
    block_size = int(block_size)
    fallback_mode = str(fallback_mode or "block_only").strip().lower()
    if fallback_mode not in {"block_only", "block_then_label"}:
        raise ValueError(
            "trace_all_ce_underfill_fallback must be block_only or "
            f"block_then_label, got {fallback_mode!r}"
        )
    if (
        row_count <= 0
        or row_count >= actor_data_parallel_size
        or block_size <= 0
    ):
        label_total = float(
            item_batch["response_mask"].sum().item()
            if "response_mask" in item_batch
            else 0.0
        )
        return item_batch, non_tensor_batch, {
            "trace_all_ce/hybrid_underfill_applied": 0.0,
            "trace_all_ce/hybrid_underfill_rows_before": float(row_count),
            "trace_all_ce/hybrid_underfill_rows_after": float(row_count),
            "trace_all_ce/hybrid_underfill_block_split_rows": 0.0,
            "trace_all_ce/hybrid_underfill_label_split_rows": 0.0,
            "trace_all_ce/hybrid_underfill_useful_dp_ranks": float(
                min(row_count, actor_data_parallel_size)
            ),
            "trace_all_ce/hybrid_underfill_ghost_dp_ranks": 0.0,
            "trace_all_ce/hybrid_underfill_labels_before": label_total,
            "trace_all_ce/hybrid_underfill_labels_after": label_total,
            "trace_all_ce/hybrid_underfill_dp_size": float(
                actor_data_parallel_size
            ),
        }
    response_mask = item_batch["response_mask"].bool()
    response_length = int(response_mask.shape[1])
    if item_batch["input_ids"].shape != item_batch["attention_mask"].shape:
        raise RuntimeError(
            "hybrid packed replay input_ids/attention_mask shape mismatch: "
            f"input_ids={tuple(item_batch['input_ids'].shape)} "
            f"attention_mask={tuple(item_batch['attention_mask'].shape)}"
        )
    if int(item_batch["input_ids"].shape[1]) < response_length:
        raise RuntimeError(
            "hybrid packed replay response exceeds full sequence width"
        )
    if response_length % block_size:
        raise RuntimeError(
            "hybrid packed replay requires block-aligned response width: "
            f"response_length={response_length} block_size={block_size}"
        )
    block_count = response_length // block_size
    entries: list[dict[str, Any]] = []
    base_group = actor_data_parallel_size // row_count
    remainder = actor_data_parallel_size % row_count
    for row_index in range(row_count):
        active_blocks = torch.nonzero(
            response_mask[row_index]
            .reshape(block_count, block_size)
            .any(dim=-1),
            as_tuple=False,
        ).flatten().tolist()
        if not active_blocks:
            entries.append(
                {
                    "row_index": row_index,
                    "blocks": [],
                    "labels": [],
                    "kind": "ghost",
                }
            )
            continue
        group_size = base_group + (1 if row_index < remainder else 0)
        part_count = min(max(group_size, 1), len(active_blocks))
        partitions = [[] for _ in range(part_count)]
        for position, block_index in enumerate(active_blocks):
            partitions[position % part_count].append(int(block_index))
        for partition in partitions:
            block_mask = torch.zeros(
                response_length,
                dtype=torch.bool,
                device=response_mask.device,
            )
            for block_index in partition:
                start = int(block_index) * block_size
                block_mask[start : start + block_size] = True
            label_positions = torch.nonzero(
                response_mask[row_index] & block_mask,
                as_tuple=False,
            ).flatten().cpu().tolist()
            entries.append(
                {
                    "row_index": row_index,
                    "blocks": partition,
                    "labels": [int(pos) for pos in label_positions],
                    "kind": "block" if part_count > 1 else "base",
                }
            )

    block_stage_rows = len(entries)
    label_split_operations = 0
    if fallback_mode == "block_then_label":
        while len(entries) < actor_data_parallel_size:
            candidates = [
                index
                for index, entry in enumerate(entries)
                if len(entry["labels"]) > 1
            ]
            if not candidates:
                break
            split_index = min(
                candidates,
                key=lambda index: (
                    -len(entries[index]["labels"]),
                    int(entries[index]["row_index"]),
                    index,
                ),
            )
            source = entries[split_index]
            labels = list(source["labels"])
            midpoint = (len(labels) + 1) // 2
            left = dict(source)
            right = dict(source)
            left["blocks"] = list(source["blocks"])
            right["blocks"] = list(source["blocks"])
            left["labels"] = labels[:midpoint]
            right["labels"] = labels[midpoint:]
            left["kind"] = "label"
            right["kind"] = "label"
            entries[split_index : split_index + 1] = [left, right]
            label_split_operations += 1

        ghost_template = next(
            (
                entry
                for entry in entries
                if int(entry["row_index"]) >= 0
            ),
            None,
        )
        while (
            len(entries) < actor_data_parallel_size
            and ghost_template is not None
        ):
            entries.append(
                {
                    "row_index": int(ghost_template["row_index"]),
                    "blocks": [],
                    "labels": [],
                    "kind": "ghost",
                }
            )

    row_indices = [int(entry["row_index"]) for entry in entries]
    owned_blocks = [list(entry["blocks"]) for entry in entries]
    owned_labels = [list(entry["labels"]) for entry in entries]
    shard_kinds = [str(entry["kind"]) for entry in entries]

    index_tensor = torch.as_tensor(row_indices, dtype=torch.long)
    expanded = item_batch[index_tensor].clone()
    label_ownership = torch.zeros(
        (len(row_indices), response_length),
        dtype=torch.bool,
        device=response_mask.device,
    )
    for expanded_index, positions in enumerate(owned_labels):
        if positions:
            label_ownership[expanded_index, positions] = True

    coverage = torch.zeros_like(response_mask, dtype=torch.long)
    for expanded_index, source_row in enumerate(row_indices):
        coverage[source_row] += label_ownership[expanded_index].long()
    expected_coverage = response_mask.long()
    if not torch.equal(coverage, expected_coverage):
        duplicate_count = int(coverage.gt(1).sum().item())
        missing_count = int(
            (expected_coverage.bool() & coverage.eq(0)).sum().item()
        )
        raise RuntimeError(
            "hybrid underfill label ownership changed canonical CE coverage: "
            f"duplicates={duplicate_count} missing={missing_count}"
        )

    expanded["responses"] = torch.where(
        label_ownership,
        expanded["responses"],
        torch.full_like(expanded["responses"], -100),
    )
    for key in (
        "response_mask",
        "response_future_steps_mask",
        "response_current_step_mask",
        "rollout_quality_mask",
    ):
        if key in expanded:
            expanded[key] = expanded[key].bool() & label_ownership
    if "signed_trace_ce_role" in expanded:
        expanded["signed_trace_ce_role"] = torch.where(
            label_ownership,
            expanded["signed_trace_ce_role"],
            torch.zeros_like(expanded["signed_trace_ce_role"]),
        )
    if "causal_wrong_ce_role" in expanded:
        expanded["causal_wrong_ce_role"] = torch.where(
            label_ownership,
            expanded["causal_wrong_ce_role"],
            torch.zeros_like(expanded["causal_wrong_ce_role"]),
        )
    if "step_maps" in expanded:
        expanded["step_maps"] = torch.where(
            label_ownership,
            expanded["step_maps"],
            torch.full_like(expanded["step_maps"], -1),
        )
    expanded["_packed_row_is_ghost"] = torch.tensor(
        [kind == "ghost" for kind in shard_kinds],
        dtype=torch.bool,
        device=expanded["response_mask"].device,
    )
    for prefix in (
        "rollout_self_conditioning_signal",
        "rollout_logits_source_hidden",
    ):
        starts_key = f"{prefix}_block_starts"
        lengths_key = f"{prefix}_block_lengths"
        values_key = f"{prefix}_block_values"
        if (
            starts_key not in expanded
            or lengths_key not in expanded
            or values_key not in expanded
        ):
            continue
        starts = expanded[starts_key].long()
        lengths = expanded[lengths_key].long()
        values = expanded[values_key]
        page_blocks = torch.div(
            starts,
            block_size,
            rounding_mode="floor",
        )
        keep_pages = torch.zeros_like(lengths, dtype=torch.bool)
        for expanded_index, blocks in enumerate(owned_blocks):
            if not blocks:
                continue
            block_tensor = torch.tensor(
                blocks,
                dtype=page_blocks.dtype,
                device=page_blocks.device,
            )
            keep_pages[expanded_index] = (
                page_blocks[expanded_index].unsqueeze(-1)
                == block_tensor.unsqueeze(0)
            ).any(dim=-1)
        selected_pages = [
            torch.nonzero(
                keep_pages[row_index],
                as_tuple=False,
            ).flatten()
            for row_index in range(len(expanded))
        ]
        max_owned_pages = max(
            (int(indices.numel()) for indices in selected_pages),
            default=0,
        )
        compact_values = torch.zeros(
            (
                len(expanded),
                max_owned_pages,
                int(values.shape[2]),
                int(values.shape[3]),
            ),
            dtype=values.dtype,
            device=values.device,
        )
        compact_starts = torch.zeros(
            (len(expanded), max_owned_pages),
            dtype=starts.dtype,
            device=starts.device,
        )
        compact_lengths = torch.zeros_like(compact_starts)
        for row_index, selected in enumerate(selected_pages):
            page_count = int(selected.numel())
            if page_count <= 0:
                continue
            compact_values[row_index, :page_count] = values[
                row_index
            ].index_select(0, selected.to(values.device))
            compact_starts[row_index, :page_count] = starts[
                row_index
            ].index_select(0, selected.to(starts.device))
            compact_lengths[row_index, :page_count] = lengths[
                row_index
            ].index_select(0, selected.to(lengths.device))
        expanded[values_key] = compact_values
        expanded[starts_key] = compact_starts
        expanded[lengths_key] = compact_lengths

    sequence_cost = expanded["attention_mask"].sum(
        dim=-1,
        dtype=torch.float64,
    )
    label_cost = expanded["response_mask"].sum(
        dim=-1,
        dtype=torch.float64,
    )
    expanded["_packed_row_cost"] = sequence_cost + 8.0 * label_cost
    indexed_non_tensor = _index_row_aligned_non_tensor_batch(
        non_tensor_batch,
        row_indices,
        row_count=row_count,
    )
    manifests = indexed_non_tensor.get("_packed_row_manifests")
    if isinstance(manifests, np.ndarray):
        split_manifests = []
        for manifest, blocks in zip(manifests.tolist(), owned_blocks):
            if not isinstance(manifest, dict):
                split_manifests.append(manifest)
                continue
            manifest = dict(manifest)
            manifest["pages"] = [
                page
                for page in manifest.get("pages", [])
                if int(page.get("block_index", -1)) in set(blocks)
            ]
            manifest["active_label_tokens"] = int(
                expanded["response_mask"][
                    len(split_manifests)
                ].sum().item()
            )
            manifest["underfill_shard_kind"] = shard_kinds[
                len(split_manifests)
            ]
            split_manifests.append(manifest)
        indexed_non_tensor["_packed_row_manifests"] = np.asarray(
            split_manifests,
            dtype=object,
        )
    useful_rows = sum(bool(labels) for labels in owned_labels)
    ghost_rows = len(owned_labels) - useful_rows
    return expanded, indexed_non_tensor, {
        "trace_all_ce/hybrid_underfill_applied": 1.0,
        "trace_all_ce/hybrid_underfill_rows_before": float(row_count),
        "trace_all_ce/hybrid_underfill_rows_after": float(len(expanded)),
        "trace_all_ce/hybrid_underfill_block_split_rows": float(
            max(block_stage_rows - row_count, 0)
        ),
        "trace_all_ce/hybrid_underfill_label_split_rows": float(
            label_split_operations
        ),
        "trace_all_ce/hybrid_underfill_useful_dp_ranks": float(
            min(useful_rows, actor_data_parallel_size)
        ),
        "trace_all_ce/hybrid_underfill_ghost_dp_ranks": float(
            min(ghost_rows, actor_data_parallel_size)
        ),
        "trace_all_ce/hybrid_underfill_labels_before": float(
            expected_coverage.sum().item()
        ),
        "trace_all_ce/hybrid_underfill_labels_after": float(
            label_ownership.sum().item()
        ),
        "trace_all_ce/hybrid_underfill_dp_size": float(
            actor_data_parallel_size
        ),
    }


def _masked_row_to_list(tensor: torch.Tensor, mask: torch.Tensor, dtype=None):
    row = tensor[mask]
    if dtype is not None:
        row = row.to(dtype=dtype)
    return row.detach().cpu().tolist()


def _counts_by_int_value(values) -> dict[str, int]:
    counts: dict[int, int] = defaultdict(int)
    for value in values or []:
        try:
            counts[int(value)] += 1
        except (TypeError, ValueError):
            continue
    return {str(k): int(counts[k]) for k in sorted(counts)}


def _pad_tpf_training_data_for_equal_fsdp_microbatches(
    data: DataProto,
    *,
    actor_data_parallel_size: int,
    micro_batch_size_per_gpu: int,
) -> tuple[DataProto, int]:
    """Pad TPF rows without adding reward-weighted actions.

    The actor dispatch splits the selected replay batch across data-parallel
    ranks before it creates per-rank micro-batches. An uneven selected-row count
    therefore makes some ranks execute more FSDP collectives than others. The
    repeated rows retain valid action ids so their zero loss stays connected to
    the model graph, while masks and advantages make their gradient exactly zero.
    """

    actor_data_parallel_size = int(actor_data_parallel_size)
    micro_batch_size_per_gpu = int(micro_batch_size_per_gpu)
    if actor_data_parallel_size <= 0:
        raise ValueError("actor_data_parallel_size must be positive")
    if micro_batch_size_per_gpu <= 0:
        raise ValueError("micro_batch_size_per_gpu must be positive")
    if len(data) <= 0:
        raise ValueError("cannot rank-align an empty TPF training batch")
    required_keys = {
        "attention_mask",
        "tpf_action_ids",
        "tpf_action_mask",
        "tpf_row_rewards",
        "tpf_row_advantages",
        "tpf_selected_mask",
        "tpf_final_mask",
    }
    missing = sorted(required_keys.difference(data.batch.keys()))
    if missing:
        raise ValueError(f"TPF rank-aligned padding is missing batch keys: {missing}")

    real_rows = len(data)
    alignment = actor_data_parallel_size * micro_batch_size_per_gpu
    selected_action_tokens = int(data.batch["tpf_action_mask"].sum().detach().cpu().item())
    if selected_action_tokens <= 0:
        raise ValueError("TPF rank-aligned padding requires at least one selected action token")

    padded, padding_rows = pad_dataproto_to_divisor(data, alignment)
    if padding_rows:
        padding_slice = slice(real_rows, real_rows + padding_rows)
        # Keep copied action ids intact: actor forward must still build a graph
        # on ghost-only ranks. Only the objective mask/weights are neutralized.
        padded.batch["tpf_action_mask"][padding_slice].fill_(False)
        padded.batch["tpf_row_rewards"][padding_slice].zero_()
        padded.batch["tpf_row_advantages"][padding_slice].zero_()
        padded.batch["tpf_selected_mask"][padding_slice].fill_(False)
        padded.batch["tpf_final_mask"][padding_slice].fill_(False)

    padded.meta_info["tpf_actor_data_parallel_size"] = actor_data_parallel_size
    padded.meta_info["tpf_micro_batch_size_per_gpu"] = micro_batch_size_per_gpu
    padded.meta_info["tpf_real_rows"] = real_rows
    padded.meta_info["tpf_rank_padding_rows"] = padding_rows
    padded.meta_info["tpf_selected_action_tokens"] = selected_action_tokens
    padded.meta_info["global_token_num"] = padded.batch["attention_mask"].sum(dim=-1).detach().cpu().tolist()
    metrics = padded.meta_info.setdefault("metrics", {})
    metrics.update(
        {
            "diffusion_tpf_replay/rank_alignment_multiple": float(alignment),
            "diffusion_tpf_replay/rank_padding_rows": float(padding_rows),
            "diffusion_tpf_replay/actor_rows_after_padding": float(len(padded)),
        }
    )
    return padded, padding_rows


GEMMA_SELECTED_BLOCK_INDICES = "gemma_selected_block_indices"
GEMMA_AVAILABLE_BLOCK_COUNTS = "gemma_available_block_counts"
GEMMA_DENOISE_NOISE_SEEDS = "gemma_denoise_noise_seeds"


def _stable_gemma_prompt_hash(prompt_ids: torch.Tensor) -> int:
    """Return a stable, order-sensitive 63-bit hash for one unpadded prompt."""
    value = 0x14650FB0739D0383
    for token_id in prompt_ids.detach().long().cpu().tolist():
        value ^= int(token_id) & 0xFFFFFFFFFFFFFFFF
        value = (value * 0x100000001B3) & 0x7FFFFFFFFFFFFFFF
    return value


def select_gemma_denoise_blocks(
    input_ids: torch.Tensor,
    attention_mask: torch.Tensor,
    responses: torch.Tensor,
    response_mask: torch.Tensor | None,
    block_length: int,
    global_step: int,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Select one response block per prompt with deterministic step rotation."""
    if block_length <= 0:
        raise ValueError(f"DiffusionGemma block_length must be positive, got {block_length}")
    if input_ids.ndim != 2 or attention_mask.shape != input_ids.shape or responses.ndim != 2:
        raise ValueError("DiffusionGemma block selection expects rank-2, shape-aligned input tensors")
    if input_ids.shape[0] != responses.shape[0] or input_ids.shape[1] < responses.shape[1]:
        raise ValueError("DiffusionGemma input_ids must contain the complete response suffix")
    if response_mask is not None and response_mask.shape != responses.shape:
        raise ValueError("DiffusionGemma response_mask must match responses")

    response_length = int(responses.shape[-1])
    prompt_width = int(input_ids.shape[-1]) - response_length
    response_active = attention_mask[:, -response_length:].bool() & responses.ge(0)
    if response_mask is not None:
        response_active &= response_mask.bool()

    selected = torch.empty(responses.shape[0], dtype=torch.long, device=responses.device)
    available = torch.empty_like(selected)
    noise_seeds = torch.empty_like(selected)
    for row_idx in range(int(responses.shape[0])):
        prompt_ids = input_ids[row_idx, :prompt_width][attention_mask[row_idx, :prompt_width].bool()]
        valid_positions = torch.nonzero(response_active[row_idx], as_tuple=False).flatten()
        if valid_positions.numel():
            active_block_indices = torch.unique(valid_positions.div(block_length, rounding_mode="floor"))
        else:
            active_block_indices = torch.zeros(1, dtype=torch.long, device=responses.device)
        num_blocks = int(active_block_indices.numel())
        prompt_hash = _stable_gemma_prompt_hash(prompt_ids)
        block_ordinal = (prompt_hash + int(global_step)) % num_blocks
        block_index = int(active_block_indices[block_ordinal].detach().cpu().item())
        selected[row_idx] = block_index
        available[row_idx] = num_blocks
        noise_seeds[row_idx] = (
            prompt_hash
            ^ ((int(global_step) + 1) * 0x9E3779B1)
            ^ (int(block_index) * 0x85EBCA6B)
        ) & 0x7FFFFFFF

    return selected, available, noise_seeds


def gemma_selected_token_mask(
    response_active: torch.Tensor,
    selected_block_indices: torch.Tensor,
    block_length: int,
) -> torch.Tensor:
    if response_active.ndim != 2 or selected_block_indices.shape != response_active.shape[:1]:
        raise ValueError("DiffusionGemma selected block metadata does not match the response batch")
    positions = torch.arange(response_active.shape[-1], device=response_active.device)
    in_selected_block = positions.unsqueeze(0).div(block_length, rounding_mode="floor")
    in_selected_block = in_selected_block.eq(selected_block_indices.long().unsqueeze(1))
    return response_active.bool() & in_selected_block


def _summarize_rollout_step_events(events) -> dict[str, float | int]:
    if not events:
        return {}

    denoise_events = [event for event in events if isinstance(event, dict) and event.get("kind") == "jetengine_denoise"]
    prefill_events = [event for event in events if isinstance(event, dict) and event.get("kind") == "jetengine_prefill"]
    if not denoise_events:
        return {
            "prefill_forwards": len(prefill_events),
            "denoise_forwards": 0,
            "accepted_tokens_total": 0,
            "forward_tokens_total": 0,
        }

    accepted = np.asarray([event.get("accepted_tokens", 0) for event in denoise_events], dtype=float)
    forward_tokens = np.asarray([event.get("tokens", 0) for event in denoise_events], dtype=float)
    seconds = np.asarray([event.get("seconds", 0.0) for event in denoise_events], dtype=float)
    total_seconds = float(seconds.sum())
    summary: dict[str, float | int] = {
        "prefill_forwards": len(prefill_events),
        "denoise_forwards": len(denoise_events),
        "accepted_tokens_total": int(accepted.sum()),
        "forward_tokens_total": int(forward_tokens.sum()),
        "accepted_per_denoise_forward_mean": float(accepted.mean()),
        "forward_tokens_per_denoise_forward_mean": float(forward_tokens.mean()),
    }
    if total_seconds > 0:
        summary["accepted_tokens_per_second"] = float(accepted.sum() / total_seconds)
        summary["forward_tokens_per_second"] = float(forward_tokens.sum() / total_seconds)
    return summary


def _iter_sglang_sdar_metric_blocks(value):
    value = _json_safe(value)
    if value is None:
        return
    if isinstance(value, dict):
        nested = value.get("sglang_sdar_request_metrics")
        if nested is not None:
            yield from _iter_sglang_sdar_metric_blocks(nested)
        elif "denoise_forwards" in value:
            yield value
        return
    if isinstance(value, list):
        for item in value:
            yield from _iter_sglang_sdar_metric_blocks(item)


def _summarize_adaptive_confidence_rollout_diagnostics(
    sdar_metrics,
) -> dict[str, float]:
    """Aggregate actual confidence-controller values emitted by SGLang."""
    diagnostics = []
    proposal_diagnostic_steps = 0
    for block in _iter_sglang_sdar_metric_blocks(sdar_metrics) or []:
        block_diagnostics = block.get(
            "adaptive_confidence_temperature_diagnostics"
        )
        if isinstance(block_diagnostics, list):
            diagnostics.extend(
                item
                for item in block_diagnostics
                if isinstance(item, dict)
            )
        proposal_diagnostics = block.get(
            "adaptive_temperature_diagnostics"
        )
        if isinstance(proposal_diagnostics, list):
            proposal_diagnostic_steps += sum(
                isinstance(item, dict)
                for item in proposal_diagnostics
            )

    if not diagnostics:
        return {}

    prefix = "rollout/confidence_temperature"
    metrics: dict[str, float] = {
        f"{prefix}/diagnostic_steps": float(len(diagnostics)),
        f"{prefix}/proposal_adaptive_diagnostic_steps": float(
            proposal_diagnostic_steps
        ),
        f"{prefix}/reheat_count": float(
            sum(bool(item.get("reheated")) for item in diagnostics)
        ),
        f"{prefix}/adaptive_unresolved_mode_fraction": float(
            sum(
                item.get("confidence_temperature_mode")
                == "adaptive_unresolved_entropy"
                for item in diagnostics
            )
            / len(diagnostics)
        ),
        f"{prefix}/unresolved_scope_fraction": float(
            sum(
                item.get("controller_scope")
                == "unresolved_unaccepted_nonprompt"
                for item in diagnostics
            )
            / len(diagnostics)
        ),
    }

    def finite_values(key: str) -> list[float]:
        values = []
        for item in diagnostics:
            value = item.get(key)
            if value is None:
                continue
            try:
                numeric = float(value)
            except (TypeError, ValueError):
                continue
            if np.isfinite(numeric):
                values.append(numeric)
        return values

    fields = {
        "effective_confidence_temperature": "effective",
        "proposed_confidence_temperature": "proposed",
        "normalized_entropy": "normalized_entropy",
        "h_ref_normalized": "h_ref_normalized",
        "h_over_h_ref": "h_over_h_ref",
        "raw_h_over_h_ref": "raw_h_over_h_ref",
        "scope_count": "unresolved_scope_count",
        "sampling_temperature": "sampling_temperature",
    }
    for source, target in fields.items():
        values = finite_values(source)
        if not values:
            continue
        values_array = np.asarray(values, dtype=float)
        metrics[f"{prefix}/{target}_mean"] = float(
            values_array.mean()
        )
        metrics[f"{prefix}/{target}_min"] = float(values_array.min())
        metrics[f"{prefix}/{target}_max"] = float(values_array.max())
        metrics[f"{prefix}/{target}_first"] = float(values_array[0])
        metrics[f"{prefix}/{target}_last"] = float(values_array[-1])

    sampling_temperatures = finite_values("sampling_temperature")
    if sampling_temperatures:
        metrics[f"{prefix}/sampling_temperature_nonunit_count"] = float(
            sum(
                abs(value - 1.0) > 1e-8
                for value in sampling_temperatures
            )
        )
    for source, target in (
        ("accepted_count", "accepted_count_total"),
        ("new_accept_count", "new_accept_count_total"),
        ("edit_count", "edit_count_total"),
    ):
        values = finite_values(source)
        if values:
            metrics[f"{prefix}/{target}"] = float(sum(values))

    return metrics


def _sum_sglang_sdar_block_count(block: dict, block_keys: tuple[str, ...], step_key: str) -> tuple[int, bool]:
    for key in block_keys:
        if block.get(key) is None:
            continue
        try:
            return int(block.get(key) or 0), True
        except (TypeError, ValueError):
            break

    steps = block.get("steps")
    if isinstance(steps, list):
        total = 0
        found = False
        for step in steps:
            if not isinstance(step, dict) or step.get(step_key) is None:
                continue
            try:
                total += int(step.get(step_key) or 0)
                found = True
            except (TypeError, ValueError):
                continue
        if found:
            return total, True
    return 0, False


def _summarize_sglang_sdar_blocks(blocks, returned_tokens: Optional[int] = None) -> dict[str, float | int]:
    blocks = [block for block in (_iter_sglang_sdar_metric_blocks(blocks) or []) if isinstance(block, dict)]
    if not blocks:
        return {}

    denoise_forwards = int(sum(int(block.get("denoise_forwards") or 0) for block in blocks))
    commit_forwards = int(sum(int(block.get("commit_forwards") or 0) for block in blocks))
    # Post-accept refine passes are real forwards (the engine emits them per block).
    # TPF definitions (LightningRL convention): "nocommit"
    # counts only forwards that still had masks in the block (mask-to-token steps ==
    # denoise_forwards); every forward on an already-clean block -- post-accept refine
    # passes and the separate KV-commit pass -- is the "commit" side ("withcommit"
    # = denoise + refine + commit). Prompt prefill is never counted.
    refine_forwards = int(sum(int(block.get("refine_forwards") or 0) for block in blocks))
    forwards_nocommit = denoise_forwards
    block_sizes = [int(block.get("block_size") or 0) for block in blocks if int(block.get("block_size") or 0) > 0]
    true_forward_tokens = int(
        sum(
            int(block.get("true_forward_tokens") or 0)
            if block.get("true_forward_tokens") is not None
            else int(block.get("block_size") or 0) * int(block.get("denoise_forwards") or 0)
            for block in blocks
        )
    )
    generated_tokens = int(
        sum(
            int(block.get("generated_tokens", block.get("total_tokens", block.get("returned_tokens", 0))) or 0)
            for block in blocks
        )
    )
    new_accept_tokens = 0
    edit_change_tokens = 0
    new_accept_available = False
    edit_change_available = False
    for block in blocks:
        count, found = _sum_sglang_sdar_block_count(
            block,
            ("new_accept_tokens", "accepted_tokens", "new_accept_count"),
            "new_accept_count",
        )
        new_accept_tokens += count
        new_accept_available = new_accept_available or found
        count, found = _sum_sglang_sdar_block_count(
            block,
            ("edit_change_tokens", "edit_change_count"),
            "edit_change_count",
        )
        edit_change_tokens += count
        edit_change_available = edit_change_available or found
    if returned_tokens is None:
        returned_tokens = generated_tokens

    accepted_tokens = int(new_accept_tokens) if new_accept_available else int(returned_tokens)
    summary: dict[str, float | int] = {
        "blocks": len(blocks),
        "denoise_forwards": denoise_forwards,
        "refine_forwards": refine_forwards,
        "commit_forwards": commit_forwards,
        "forwards_nocommit": forwards_nocommit,
        "total_forwards": forwards_nocommit + commit_forwards,
        "accepted_tokens": accepted_tokens,
        "new_accept_tokens": int(new_accept_tokens),
        "edit_change_tokens": int(edit_change_tokens),
        "new_accept_metrics_available": int(new_accept_available),
        "edit_change_metrics_available": int(edit_change_available),
        "returned_tokens": int(returned_tokens),
        "total_tokens": generated_tokens,
        "generated_tokens": generated_tokens,
        "true_forward_tokens": true_forward_tokens,
    }
    if block_sizes:
        summary["block_size"] = int(max(set(block_sizes), key=block_sizes.count))
    if forwards_nocommit > 0:
        summary["tpf_nocommit"] = float(returned_tokens / forwards_nocommit)
    if denoise_forwards > 0:
        accepted_tpf = accepted_tokens / denoise_forwards
        summary["tpf"] = float(returned_tokens / denoise_forwards)
        summary["tpf_accepted"] = float(accepted_tpf)
        if new_accept_available:
            summary["tpf_new_accept"] = float(new_accept_tokens / denoise_forwards)
        summary["tpf_edit_change"] = float(edit_change_tokens / denoise_forwards)
        summary["tpf_returned"] = float(returned_tokens / denoise_forwards)
        summary["tpf_generated"] = float(generated_tokens / denoise_forwards)
    return summary


def _compute_response_tpf_values(
    *,
    sdar_metrics,
    response_lengths: list[int],
) -> np.ndarray:
    """Return exact returned-token TPF aligned with rollout rows."""
    if sdar_metrics is None:
        raise RuntimeError(
            "response TPF selection requires request-local sglang_sdar_metrics"
        )
    if len(sdar_metrics) != len(response_lengths):
        raise RuntimeError(
            "response TPF metadata is not aligned with rollout responses: "
            f"metrics={len(sdar_metrics)} responses={len(response_lengths)}"
        )

    response_tpf = []
    for sample_idx, (sample_metrics, response_length) in enumerate(
        zip(sdar_metrics, response_lengths, strict=True)
    ):
        summary = _summarize_sglang_sdar_blocks(
            sample_metrics,
            returned_tokens=int(response_length),
        )
        if summary.get("denoise_forwards", 0) <= 0 or summary.get("tpf") is None:
            raise RuntimeError(
                "response TPF CE scaling is missing exact denoise metadata for "
                f"sample {sample_idx}"
            )
        tpf = float(summary["tpf"])
        if not np.isfinite(tpf) or tpf < 0.0:
            raise RuntimeError(
                f"invalid response TPF for sample {sample_idx}: tpf={tpf}"
            )
        response_tpf.append(tpf)

    return np.asarray(response_tpf, dtype=np.float32)


def _compute_response_tpf_ce_scales(
    *,
    sdar_metrics,
    response_lengths: list[int],
    power: float,
    denominator: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return response TPF and absolute CE scales aligned with rollout rows."""
    power = float(power)
    denominator = float(denominator)
    if not np.isfinite(power) or power <= 0.0:
        raise ValueError(f"response TPF CE power must be finite and positive, got {power}")
    if not np.isfinite(denominator) or denominator <= 0.0:
        raise ValueError(
            "response TPF CE denominator must be finite and positive, "
            f"got {denominator}"
        )
    response_tpf = _compute_response_tpf_values(
        sdar_metrics=sdar_metrics,
        response_lengths=response_lengths,
    )
    response_scales = np.power(response_tpf, power) / denominator
    if not bool(np.isfinite(response_scales).all()):
        raise RuntimeError("response TPF CE scaling produced non-finite values")
    return (
        response_tpf,
        np.asarray(response_scales, dtype=np.float32),
    )


def _select_highest_tpf_rollout(
    quality_keep: torch.Tensor,
    response_tpf: np.ndarray,
) -> tuple[torch.Tensor, Optional[int]]:
    """Keep only the highest-TPF quality-approved rollout, with stable ties."""
    quality_keep = quality_keep.bool().view(-1)
    if quality_keep.numel() != int(response_tpf.shape[0]):
        raise RuntimeError(
            "response TPF top-1 selector alignment mismatch: "
            f"keep={quality_keep.numel()} tpf={response_tpf.shape[0]}"
        )
    selected = torch.zeros_like(quality_keep)
    candidate_indices = torch.nonzero(
        quality_keep,
        as_tuple=False,
    ).flatten()
    if candidate_indices.numel() == 0:
        return selected, None
    candidate_list = candidate_indices.tolist()
    selected_idx = max(
        candidate_list,
        key=lambda index: (float(response_tpf[index]), -int(index)),
    )
    selected[int(selected_idx)] = True
    return selected, int(selected_idx)


def _deterministic_random_replay_ids(
    *,
    positions: torch.Tensor,
    vocab_high: int,
    seed: int,
    sample_index: int,
    round_index: int,
) -> torch.Tensor:
    """Stable random-vocabulary IDs for a replay intervention."""
    vocab_high = int(vocab_high)
    if vocab_high <= 0:
        raise ValueError("random replay vocab_high must be positive")
    values = (
        (positions.to(dtype=torch.int64) + 1) * 1103515245
        + (int(sample_index) + 1) * 12345
        + (int(round_index) + 1) * 2654435761
        + int(seed)
    )
    return torch.remainder(values, vocab_high).to(dtype=torch.long)


def _replay_item_is_final_denoise_row(item: Any) -> bool:
    if not isinstance(item, dict):
        return False
    metadata = item.get("metadata")
    if not isinstance(metadata, dict):
        metadata = {}
    return bool(
        item.get(
            "is_final_denoise_row",
            metadata.get("is_final_denoise_row", False),
        )
    )


def _should_randomize_replay_page(
    *,
    mode: str,
    item: Any,
    seed: int,
    sample_index: int,
    identity_index: int,
    mixed_fraction: float,
) -> bool:
    """Choose whether one active replay page receives random token IDs."""
    mode = str(mode).strip().lower()
    if mode == "exact":
        return False
    if mode == "random_active_block":
        return True
    if _replay_item_is_final_denoise_row(item):
        return False
    if mode == "random_nonfinal_active_block":
        return True
    if mode != "mixed_exact_random_nonfinal":
        raise ValueError(f"unsupported replay input mode: {mode!r}")
    fraction = float(mixed_fraction)
    if not 0.0 <= fraction <= 1.0:
        raise ValueError(
            "mixed replay random fraction must be in [0, 1], got "
            f"{fraction}"
        )
    bucket_count = 1_000_000
    bucket = (
        (int(sample_index) + 1) * 1_103_515_245
        + (int(identity_index) + 1) * 2_654_435_761
        + (int(seed) + 1) * 12_345
    ) % bucket_count
    return bucket < int(round(fraction * bucket_count))


def _summarize_sglang_sdar_delta(delta, returned_tokens: Optional[int] = None) -> dict[str, float | int]:
    delta = _json_safe(delta)
    if not isinstance(delta, dict):
        return {}
    denoise_forwards = int(float(delta.get("denoise_forwards") or 0))
    if denoise_forwards <= 0:
        return {}
    block_size = int(float(delta.get("block_size") or 256))
    true_forward_tokens = int(float(delta.get("true_forward_tokens", block_size * denoise_forwards) or 0))
    generated_tokens = int(float(delta.get("generated_tokens", delta.get("total_tokens", 0)) or 0))
    if returned_tokens is None:
        returned_tokens = generated_tokens
    new_accept_tokens = int(float(delta.get("new_accept_tokens", delta.get("accepted_tokens", 0)) or 0))
    edit_change_tokens = int(float(delta.get("edit_change_tokens", 0) or 0))
    new_accept_available = bool(delta.get("new_accept_tokens") is not None or delta.get("accepted_tokens") is not None)
    accepted_tokens = int(new_accept_tokens) if new_accept_available else int(returned_tokens)
    _refine_forwards = int(float(delta.get("refine_forwards") or 0))
    summary: dict[str, float | int] = {
        "blocks": int(float(delta.get("commit_forwards") or 0)),
        "denoise_forwards": denoise_forwards,
        "refine_forwards": _refine_forwards,
        "forwards_nocommit": denoise_forwards,  # mask-to-token steps only
        "total_forwards": denoise_forwards + _refine_forwards + int(float(delta.get("commit_forwards") or 0)),
        "commit_forwards": int(float(delta.get("commit_forwards") or 0)),
        "accepted_tokens": accepted_tokens,
        "new_accept_tokens": int(new_accept_tokens),
        "edit_change_tokens": int(edit_change_tokens),
        "new_accept_metrics_available": int(new_accept_available),
        "edit_change_metrics_available": int(delta.get("edit_change_tokens") is not None),
        "returned_tokens": int(returned_tokens),
        "total_tokens": generated_tokens,
        "generated_tokens": generated_tokens,
        "true_forward_tokens": true_forward_tokens,
        "block_size": block_size,
        "tpf": float(returned_tokens / denoise_forwards),
        "tpf_accepted": float(accepted_tokens / denoise_forwards),
        "tpf_returned": float(returned_tokens / denoise_forwards),
        "tpf_generated": float(generated_tokens / denoise_forwards),
    }
    if new_accept_available:
        summary["tpf_new_accept"] = float(new_accept_tokens / denoise_forwards)
    summary["tpf_edit_change"] = float(edit_change_tokens / denoise_forwards)
    if summary["forwards_nocommit"] > 0:
        summary["tpf_nocommit"] = float(returned_tokens / summary["forwards_nocommit"])
    return summary


def _iter_async_capture_lifecycles(value):
    if isinstance(value, dict):
        lifecycle = value.get("async_capture_lifecycle")
        if isinstance(lifecycle, dict):
            yield lifecycle
        for nested in value.values():
            yield from _iter_async_capture_lifecycles(nested)
    elif isinstance(value, (list, tuple, np.ndarray)):
        for nested in value:
            yield from _iter_async_capture_lifecycles(nested)


def summarize_sglang_sdar_rollout_metrics(batch: DataProto, timing_raw: dict) -> dict[str, float]:
    sdar_deltas = batch.non_tensor_batch.get("sglang_sdar_stats_delta")
    sdar_metrics = batch.non_tensor_batch.get("sglang_sdar_metrics")
    if sdar_deltas is None and sdar_metrics is None:
        return {}

    response_mask = batch.batch.get("response_mask")
    per_sample_summaries = []
    # Prefer request-local block metrics. The global before/after DLLM stats
    # delta can be polluted by concurrent rollout requests on the same server.
    using_request_local_metrics = (
        sdar_metrics is not None
        and next(_iter_sglang_sdar_metric_blocks(sdar_metrics), None) is not None
    )
    if not using_request_local_metrics and sdar_deltas is None:
        return {}
    metric_prefix = "rollout/tpf" if using_request_local_metrics else "rollout/tpf/fallback_unsafe"
    source_values = sdar_metrics if using_request_local_metrics else sdar_deltas
    for i, sample_metrics in enumerate(source_values):
        returned_tokens = None
        if response_mask is not None:
            returned_tokens = int(response_mask[i].bool().sum().item())
        if using_request_local_metrics:
            summary = _summarize_sglang_sdar_blocks(sample_metrics, returned_tokens=returned_tokens)
        else:
            summary = _summarize_sglang_sdar_delta(sample_metrics, returned_tokens=returned_tokens)
        if summary:
            per_sample_summaries.append(summary)

    if not per_sample_summaries:
        return {}

    denoise_forwards = int(sum(item["denoise_forwards"] for item in per_sample_summaries))
    commit_forwards = int(sum(item["commit_forwards"] for item in per_sample_summaries))
    refine_forwards = int(sum(int(item.get("refine_forwards", 0)) for item in per_sample_summaries))
    forwards_nocommit = int(sum(int(item.get("forwards_nocommit", item["denoise_forwards"])) for item in per_sample_summaries))
    accepted_tokens = int(sum(item.get("accepted_tokens", item["returned_tokens"]) for item in per_sample_summaries))
    new_accept_tokens = int(sum(item.get("new_accept_tokens", 0) for item in per_sample_summaries))
    edit_change_tokens = int(sum(item.get("edit_change_tokens", 0) for item in per_sample_summaries))
    new_accept_available_samples = int(sum(int(item.get("new_accept_metrics_available", 0)) for item in per_sample_summaries))
    edit_change_available_samples = int(sum(int(item.get("edit_change_metrics_available", 0)) for item in per_sample_summaries))
    returned_tokens = int(sum(item["returned_tokens"] for item in per_sample_summaries))
    generated_tokens = int(sum(item["generated_tokens"] for item in per_sample_summaries))
    true_forward_tokens = int(sum(item["true_forward_tokens"] for item in per_sample_summaries))
    block_sizes = [int(item["block_size"]) for item in per_sample_summaries if "block_size" in item]

    metrics: dict[str, float] = {
        "rollout/tpf/counter_source": 0.0 if using_request_local_metrics else 1.0,
        f"{metric_prefix}/samples_with_sdar_metrics": float(len(per_sample_summaries)),
        f"{metric_prefix}/denoise_forwards_total": float(denoise_forwards),
        f"{metric_prefix}/refine_forwards_total": float(refine_forwards),
        f"{metric_prefix}/forwards_nocommit_total": float(forwards_nocommit),
        f"{metric_prefix}/commit_forwards_total": float(commit_forwards),
        f"{metric_prefix}/accepted_tokens_total": float(accepted_tokens),
        f"{metric_prefix}/new_accept_tokens_total": float(new_accept_tokens),
        f"{metric_prefix}/edit_change_tokens_total": float(edit_change_tokens),
        f"{metric_prefix}/new_accept_metrics_available_samples": float(new_accept_available_samples),
        f"{metric_prefix}/edit_change_metrics_available_samples": float(edit_change_available_samples),
        f"{metric_prefix}/returned_tokens_total": float(returned_tokens),
        f"{metric_prefix}/total_tokens_total": float(generated_tokens),
        f"{metric_prefix}/generated_tokens_total": float(generated_tokens),
        f"{metric_prefix}/true_forward_tokens_total": float(true_forward_tokens),
    }
    if not using_request_local_metrics:
        metrics[f"{metric_prefix}/counter_source"] = 1.0
    if block_sizes:
        metrics[f"{metric_prefix}/block_size"] = float(max(set(block_sizes), key=block_sizes.count))
    # ── TPF, four numbers ───────────────────────────────
    # numerator: returned tokens = the EOS-trimmed response (response_mask sum); the
    # block-padded positions after EOS in the last block are NOT counted.
    # denominators (prompt prefill never counted), LightningRL convention:
    #   nocommit    forwards that still had masks in the block = denoise_forwards
    #               (mask-to-token steps; LightningRL's num_forwards)
    #   withcommit  every forward on the response blocks = denoise + refine + commit
    #               (refine passes run on the already-clean block; under reuse_refine
    #               the first of them is what writes the block's K/V)
    # aggregations:
    #   pooled      Σ tokens / Σ forwards over the batch
    #   mean        mean over samples of tokens_i / forwards_i
    # Headline aliases: tpf = nocommit pooled, tpf_mean = nocommit mean.
    # The old denoise-only pooled value is kept as tpf_denoise_pooled.
    total_forwards_all = int(sum(int(item.get("total_forwards", item["denoise_forwards"])) for item in per_sample_summaries))
    for _tag, _den_key, _den_total in (
        ("nocommit", "forwards_nocommit", forwards_nocommit),
        ("withcommit", "total_forwards", total_forwards_all),
    ):
        if _den_total > 0:
            metrics[f"{metric_prefix}/tpf_{_tag}_pooled"] = float(returned_tokens / _den_total)
        _per = [
            float(item["returned_tokens"]) / float(item[_den_key])
            for item in per_sample_summaries
            if int(item.get(_den_key, 0) or 0) > 0
        ]
        if _per:
            metrics[f"{metric_prefix}/tpf_{_tag}_mean"] = float(sum(_per) / len(_per))
    metrics[f"{metric_prefix}/total_forwards_total"] = float(total_forwards_all)
    if f"{metric_prefix}/tpf_nocommit_pooled" in metrics:
        metrics[f"{metric_prefix}/tpf"] = metrics[f"{metric_prefix}/tpf_nocommit_pooled"]
    if f"{metric_prefix}/tpf_nocommit_mean" in metrics:
        metrics[f"{metric_prefix}/tpf_mean"] = metrics[f"{metric_prefix}/tpf_nocommit_mean"]
    if denoise_forwards > 0:
        metrics[f"{metric_prefix}/tpf_denoise_pooled"] = float(returned_tokens / denoise_forwards)
        metrics[f"{metric_prefix}/tpf_accepted"] = float(accepted_tokens / denoise_forwards)
        metrics[f"{metric_prefix}/tpf_new_accept"] = float(new_accept_tokens / denoise_forwards)
        metrics[f"{metric_prefix}/tpf_edit_change"] = float(edit_change_tokens / denoise_forwards)
        metrics[f"{metric_prefix}/tpf_returned"] = float(returned_tokens / denoise_forwards)
        metrics[f"{metric_prefix}/tpf_generated"] = float(generated_tokens / denoise_forwards)

    # ── TPF accounting matrix ─────────────────────────────────────────────────
    # Per-row quantities are at hand: the summaries carry per-sample forwards, the batch per-row masks.
    # Row order is guaranteed by the `for i, sample_metrics in enumerate(source_values)` loop above:
    # per_sample_summaries follow the batch rows, so returned_tokens is taken by index i.
    try:
        _tm_L = int(batch.batch["responses"].shape[-1])
        _tm_attn = batch.batch["attention_mask"][:, -_tm_L:]
        _tm_rows = []
        for _i, _s in enumerate(per_sample_summaries):
            if _i >= _tm_attn.shape[0]:
                break
            _cmp = int(_tm_attn[_i].bool().sum().item())
            _tm_rows.append({
                "ret": float(_s["returned_tokens"]),
                "cmp": float(_cmp),
                "dn": float(_s["denoise_forwards"]),
                "nc": float(_s.get("forwards_nocommit", _s["denoise_forwards"])),
                "tot": float(_s.get("total_forwards", _s["denoise_forwards"] + _s.get("commit_forwards", 0))),
                # Hitting the generation limit (finish_reason "length"): such rows have an inherently low TPF
                # (the answer is cut off but the forwards still run), so they must be separable.
                "crashed": _cmp >= _tm_L,
            })
        if _tm_rows:
            _n_all = len(_tm_rows)
            _n_clean = sum(1 for r in _tm_rows if not r["crashed"])
            metrics[f"{metric_prefix}_matrix/n_rows"] = float(_n_all)
            metrics[f"{metric_prefix}_matrix/n_crashed"] = float(_n_all - _n_clean)
            metrics[f"{metric_prefix}_matrix/completion_tokens_total"] = float(
                sum(r["cmp"] for r in _tm_rows))
            for _num in ("ret", "cmp"):
                for _den in ("dn", "nc", "tot"):
                    for _cl, _sel in (("all", _tm_rows),
                                      ("clean", [r for r in _tm_rows if not r["crashed"]])):
                        if not _sel:
                            continue
                        _sd = sum(r[_den] for r in _sel)
                        if _sd > 0:
                            metrics[f"{metric_prefix}_matrix/{_num}_pool_{_cl}_{_den}"] = float(
                                sum(r[_num] for r in _sel) / _sd)
                        _per = [r[_num] / r[_den] for r in _sel if r[_den] > 0]
                        if _per:
                            metrics[f"{metric_prefix}_matrix/{_num}_row_{_cl}_{_den}"] = float(
                                sum(_per) / len(_per))
            # Standard definition: returned tokens (EOS-trimmed, without the last block's
            # padding) per forward with masks (LightningRL's mask-to-token count = denoise), over all rows; pooled and per-row mean. In the matrix nc = dn =
            # without commit, tot = with commit (denoise + refine + commit); the older cmp_row_clean_dn is kept.
            _std = metrics.get(f"{metric_prefix}_matrix/ret_pool_all_nc")
            if _std is not None:
                metrics[f"{metric_prefix}_standard"] = float(_std)
            _std_mean = metrics.get(f"{metric_prefix}_matrix/ret_row_all_nc")
            if _std_mean is not None:
                metrics[f"{metric_prefix}_standard_mean"] = float(_std_mean)
    except Exception as _tm_e:  # metrics must never crash training
        metrics[f"{metric_prefix}_matrix/error"] = 1.0
        if not globals().get("_TPF_MATRIX_ERR_ANNOUNCED"):
            globals()["_TPF_MATRIX_ERR_ANNOUNCED"] = True
            print("[TPF-MATRIX] computation failed and was skipped (training unaffected): %r" % (_tm_e,), flush=True)

    per_prompt_new_accept_tpf = []
    per_prompt_returned_tpf = []
    per_prompt_generated_tpf = []
    for sample_idx, item in enumerate(per_sample_summaries):
        prefix = f"{metric_prefix}/per_prompt/{sample_idx}"
        sample_denoise_forwards = int(item["denoise_forwards"])
        sample_accepted_tokens = int(item.get("accepted_tokens", item["returned_tokens"]))
        sample_new_accept_tokens = int(item.get("new_accept_tokens", 0))
        sample_edit_change_tokens = int(item.get("edit_change_tokens", 0))
        sample_returned_tokens = int(item["returned_tokens"])
        sample_generated_tokens = int(item["generated_tokens"])
        metrics[f"{prefix}/denoise_forwards"] = float(sample_denoise_forwards)
        metrics[f"{prefix}/accepted_tokens"] = float(sample_accepted_tokens)
        metrics[f"{prefix}/new_accept_tokens"] = float(sample_new_accept_tokens)
        metrics[f"{prefix}/edit_change_tokens"] = float(sample_edit_change_tokens)
        metrics[f"{prefix}/returned_tokens"] = float(sample_returned_tokens)
        metrics[f"{prefix}/generated_tokens"] = float(sample_generated_tokens)
        metrics[f"{prefix}/new_accept_metrics_available"] = float(item.get("new_accept_metrics_available", 0))
        if sample_denoise_forwards > 0:
            accepted_tpf = float(sample_accepted_tokens / sample_denoise_forwards)
            returned_tpf = float(sample_returned_tokens / sample_denoise_forwards)
            generated_tpf = float(sample_generated_tokens / sample_denoise_forwards)
            new_accept_tpf = float(sample_new_accept_tokens / sample_denoise_forwards)
            metrics[f"{prefix}/tpf"] = returned_tpf
            metrics[f"{prefix}/tpf_accepted"] = accepted_tpf
            metrics[f"{prefix}/tpf_new_accept"] = new_accept_tpf
            metrics[f"{prefix}/tpf_edit_change"] = float(sample_edit_change_tokens / sample_denoise_forwards)
            metrics[f"{prefix}/tpf_returned"] = returned_tpf
            metrics[f"{prefix}/tpf_generated"] = generated_tpf
            per_prompt_new_accept_tpf.append(new_accept_tpf)
            per_prompt_returned_tpf.append(returned_tpf)
            per_prompt_generated_tpf.append(generated_tpf)

    if per_prompt_new_accept_tpf:
        new_accept_arr = np.asarray(per_prompt_new_accept_tpf, dtype=float)
        returned_arr = np.asarray(per_prompt_returned_tpf, dtype=float)
        generated_arr = np.asarray(per_prompt_generated_tpf, dtype=float)
        metrics[f"{metric_prefix}/per_prompt/tpf_new_accept_mean"] = float(new_accept_arr.mean())
        metrics[f"{metric_prefix}/per_prompt/tpf_new_accept_min"] = float(new_accept_arr.min())
        metrics[f"{metric_prefix}/per_prompt/tpf_new_accept_max"] = float(new_accept_arr.max())
        metrics[f"{metric_prefix}/per_prompt/tpf_returned_mean"] = float(returned_arr.mean())
        metrics[f"{metric_prefix}/per_prompt/tpf_generated_mean"] = float(generated_arr.mean())

    if sdar_metrics is not None:
        drain_wait_seconds = []
        d2h_seconds_total = []
        pack_seconds_total = []
        capture_e2e_seconds_total = []
        critical_path_blocked_seconds = []
        for sample_metrics in sdar_metrics:
            lifecycles = list(_iter_async_capture_lifecycles(sample_metrics))
            if not lifecycles:
                continue
            lifecycle = lifecycles[-1]
            if lifecycle.get("drain_wait_us") is not None:
                drain_wait_seconds.append(
                    float(lifecycle["drain_wait_us"]) / 1_000_000.0
                )
            global_capture = lifecycle.get("global")
            if not isinstance(global_capture, dict):
                continue
            process_count = float(global_capture.get("process_count", 0.0) or 0.0)
            d2h_seconds_total.append(
                process_count
                * float(global_capture.get("d2h_us_avg", 0.0) or 0.0)
                / 1_000_000.0
            )
            pack_seconds_total.append(
                process_count
                * float(global_capture.get("pack_us_avg", 0.0) or 0.0)
                / 1_000_000.0
            )
            capture_e2e_seconds_total.append(
                process_count
                * float(global_capture.get("e2e_us_avg", 0.0) or 0.0)
                / 1_000_000.0
            )
            critical_path_blocked_seconds.append(
                float(
                    global_capture.get(
                        "critical_path_blocked_us_total",
                        0.0,
                    )
                    or 0.0
                )
                / 1_000_000.0
            )
        for name, values in (
            ("drain_wait_s", drain_wait_seconds),
            ("d2h_work_s", d2h_seconds_total),
            ("pack_work_s", pack_seconds_total),
            ("consumer_e2e_work_s", capture_e2e_seconds_total),
            ("critical_path_blocked_s", critical_path_blocked_seconds),
        ):
            if values:
                arr = np.asarray(values, dtype=float)
                metrics[f"{metric_prefix}/async_capture/{name}_mean"] = float(
                    arr.mean()
                )
                metrics[f"{metric_prefix}/async_capture/{name}_max"] = float(
                    arr.max()
                )

    gen_seconds = float(timing_raw.get("gen", 0.0) or 0.0)
    if gen_seconds > 0:
        metrics[f"{metric_prefix}/true_forward_tps_gen_window"] = float(true_forward_tokens / gen_seconds)
        metrics[f"{metric_prefix}/returned_token_tps_gen_window"] = float(returned_tokens / gen_seconds)

    meta_infos = batch.non_tensor_batch.get("sglang_meta_info")
    if meta_infos is not None:
        e2e_latencies = []
        completion_tokens = []
        verl_sglang_timing: dict[str, list[float]] = {}
        for meta in meta_infos:
            meta = _json_safe(meta)
            if not isinstance(meta, dict):
                continue
            try:
                if meta.get("e2e_latency") is not None:
                    e2e_latencies.append(float(meta["e2e_latency"]))
                if meta.get("completion_tokens") is not None:
                    completion_tokens.append(float(meta["completion_tokens"]))
                for timing_key in (
                    "verl_sglang_generate_total_seconds",
                    "verl_sglang_stats_before_seconds",
                    "verl_sglang_request_build_seconds",
                    "verl_sglang_request_generate_seconds",
                    "verl_sglang_unwrap_seconds",
                    "verl_sglang_stats_after_seconds",
                    "verl_sglang_stats_diff_seconds",
                    "verl_sglang_stream_replay_enabled",
                    "verl_sglang_batch_input_ids_enabled",
                    "verl_sglang_return_logprob",
                ):
                    if meta.get(timing_key) is not None:
                        verl_sglang_timing.setdefault(timing_key, []).append(float(meta[timing_key]))
            except (TypeError, ValueError):
                continue
        if e2e_latencies:
            e2e_arr = np.asarray(e2e_latencies, dtype=float)
            metrics[f"{metric_prefix}/sglang_e2e_latency_mean"] = float(e2e_arr.mean())
            metrics[f"{metric_prefix}/sglang_e2e_latency_max"] = float(e2e_arr.max())
            if float(e2e_arr.max()) > 0:
                metrics[f"{metric_prefix}/true_forward_tps_sglang_e2e_max"] = float(
                    true_forward_tokens / e2e_arr.max()
                )
        if completion_tokens:
            metrics[f"{metric_prefix}/sglang_completion_tokens_total"] = float(sum(completion_tokens))
        for timing_key, values in verl_sglang_timing.items():
            if not values:
                continue
            arr = np.asarray(values, dtype=float)
            short_key = timing_key.replace("verl_sglang_", "verl_sglang/")
            metrics[f"{metric_prefix}/{short_key}_mean"] = float(arr.mean())
            metrics[f"{metric_prefix}/{short_key}_max"] = float(arr.max())

    if sdar_metrics is not None:
        metrics.update(
            _summarize_adaptive_confidence_rollout_diagnostics(
                sdar_metrics
            )
        )

    return metrics


def summarize_sdar_trace_map_status(batch: DataProto) -> dict[str, float]:
    statuses = batch.non_tensor_batch.get("sdar_trace_map_status")
    if statuses is None:
        return {}

    statuses = [item for item in _json_safe(statuses) if isinstance(item, dict)]
    if not statuses:
        return {}

    samples = len(statuses)
    exact_tokens = int(sum(int(item.get("exact_tokens") or 0) for item in statuses))
    synthetic_tokens = int(sum(int(item.get("synthetic_tokens") or 0) for item in statuses))
    response_tokens = int(sum(int(item.get("response_tokens") or 0) for item in statuses))
    replay_tensor_steps = int(sum(int(item.get("replay_tensor_steps") or 0) for item in statuses))
    synthetic_samples = int(sum(int(item.get("synthetic_tokens") or 0) > 0 for item in statuses))
    exact_only_samples = int(
        sum(int(item.get("exact_tokens") or 0) > 0 and int(item.get("synthetic_tokens") or 0) == 0 for item in statuses)
    )
    samples_with_replay_tensors = int(sum(bool(item.get("has_replay_tensors")) for item in statuses))

    metrics: dict[str, float] = {
        "rollout/sdar_trace_map/samples": float(samples),
        "rollout/sdar_trace_map/exact_tokens": float(exact_tokens),
        "rollout/sdar_trace_map/synthetic_tokens": float(synthetic_tokens),
        "rollout/sdar_trace_map/response_tokens": float(response_tokens),
        "rollout/sdar_trace_map/synthetic_samples": float(synthetic_samples),
        "rollout/sdar_trace_map/exact_only_samples": float(exact_only_samples),
        "rollout/sdar_trace_map/samples_with_replay_tensors": float(samples_with_replay_tensors),
        "rollout/sdar_trace_map/replay_tensor_steps": float(replay_tensor_steps),
        "rollout_corr/synthetic_sdar_step_map_invalid": 1.0 if synthetic_tokens > 0 else 0.0,
        "rollout_corr/missing_sdar_replay_tensors_invalid": 1.0
        if samples_with_replay_tensors < samples
        else 0.0,
    }
    if response_tokens > 0:
        metrics["rollout/sdar_trace_map/exact_token_frac"] = float(exact_tokens / response_tokens)
        metrics["rollout/sdar_trace_map/synthetic_token_frac"] = float(synthetic_tokens / response_tokens)
    return metrics


def summarize_rule_reward_metrics(reward_tensor: torch.Tensor, reward_extra_infos_dict: dict) -> dict[str, float]:
    metrics: dict[str, float] = {}
    if reward_tensor is not None:
        rewards = reward_tensor.detach().float().sum(dim=-1).cpu()
        if rewards.numel() > 0:
            metrics.update(
                {
                    "rule_reward/reward/mean": float(rewards.mean().item()),
                    "rule_reward/reward/max": float(rewards.max().item()),
                    "rule_reward/reward/min": float(rewards.min().item()),
                }
            )

    for key, values in (reward_extra_infos_dict or {}).items():
        try:
            arr = np.asarray(_json_safe(values), dtype=float)
        except (TypeError, ValueError):
            continue
        if arr.size == 0:
            continue
        arr = arr.reshape(-1)
        metrics[f"rule_reward/{key}/mean"] = float(arr.mean())
        metrics[f"rule_reward/{key}/max"] = float(arr.max())
        metrics[f"rule_reward/{key}/min"] = float(arr.min())
    return metrics


def apply_kl_penalty(data: DataProto, kl_ctrl: core_algos.AdaptiveKLController, kl_penalty="kl"):
    """Apply KL penalty to the token-level rewards.

    This function computes the KL divergence between the reference policy and current policy,
    then applies a penalty to the token-level rewards based on this divergence.

    Args:
        data (DataProto): The data containing batched model outputs and inputs.
        kl_ctrl (core_algos.AdaptiveKLController): Controller for adaptive KL penalty.
        kl_penalty (str, optional): Type of KL penalty to apply. Defaults to "kl".

    Returns:
        tuple: A tuple containing:
            - The updated data with token-level rewards adjusted by KL penalty
            - A dictionary of metrics related to the KL penalty
    """
    response_mask = data.batch["response_mask"]
    token_level_scores = data.batch["token_level_scores"]
    batch_size = data.batch.batch_size[0]

    # compute kl between ref_policy and current policy
    # When apply_kl_penalty, algorithm.use_kl_in_reward=True, so the reference model has been enabled.
    kld = core_algos.kl_penalty(
        data.batch["old_log_probs"], data.batch["ref_log_prob"], kl_penalty=kl_penalty
    )  # (batch_size, response_length)
    kld = kld * response_mask
    beta = kl_ctrl.value

    token_level_rewards = token_level_scores - beta * kld

    current_kl = masked_mean(kld, mask=response_mask, axis=-1)  # average over sequence
    current_kl = torch.mean(current_kl, dim=0).item()

    # according to https://github.com/huggingface/trl/blob/951ca1841f29114b969b57b26c7d3e80a39f75a0/trl/trainer/ppo_trainer.py#L837
    kl_ctrl.update(current_kl=current_kl, n_steps=batch_size)
    data.batch["token_level_rewards"] = token_level_rewards

    metrics = {"actor/reward_kl_penalty": current_kl, "actor/reward_kl_penalty_coeff": beta}

    return data, metrics


def compute_response_mask(data: DataProto):
    """Compute the attention mask for the response part of the sequence.

    This function extracts the portion of the attention mask that corresponds to the model's response,
    which is used for masking computations that should only apply to response tokens.

    Args:
        data (DataProto): The data containing batched model outputs and inputs.

    Returns:
        torch.Tensor: The attention mask for the response tokens.
    """
    responses = data.batch["responses"]
    response_length = responses.size(1)
    attention_mask = data.batch["attention_mask"]
    return attention_mask[:, -response_length:]


def compute_advantage(
    data: DataProto,
    adv_estimator: AdvantageEstimator,
    gamma: float = 1.0,
    lam: float = 1.0,
    num_repeat: int = 1,
    norm_adv_by_std_in_grpo: bool = True,
    config: Optional[AlgoConfig] = None,
) -> DataProto:
    """Compute advantage estimates for policy optimization.

    This function computes advantage estimates using various estimators like GAE, GRPO, REINFORCE++, etc.
    The advantage estimates are used to guide policy optimization in RL algorithms.

    Args:
        data (DataProto): The data containing batched model outputs and inputs.
        adv_estimator (AdvantageEstimator): The advantage estimator to use (e.g., GAE, GRPO, REINFORCE++).
        gamma (float, optional): Discount factor for future rewards. Defaults to 1.0.
        lam (float, optional): Lambda parameter for GAE. Defaults to 1.0.
        num_repeat (int, optional): Number of times to repeat the computation. Defaults to 1.
        norm_adv_by_std_in_grpo (bool, optional): Whether to normalize advantages by standard deviation in
            GRPO. Defaults to True.
        config (dict, optional): Configuration dictionary for algorithm settings. Defaults to None.

    Returns:
        DataProto: The updated data with computed advantages and returns.
    """
    # Back-compatible with trainers that do not compute response mask in fit
    # if "response_mask" not in data.batch.keys():
        # data.batch["response_mask"] =
    # prepare response group
    if adv_estimator == AdvantageEstimator.GAE:
        # Compute advantages and returns using Generalized Advantage Estimation (GAE)
        advantages, returns = core_algos.compute_gae_advantage_return(
            token_level_rewards=data.batch["token_level_rewards"],
            values=data.batch["values"],
            response_mask=data.batch["response_mask"],
            gamma=gamma,
            lam=lam,
        )
        data.batch["advantages"] = advantages
        data.batch["returns"] = returns
        if config.get("use_pf_ppo", False):
            data = core_algos.compute_pf_ppo_reweight_data(
                data,
                config.pf_ppo.get("reweight_method"),
                config.pf_ppo.get("weight_pow"),
            )
    elif adv_estimator == AdvantageEstimator.GRPO:
        # Initialize the mask for GRPO calculation
        grpo_calculation_mask = data.batch["response_mask"]

        # Call compute_grpo_outcome_advantage with parameters matching its definition
        advantages, returns = core_algos.compute_grpo_outcome_advantage(
            token_level_rewards=data.batch["token_level_rewards"],
            input_mask=grpo_calculation_mask,
            index=data.non_tensor_batch["uid"],
            response_index=data.non_tensor_batch["response_uid"],
            norm_adv_by_std_in_grpo=norm_adv_by_std_in_grpo,
        )
        data.batch["advantages"] = advantages
        data.batch["returns"] = returns
    else:
        # handle all other adv estimator type other than GAE and GRPO
        adv_estimator_fn = core_algos.get_adv_estimator_fn(adv_estimator)
        adv_kwargs = {
            "token_level_rewards": data.batch["token_level_rewards"],
            "response_mask": data.batch["response_mask"],
            "config": config,
        }
        if "uid" in data.non_tensor_batch:  # optional
            adv_kwargs["index"] = data.non_tensor_batch["uid"]
        if "reward_baselines" in data.batch:  # optional
            adv_kwargs["reward_baselines"] = data.batch["reward_baselines"]
        # Add sum_pi_squared for Optimal Token Baseline
        if adv_estimator in (AdvantageEstimator.OPTIMAL_TOKEN_BASELINE, AdvantageEstimator.TIR_OPTIMAL_TOKEN_BASELINE):
            # Check if sum_pi_squared is available
            assert "sum_pi_squared" in data.batch, (
                "Step-dependent optimal baseline requires sum_pi_squared from actor. "
                "Please set actor.calculate_sum_pi_squared=True in config."
            )
            adv_kwargs["sum_pi_squared"] = data.batch["sum_pi_squared"]
            # Get pre-computed rollout IS weights if available
            rollout_is_weights = data.batch.get("rollout_is_weights", None)
            adv_kwargs["rollout_is_weights"] = rollout_is_weights

        # calculate advantage estimator
        advantages, returns = adv_estimator_fn(**adv_kwargs)
        data.batch["advantages"] = advantages
        data.batch["returns"] = returns
    return data


class NodeLocalT5Consumer:
    """Consume split replay on the same node as rollout and actor workers."""

    def __init__(
        self,
        *,
        config: Any,
        pad_token_id: int,
        eos_token_id: int = 0,
        actor_world_size: int = 1,
        queue: Any,
        actor_workers: list[Any],
        worker_call_info: dict[str, Any] | None = None,
        chunk_size: int,
        pull_max_items: int,
        flush_timeout_ms: int = 0,
        max_inflight_chunks: int = 1,
        global_step: int,
        store: str = "shm",
        node_label: str = "",
    ):
        self.config = config
        self.pad_token_id = int(pad_token_id)
        self.queue = queue
        self.actor_workers = list(actor_workers)
        self.worker_call_info = dict(worker_call_info or {})
        self.chunk_size = max(1, int(chunk_size or 64))
        self.pull_max_items = max(1, int(pull_max_items or 8))
        self.flush_timeout_seconds = max(0.0, float(flush_timeout_ms or 0) / 1000.0)
        self.max_inflight_chunks = max(1, int(max_inflight_chunks or 1))
        self.global_step = int(global_step or 0)
        self.store = str(store or "shm").strip().lower()
        self.node_label = str(node_label or "")
        self._helper = object.__new__(RayPPOTrainer)
        self._helper.config = config
        self._helper.global_steps = self.global_step
        self._helper.tokenizer = type(
            "_NodeLocalTokenizer",
            (),
            {"pad_token_id": self.pad_token_id, "eos_token_id": int(eos_token_id)},
        )()
        # actor_world_size must be GLOBAL dp size, not len(actor_workers): dispatch sharding
        # uses len(local actor_workers) at _submit_local_chunk, but row-count and lease
        # sharding (:19216/:19418) read actor_rollout_wg.world_size.
        self._helper.actor_rollout_wg = types.SimpleNamespace(world_size=int(actor_world_size))
        if RayPPOTrainer._replay_row_manifest_enabled():
            # Per-consumer manifest path with node_label suffix enables row-level parity diffs.
            node_manifest = os.path.join(
                os.path.dirname(RayPPOTrainer._replay_row_manifest_path(self._helper)),
                f"replay_row_manifest_{self.node_label}.jsonl",
            )
            self._helper._replay_row_manifest_path = lambda _nl=node_manifest: _nl
        else:
            self._helper._replay_row_manifest_enabled = lambda: False
            self._helper._dump_replay_row_manifest = lambda *args, **kwargs: None

    @staticmethod
    def _metric_float(metrics: dict[str, Any], key: str) -> float:
        value = metrics.get(key, 0.0) if isinstance(metrics, dict) else 0.0
        if torch.is_tensor(value):
            value = value.detach().cpu().reshape(-1)[0].item() if value.numel() else 0.0
        try:
            return float(value)
        except (TypeError, ValueError):
            return 0.0

    @staticmethod
    def _merge_actor_metrics(results: Any) -> dict[str, float]:
        merged: dict[str, float] = {}
        if not isinstance(results, list):
            results = [results]
        for result in results:
            if isinstance(result, DataProto):
                metrics = result.meta_info.get("metrics", {})
            elif isinstance(result, dict):
                metrics = result
            else:
                metrics = {}
            for key, value in dict(metrics or {}).items():
                numeric = NodeLocalT5Consumer._metric_float(metrics, key)
                merged[key] = merged.get(key, 0.0) + numeric
        return merged

    def _send_local_chunk(
        self, tensor_chunk: dict[str, torch.Tensor], chunk_idx: int
    ) -> tuple[dict[str, float], float, int]:
        """Shard and dispatch *tensor_chunk* to local actor ranks.

        Returns (actor_metrics, submit_seconds, chunk_bytes).
        chunk_bytes is the unsharded total byte count — a proxy for the
        cross-node bytes that would have been transferred in the central path.
        """
        record = self._submit_local_chunk(tensor_chunk, chunk_idx)
        metrics, _ = self._drain_local_chunk(record)
        return metrics, float(record.get("submit_seconds", 0.0) or 0.0), int(record.get("chunk_bytes", 0) or 0)

    def _submit_local_chunk(self, tensor_chunk: dict[str, torch.Tensor], chunk_idx: int) -> dict[str, Any]:
        """Shard and submit *tensor_chunk* to local actor ranks without waiting."""
        chunk_bytes = RayPPOTrainer._estimate_tensor_chunk_bytes(tensor_chunk)
        # SP members of a DP group must cooperate on the SAME rows (each holds
        # half the tokens); sharding per WORKER handed SP partners different
        # rows, silently desyncing every SP collective (chunk-idx markers
        # showed a rank reducing chunk 0 against a partner on chunk ~137).
        # Shard per DP GROUP and broadcast each shard to all SP members.
        sp_size = 1
        if self.config is not None:
            sp_size = int(
                self.config.actor_rollout_ref.actor.get(
                    "ulysses_sequence_parallel_size", 1
                )
                or 1
            )
        sp_size = max(1, sp_size)
        if len(self.actor_workers) % sp_size != 0:
            raise RuntimeError(
                "node-local dispatch requires actor worker count divisible by "
                f"ulysses SP size: {len(self.actor_workers)} vs sp={sp_size}"
            )
        num_groups = len(self.actor_workers) // sp_size
        shards = self._helper._split_t5_tensor_chunk_for_actor_dp(tensor_chunk, num_groups)
        payloads = []
        send_records = []
        submit_start = time.perf_counter()
        submit_wall_ts = time.time()
        try:
            for shard in shards:
                shard = dict(shard)
                shard["_node_local_submit_wall_ts"] = torch.tensor([submit_wall_ts], dtype=torch.float64)
                member_payloads = []
                for _member_idx in range(sp_size):
                    if self.store in {"shm", "shared_memory"}:
                        payload, record = self._helper._build_t5_tensor_chunk_shm_payload(dict(shard))
                        send_records.append(record)
                        member_payloads.append(payload)
                    else:
                        member_payloads.append(shard)
                payloads.append(member_payloads)
            refs = [
                self._execute_actor_worker(
                    self.actor_workers[group_idx * sp_size + member_idx],
                    "node_local_consume_t5_tensor_chunk",
                    group_payloads[member_idx],
                    chunk_idx=chunk_idx,
                )
                for group_idx, group_payloads in enumerate(payloads)
                for member_idx in range(sp_size)
            ]
        except Exception:
            for record in send_records:
                RayPPOTrainer._unlink_t5_tensor_chunk_shm_payload(record.get("shm_payload"))
            raise
        submit_seconds = time.perf_counter() - submit_start
        return {
            "refs": refs,
            "send_records": send_records,
            "submit_start": submit_start,
            "submit_seconds": submit_seconds,
            "chunk_bytes": chunk_bytes,
            "chunk_idx": int(chunk_idx),
            "rows": int(tensor_chunk["input_ids"].shape[0]),
            "active_tokens": self._helper._count_t5_replay_active_tokens(tensor_chunk),
        }

    def _drain_local_chunk(self, record: dict[str, Any]) -> tuple[dict[str, float], float]:
        try:
            results = ray.get(record["refs"])
            metrics = self._merge_actor_metrics(results)
            actor_queue_values = []
            result_list = results if isinstance(results, list) else [results]
            for result in result_list:
                if isinstance(result, DataProto):
                    result_metrics = result.meta_info.get("metrics", {})
                elif isinstance(result, dict):
                    result_metrics = result
                else:
                    result_metrics = {}
                actor_queue_values.append(
                    self._metric_float(result_metrics, "actor/t5_tensor_replay/actor_method_queue_seconds")
                )
            if actor_queue_values:
                metrics["actor/t5_tensor_replay/actor_method_queue_seconds_max"] = max(actor_queue_values)
                metrics["actor/t5_tensor_replay/actor_method_queue_calls"] = float(len(actor_queue_values))
            total_seconds = time.perf_counter() - float(record.get("submit_start", time.perf_counter()))
            result_wait_seconds = max(0.0, total_seconds - float(record.get("submit_seconds", 0.0) or 0.0))
            return metrics, result_wait_seconds
        finally:
            for send_record in record.get("send_records", []) or []:
                RayPPOTrainer._unlink_t5_tensor_chunk_shm_payload(send_record.get("shm_payload"))

    def _execute_actor_worker(self, worker: Any, method_name: str, *args, **kwargs):
        method_names = set(self.worker_call_info.get("method_names") or [])
        fused_worker_used = bool(self.worker_call_info.get("fused_worker_used", False))
        sub_cls_name = str(self.worker_call_info.get("sub_cls_name") or "")
        candidates = [method_name]
        for prefix in (sub_cls_name, "actor_rollout", "actor"):
            if prefix:
                candidates.append(f"{prefix}_{method_name}")
        for exposed_name in method_names:
            if exposed_name == method_name or exposed_name.endswith(f"_{method_name}"):
                candidates.append(exposed_name)

        seen = set()
        for candidate in candidates:
            if candidate in seen:
                continue
            seen.add(candidate)
            try:
                remote_call = getattr(worker, candidate)
                return remote_call.remote(*args, **kwargs)
            except AttributeError:
                continue

        if fused_worker_used:
            execute_fn_name = str(self.worker_call_info.get("fused_worker_execute_fn_name") or "_fuw_execute")
            try:
                remote_call = getattr(worker, execute_fn_name)
                target = f"{sub_cls_name or 'actor'}_fwmn_{method_name}"
                return remote_call.remote(target, *args, **kwargs)
            except AttributeError:
                pass
        raise AttributeError(
            f"Could not execute actor worker method {method_name}; "
            f"tried={list(seen)} fused={fused_worker_used} sub_cls={sub_cls_name}"
        )

    def run(self) -> dict[str, Any]:
        state: dict[str, Any] = {
            "node_label": self.node_label,
            "queue_items": 0,
            "chunks": 0,
            "rows": 0,
            "active_tokens": 0,
            "actor_rpc_submit_seconds": 0.0,
            "actor_rpc_result_wait_seconds": 0.0,
            "actor_t5_forward_seconds": 0.0,
            "actor_t5_backward_seconds": 0.0,
            "actor_t5_chunk_total_seconds": 0.0,
            "actor_method_queue_seconds": 0.0,
            "actor_method_queue_seconds_max": 0.0,
            "actor_method_queue_calls": 0.0,
            "direct_compact_rows": 0,
            "direct_compact_active_tokens": 0,
            # Bytes of full (unsharded) tensor chunks dispatched locally —
            # these would have crossed node boundaries in the central consumer.
            "node_local_cross_node_tensor_bytes_avoided": 0,
            "node_local_actor_rpc_submit_calls": 0,
            "node_local_actor_rpc_submit_seconds": 0.0,
            "node_local_actor_rpc_result_wait_calls": 0,
            "node_local_actor_rpc_result_wait_seconds": 0.0,
            "node_local_build_t5_batch_seconds": 0.0,
            "node_local_actor_shm_bytes": 0,
            "node_local_actor_shm_create_seconds": 0.0,
            "node_local_actor_shm_create_seconds_max": 0.0,
            "queue_item_wait_seconds": 0.0,
            "queue_item_wait_seconds_max": 0.0,
            "queue_item_count_with_timing": 0,
            "stream_consumer_raw_pop_many_seconds": 0.0,
            "stream_consumer_raw_queue_wait_seconds": 0.0,
            "stream_consumer_extract_seconds": 0.0,
            "stream_consumer_table_fetch_seconds": 0.0,
            "stream_consumer_materialize_seconds": 0.0,
            "stream_consumer_merge_filter_seconds": 0.0,
            "stream_consumer_direct_build_seconds": 0.0,
            "stream_consumer_item_process_pre_push_seconds": 0.0,
            "stream_consumer_trainer_queue_enqueue_seconds": 0.0,
            "stream_consumer_trainer_queue_enqueue_seconds_max": 0.0,
            "stream_consumer_trainer_queue_enqueue_count": 0,
            "sglang_stream_replay_compact_seconds": 0.0,
            "sglang_stream_replay_shm_seconds": 0.0,
            "sglang_stream_pre_queue_seconds": 0.0,
            "sglang_stream_replay_items": 0,
            "sglang_stream_chunk_output_tokens": 0,
            "flush_timeout_ms": float(self.flush_timeout_seconds * 1000.0),
            "flush_count": 0,
            "flush_by_rows": 0,
            "flush_by_timeout": 0,
            "flush_by_close": 0,
            "flush_wait_seconds": 0.0,
            "max_inflight_chunks": float(self.max_inflight_chunks),
            "inflight_max": 0,
            "inflight_drains": 0,
        }
        delta_teacher_cache: dict[str, dict[int, dict[str, Any]]] = {}
        pending_direct_items: list[dict[str, Any]] = []
        pending_started_at: float | None = None
        inflight: list[dict[str, Any]] = []
        # Hold-until-tail buffer: mid-stream items (no acc) keyed by stream_cache_key;
        # released when the tail item (with acc) arrives for the same key.
        held: dict[str, list[dict[str, Any]]] = {}

        def _drain_one_inflight() -> None:
            if not inflight:
                return
            record = inflight.pop(0)
            metrics, result_wait_seconds = self._drain_local_chunk(record)
            rows = int(record.get("rows", 0) or 0)
            active_tokens = int(record.get("active_tokens", 0) or 0)
            chunk_bytes = int(record.get("chunk_bytes", 0) or 0)
            submit_seconds = float(record.get("submit_seconds", 0.0) or 0.0)
            send_records = record.get("send_records", []) or []
            shm_bytes = sum(int(item.get("shm_bytes", 0) or 0) for item in send_records if isinstance(item, dict))
            shm_create_seconds = sum(
                float(item.get("shm_create_seconds", 0.0) or 0.0)
                for item in send_records
                if isinstance(item, dict)
            )
            state["actor_rpc_submit_seconds"] += submit_seconds
            state["actor_rpc_result_wait_seconds"] += result_wait_seconds
            state["actor_t5_forward_seconds"] += self._metric_float(metrics, "actor/t5_tensor_replay/forward_seconds")
            state["actor_t5_backward_seconds"] += self._metric_float(metrics, "actor/t5_tensor_replay/backward_seconds")
            state["actor_t5_chunk_total_seconds"] += self._metric_float(
                metrics,
                "actor/t5_tensor_replay/chunk_total_seconds",
            )
            actor_method_queue_seconds = self._metric_float(
                metrics,
                "actor/t5_tensor_replay/actor_method_queue_seconds",
            )
            state["actor_method_queue_seconds"] += actor_method_queue_seconds
            state["actor_method_queue_seconds_max"] = max(
                float(state.get("actor_method_queue_seconds_max", 0.0) or 0.0),
                self._metric_float(metrics, "actor/t5_tensor_replay/actor_method_queue_seconds_max"),
            )
            state["actor_method_queue_calls"] += self._metric_float(
                metrics,
                "actor/t5_tensor_replay/actor_method_queue_calls",
            )
            state["node_local_cross_node_tensor_bytes_avoided"] += chunk_bytes
            state["node_local_actor_shm_bytes"] += shm_bytes
            state["node_local_actor_shm_create_seconds"] += shm_create_seconds
            state["node_local_actor_shm_create_seconds_max"] = max(
                float(state.get("node_local_actor_shm_create_seconds_max", 0.0) or 0.0),
                max(
                    [
                        float(item.get("shm_create_seconds", 0.0) or 0.0)
                        for item in send_records
                        if isinstance(item, dict)
                    ]
                    or [0.0]
                ),
            )
            state["node_local_actor_rpc_submit_calls"] += len(self.actor_workers)
            state["node_local_actor_rpc_submit_seconds"] += submit_seconds
            state["node_local_actor_rpc_result_wait_calls"] += 1
            state["node_local_actor_rpc_result_wait_seconds"] += result_wait_seconds
            state["chunks"] += 1
            state["rows"] += rows
            state["active_tokens"] += active_tokens
            state["inflight_drains"] += 1

        def _submit_inflight(tensor_chunk: dict[str, torch.Tensor], chunk_idx: int) -> None:
            while len(inflight) >= self.max_inflight_chunks:
                _drain_one_inflight()
            inflight.append(self._submit_local_chunk(tensor_chunk, chunk_idx))
            state["inflight_max"] = max(int(state.get("inflight_max", 0) or 0), len(inflight))

        def _pending_rows() -> int:
            total = 0
            for payload in pending_direct_items:
                try:
                    total += int(payload.get("source_replay_rows", payload.get("rows", 0)) or 0)
                except (TypeError, ValueError):
                    pass
            return total

        def _flush_pending(reason: str) -> None:
            nonlocal pending_started_at
            if not pending_direct_items:
                pending_started_at = None
                return
            flush_wait = time.perf_counter() - pending_started_at if pending_started_at is not None else 0.0
            direct_items = list(pending_direct_items)
            pending_direct_items.clear()
            pending_started_at = None
            state["flush_count"] += 1
            state["flush_wait_seconds"] += max(0.0, flush_wait)
            if reason == "rows":
                state["flush_by_rows"] += 1
            elif reason == "timeout":
                state["flush_by_timeout"] += 1
            elif reason == "close":
                state["flush_by_close"] += 1
            build_batch_start = time.perf_counter()
            try:
                tensor_batch, direct_metrics = self._helper._build_direct_compact_streaming_t5_tensor_batch(
                    direct_items,
                    delta_teacher_cache=delta_teacher_cache,
                )
            except _ZeroSignalGRPOBatch as exc:
                state["node_local_build_t5_batch_seconds"] += time.perf_counter() - build_batch_start
                for key, value in exc.metrics.items():
                    zkey = f"zero_signal/{key}"
                    state[zkey] = float(state.get(zkey, 0.0)) + float(value)
                state["zero_signal_flushes"] = int(state.get("zero_signal_flushes", 0)) + 1
                return
            state["node_local_build_t5_batch_seconds"] += time.perf_counter() - build_batch_start
            state["direct_compact_rows"] += int(round(float(direct_metrics.get("rows", 0.0) or 0.0)))
            state["direct_compact_active_tokens"] += int(round(float(direct_metrics.get("active_tokens", 0.0) or 0.0)))
            for tensor_chunk in self._helper._iter_t5_replay_tensor_chunks(tensor_batch, self.chunk_size):
                chunk_idx = int(state["chunks"]) + len(inflight)
                _submit_inflight(tensor_chunk, chunk_idx)

        while True:
            if not pending_direct_items and len(inflight) >= self.max_inflight_chunks:
                _drain_one_inflight()
            pop_timeout = self.flush_timeout_seconds if pending_direct_items and self.flush_timeout_seconds > 0 else None
            items = ray.get(self.queue.pop_many.remote(self.pull_max_items, pop_timeout))
            if items is None:
                if held:
                    orphans = {k: len(v) for k, v in held.items()}
                    raise RuntimeError(
                        f"NodeLocalT5Consumer closed with {len(orphans)} orphaned "
                        f"hold group(s) — tail item never arrived for these "
                        f"stream_cache_keys: {orphans}. This means a producer pushed "
                        "mid-stream items but never pushed the corresponding tail item."
                    )
                _flush_pending("close")
                while inflight:
                    _drain_one_inflight()
                break
            if not items:
                _flush_pending("timeout")
                continue
            direct_items = []
            for queue_item in items:
                push_ts = float(queue_item.get("push_ts", 0.0) or 0.0)
                payload = queue_item.get("item")
                if push_ts > 0.0:
                    queue_item_wait = max(0.0, time.time() - push_ts)
                    state["queue_item_wait_seconds"] += queue_item_wait
                    state["queue_item_wait_seconds_max"] = max(
                        float(state.get("queue_item_wait_seconds_max", 0.0) or 0.0),
                        queue_item_wait,
                    )
                    state["queue_item_count_with_timing"] += 1
                    if isinstance(payload, dict):
                        enqueue_start_ts = float(
                            payload.get("stream_consumer_trainer_queue_push_start_wall_ts", 0.0) or 0.0
                        )
                        if enqueue_start_ts > 0.0:
                            enqueue_seconds = max(0.0, push_ts - enqueue_start_ts)
                            state["stream_consumer_trainer_queue_enqueue_seconds"] += enqueue_seconds
                            state["stream_consumer_trainer_queue_enqueue_seconds_max"] = max(
                                float(
                                    state.get("stream_consumer_trainer_queue_enqueue_seconds_max", 0.0)
                                    or 0.0
                                ),
                                enqueue_seconds,
                            )
                            state["stream_consumer_trainer_queue_enqueue_count"] += 1
                if isinstance(payload, dict):
                    for metric_name in (
                        "stream_consumer_raw_pop_many_seconds",
                        "stream_consumer_raw_queue_wait_seconds",
                        "stream_consumer_extract_seconds",
                        "stream_consumer_table_fetch_seconds",
                        "stream_consumer_materialize_seconds",
                        "stream_consumer_merge_filter_seconds",
                        "stream_consumer_direct_build_seconds",
                        "stream_consumer_item_process_pre_push_seconds",
                        "sglang_stream_replay_compact_seconds",
                        "sglang_stream_replay_shm_seconds",
                        "sglang_stream_pre_queue_seconds",
                    ):
                        state[metric_name] += float(payload.get(metric_name, 0.0) or 0.0)
                    state["sglang_stream_replay_items"] += int(
                        payload.get("sglang_stream_replay_items", 0) or 0
                    )
                    state["sglang_stream_chunk_output_tokens"] += int(
                        payload.get("sglang_stream_chunk_output_tokens", 0) or 0
                    )
                if isinstance(payload, dict) and payload.get("format") == "split_sdar_direct_compact_v1":
                    if payload.get("closer_only"):
                        # Row-less acc closer (producer had mid-stream items but no
                        # trainable tail): stamp+release held siblings, never train
                        # on the closer itself. Without acc the sample is unscorable
                        # — drop the held group loudly rather than poison labels.
                        key = payload.get("stream_cache_key")
                        acc_val = payload.get("acc")
                        if acc_val is None:
                            dropped = len(held.pop(key, [])) if key else 0
                            print(
                                "[SplitStreaming] sdar_stream_closer_without_acc "
                                f"key={key} dropped_held={dropped}",
                                flush=True,
                            )
                        elif key and key in held:
                            meta_val = payload.get("sglang_meta_info") or {}
                            for held_item in held[key]:
                                held_item["acc"] = acc_val
                                held_meta = held_item.get("sglang_meta_info")
                                if not held_meta:
                                    held_item["sglang_meta_info"] = meta_val
                                elif (
                                    isinstance(held_meta, dict)
                                    and isinstance(meta_val, dict)
                                    and normalize_finish_reason(held_meta) is None
                                ):
                                    # Mid-stream chunk meta carries finish_reason=None
                                    # until the stream ends (SGLang convention); take
                                    # the closer/tail's finish explicitly, keep the
                                    # held item's other fields.
                                    merged_meta = {**meta_val, **held_meta}
                                    if normalize_finish_reason(merged_meta) is None:
                                        merged_meta["finish_reason"] = meta_val.get("finish_reason")
                                    held_item["sglang_meta_info"] = merged_meta
                            direct_items.extend(held.pop(key))
                    elif payload.get("acc") is None:
                        # Mid-stream item (no acc yet): hold until tail arrives with acc.
                        key = payload.get("stream_cache_key")
                        if not key:
                            raise RuntimeError(
                                "NodeLocalT5Consumer received a mid-stream direct item "
                                "(acc=None) with no stream_cache_key — it can never be "
                                "released at tail. Disable SGLANG_SDAR_REPLAY_EARLY_STREAM "
                                "or ensure every mid-stream item carries a stream_cache_key."
                            )
                        held.setdefault(key, []).append(payload)
                    else:
                        # Tail or single-chunk item with acc — release any held siblings first.
                        key = payload.get("stream_cache_key")
                        if key and key in held:
                            acc_val = payload["acc"]
                            meta_val = payload.get("sglang_meta_info") or {}
                            for held_item in held[key]:
                                held_item["acc"] = acc_val
                                held_meta = held_item.get("sglang_meta_info")
                                if not held_meta:
                                    held_item["sglang_meta_info"] = meta_val
                                elif (
                                    isinstance(held_meta, dict)
                                    and isinstance(meta_val, dict)
                                    and normalize_finish_reason(held_meta) is None
                                ):
                                    # Mid-stream chunk meta carries finish_reason=None
                                    # until the stream ends (SGLang convention); take
                                    # the closer/tail's finish explicitly, keep the
                                    # held item's other fields.
                                    merged_meta = {**meta_val, **held_meta}
                                    if normalize_finish_reason(merged_meta) is None:
                                        merged_meta["finish_reason"] = meta_val.get("finish_reason")
                                    held_item["sglang_meta_info"] = merged_meta
                            direct_items.extend(held.pop(key))
                        direct_items.append(payload)
                elif isinstance(payload, dict) and payload.get("format") == "split_sdar_stream_metrics_v1":
                    self._helper._accumulate_split_streaming_source_metrics(
                        state, payload, path="summary"
                    )
                elif isinstance(payload, DataProto):
                    # Search for fallback reason in meta_info, then non_tensor_batch, then extra.
                    fallback_reason = getattr(payload.meta_info, "get", lambda k, d=None: d)(
                        "direct_compact_fallback_reason", None
                    )
                    if fallback_reason is None:
                        ntb = getattr(payload, "non_tensor_batch", None) or {}
                        ntb_col = ntb.get("direct_compact_fallback_reason") if isinstance(ntb, dict) else None
                        if ntb_col is not None and len(ntb_col) > 0:
                            fallback_reason = ntb_col[0]
                    if fallback_reason is None:
                        extra = getattr(payload, "extra", None) or {}
                        fallback_reason = (
                            extra.get("direct_compact_fallback_reason")
                            if isinstance(extra, dict)
                            else None
                        )
                    if fallback_reason is None:
                        fallback_reason = "unknown"
                    raise RuntimeError(
                        f"NodeLocalT5Consumer received a legacy DataProto payload "
                        f"(producer fell back from direct-compact; reason={fallback_reason!r}). "
                        "This indicates silent row attrition — fix or explicitly port the "
                        "fallback path before enabling the node-local consumer."
                    )
                else:
                    state["unclassified_payloads"] = int(state.get("unclassified_payloads", 0)) + 1
            state["queue_items"] += len(items)
            if not direct_items:
                continue
            if pending_started_at is None:
                pending_started_at = time.perf_counter()
            pending_direct_items.extend(direct_items)
            pending_rows = _pending_rows()
            pending_age = time.perf_counter() - pending_started_at if pending_started_at is not None else 0.0
            if pending_rows >= self.chunk_size:
                _flush_pending("rows")
            elif self.flush_timeout_seconds > 0 and pending_age >= self.flush_timeout_seconds:
                _flush_pending("timeout")
        unclassified = int(state.get("unclassified_payloads", 0))
        if unclassified > 0:
            raise RuntimeError(
                f"NodeLocalT5Consumer received {unclassified} unclassified queue payload(s). "
                "Each must be either split_sdar_direct_compact_v1, split_sdar_stream_metrics_v1, "
                "or a DataProto. Unclassified payloads indicate an unexpected producer format."
            )
        return state

# Running count of steps in which no AEC page intersects a trainable position.
_AEC_NO_TRAINABLE_SKIP_COUNT = 0


class RayPPOTrainer:
    """Distributed PPO trainer using Ray for scalable reinforcement learning.

    This trainer orchestrates distributed PPO training across multiple nodes and GPUs,
    managing actor rollouts, critic training, and reward computation with Ray backend.
    Supports various model architectures including FSDP, Megatron, vLLM, and SGLang integration.
    """

    _ACTOR_REPLAY_STATE_KEYS = (
        "rollout_self_conditioning_signal",
        "rollout_logits_source_hidden",
        "rollout_self_conditioning_signal_block_values",
        "rollout_self_conditioning_signal_block_rows",
        "rollout_self_conditioning_signal_block_starts",
        "rollout_self_conditioning_signal_block_lengths",
        "rollout_logits_source_hidden_block_values",
        "rollout_logits_source_hidden_block_rows",
        "rollout_logits_source_hidden_block_starts",
        "rollout_logits_source_hidden_block_lengths",
    )
    _T5_REPLAY_TENSOR_KEYS = (
        "responses",
        "response_mask",
        "input_ids",
        "attention_mask",
        "position_ids",
        "rollout_self_conditioning_signal",
        "rollout_logits_source_hidden",
        "rollout_self_conditioning_signal_block_values",
        "rollout_self_conditioning_signal_block_rows",
        "rollout_self_conditioning_signal_block_starts",
        "rollout_self_conditioning_signal_block_lengths",
        "rollout_logits_source_hidden_block_values",
        "rollout_logits_source_hidden_block_rows",
        "rollout_logits_source_hidden_block_starts",
        "rollout_logits_source_hidden_block_lengths",
        "rollout_quality_mask",
        "response_level_ce_token_count",
        "response_level_aec_pair_count",
        "adjacent_entropy_pair_mask",
        "adjacent_entropy_pair_ids",
        "adjacent_entropy_prev_mean",
        "adjacent_entropy_pair_local_step",
        "adjacent_entropy_rollout_next_mean",
        "adjacent_entropy_vocab_size",
        "_packed_row_cost",
    )
    _T5_SPARSE_LOGITS_SOURCE_KEYS = (
        "rollout_logits_source_hidden_sparse_values",
        "rollout_logits_source_hidden_sparse_rows",
        "rollout_logits_source_hidden_sparse_positions",
        "rollout_logits_source_hidden_sparse_shape",
    )
    _T5_TENSOR_CHUNK_SHM_FORMAT = "split_streaming_t5_tensor_chunk_shm_v1"
    _ACTOR_T5_REPLAY_SECONDS_METRICS = (
        ("actor/t5_tensor_replay/h2d_seconds", "actor_t5_h2d"),
        ("actor/t5_tensor_replay/forward_seconds", "actor_t5_forward"),
        ("actor/t5_tensor_replay/loss_prep_seconds", "actor_t5_loss_prep"),
        ("actor/t5_tensor_replay/backward_seconds", "actor_t5_backward"),
        ("actor/t5_tensor_replay/empty_cache_seconds", "actor_t5_empty_cache"),
        ("actor/t5_tensor_replay/chunk_total_seconds", "actor_t5_chunk_total"),
    )

    # TODO: support each role have individual ray_worker_group_cls,
    # i.e., support different backend of different role
    def __init__(
        self,
        config,
        tokenizer,
        role_worker_mapping: dict[Role, WorkerType],
        resource_pool_manager: ResourcePoolManager,
        ray_worker_group_cls: type[RayWorkerGroup] = RayWorkerGroup,
        processor=None,
        train_dataset: Optional[Dataset] = None,
        val_dataset: Optional[Dataset] = None,
        collate_fn=None,
        train_sampler: Optional[Sampler] = None,
        device_name=None,
    ):
        """
        Initialize distributed PPO trainer with Ray backend.
        Note that this trainer runs on the driver process on a single CPU/GPU node.

        Args:
            config: Configuration object containing training parameters.
            tokenizer: Tokenizer used for encoding and decoding text.
            role_worker_mapping (dict[Role, WorkerType]): Mapping from roles to worker classes.
            resource_pool_manager (ResourcePoolManager): Manager for Ray resource pools.
            ray_worker_group_cls (RayWorkerGroup, optional): Class for Ray worker groups. Defaults to RayWorkerGroup.
            processor: Optional data processor, used for multimodal data
            train_dataset (Optional[Dataset], optional): Training dataset. Defaults to None.
            val_dataset (Optional[Dataset], optional): Validation dataset. Defaults to None.
            collate_fn: Function to collate data samples into batches.
            train_sampler (Optional[Sampler], optional): Sampler for the training dataset. Defaults to None.
            device_name (str, optional): Device name for training (e.g., "cuda", "cpu"). Defaults to None.
        """

        # Store the tokenizer for text processing
        self.tokenizer = tokenizer
        self.processor = processor
        self.config = config

        self.hybrid_engine = config.actor_rollout_ref.hybrid_engine
        assert self.hybrid_engine, "Currently, only support hybrid engine"

        if self.hybrid_engine:
            assert Role.ActorRollout in role_worker_mapping or Role.ActorRolloutRef in role_worker_mapping, (
                f"{role_worker_mapping.keys()=}"
            )

        self.role_worker_mapping = role_worker_mapping
        self.resource_pool_manager = resource_pool_manager
        self.use_reference_policy = need_reference_policy(self.config)

        self.use_rm = need_reward_model(self.config)

        self.use_critic = need_critic(self.config)
        self.ray_worker_group_cls = ray_worker_group_cls
        self.device_name = device_name if device_name else self.config.trainer.device
        self.validation_generations_logger = ValidationGenerationsLogger(
            project_name=self.config.trainer.project_name,
            experiment_name=self.config.trainer.experiment_name,
        )

        # if ref_in_actor is True, the reference policy will be actor without lora applied
        lora_rank = config.actor_rollout_ref.model.get("lora", {}).get("rank", 0)
        if lora_rank <= 0:
            lora_rank = config.actor_rollout_ref.model.get("lora_rank", 0)
        self.ref_in_actor = lora_rank > 0 or config.actor_rollout_ref.model.get("lora_adapter_path") is not None

        # define in-reward KL control
        # kl loss control currently not suppoorted
        if self.config.algorithm.use_kl_in_reward:
            self.kl_ctrl_in_reward = core_algos.get_kl_controller(self.config.algorithm.kl_ctrl)

        self.use_prefix_grouper = self.config.actor_rollout_ref.actor.get("use_prefix_grouper", False)
        self.use_legacy_worker_impl = config.trainer.get("use_legacy_worker_impl", "auto")

        self._create_dataloader(train_dataset, val_dataset, collate_fn, train_sampler)

    def _create_dataloader(self, train_dataset, val_dataset, collate_fn, train_sampler: Optional[Sampler]):
        """
        Creates the train and validation dataloaders.
        """
        # TODO: we have to make sure the batch size is divisible by the dp size
        from verl.trainer.main_ppo import create_rl_dataset, create_rl_sampler

        if train_dataset is None:
            train_dataset = create_rl_dataset(
                self.config.data.train_files,
                self.config.data,
                self.tokenizer,
                self.processor,
                max_samples=self.config.data.get("train_max_samples", -1),
            )
        if val_dataset is None:
            val_dataset = create_rl_dataset(
                self.config.data.val_files,
                self.config.data,
                self.tokenizer,
                self.processor,
                max_samples=self.config.data.get("val_max_samples", -1),
            )
        self.train_dataset, self.val_dataset = train_dataset, val_dataset

        if train_sampler is None:
            train_sampler = create_rl_sampler(self.config.data, self.train_dataset)
        if collate_fn is None:
            from verl.utils.dataset.rl_dataset import collate_fn as default_collate_fn

            collate_fn = default_collate_fn

        num_workers = self.config.data["dataloader_num_workers"]

        self.train_dataloader = StatefulDataLoader(
            dataset=self.train_dataset,
            batch_size=self.config.data.get("gen_batch_size", self.config.data.train_batch_size),
            num_workers=num_workers,
            drop_last=True,
            collate_fn=collate_fn,
            sampler=train_sampler,
        )

        val_batch_size = self.config.data.val_batch_size  # Prefer config value if set
        if val_batch_size is None:
            val_batch_size = len(self.val_dataset)

        self.val_dataloader = StatefulDataLoader(
            dataset=self.val_dataset,
            batch_size=val_batch_size,
            num_workers=num_workers,
            shuffle=self.config.data.get("validation_shuffle", True),
            drop_last=False,
            collate_fn=collate_fn,
        )

        assert len(self.train_dataloader) >= 1, "Train dataloader is empty!"
        assert len(self.val_dataloader) >= 1, "Validation dataloader is empty!"

        print(
            f"Size of train dataloader: {len(self.train_dataloader)}, Size of val dataloader: "
            f"{len(self.val_dataloader)}"
        )

        total_training_steps = len(self.train_dataloader) * self.config.trainer.total_epochs

        if self.config.trainer.total_training_steps is not None:
            total_training_steps = self.config.trainer.total_training_steps

        self.total_training_steps = total_training_steps
        print(f"Total training steps: {self.total_training_steps}")

        try:
            OmegaConf.set_struct(self.config, True)
            with open_dict(self.config):
                if OmegaConf.select(self.config, "actor_rollout_ref.actor.optim"):
                    self.config.actor_rollout_ref.actor.optim.total_training_steps = total_training_steps
                if OmegaConf.select(self.config, "critic.optim"):
                    self.config.critic.optim.total_training_steps = total_training_steps
        except Exception as e:
            print(f"Warning: Could not set total_training_steps in config. Structure missing? Error: {e}")

    def _dump_generations(self, inputs, outputs, gts, scores, reward_extra_infos_dict, dump_path, artifacts=None):
        """Dump rollout/validation samples as JSONL."""
        os.makedirs(dump_path, exist_ok=True)
        filename = os.path.join(dump_path, f"{self.global_steps}.jsonl")

        n = len(inputs)
        base_data = {
            "input": inputs,
            "output": outputs,
            "gts": gts,
            "score": scores,
            "step": [self.global_steps] * n,
        }

        for k, v in reward_extra_infos_dict.items():
            if len(v) == n:
                base_data[k] = v

        async_dump = os.environ.get("VERL_ROLLOUT_DUMP_ASYNC", "0") == "1"
        if async_dump:
            future = _get_rollout_dump_executor().submit(
                _write_generation_jsonl,
                filename,
                base_data,
                artifacts,
            )
            future.add_done_callback(_report_rollout_dump_failure)
            print(f"Queued generation dump to {filename}")
        else:
            _write_generation_jsonl(filename, base_data, artifacts)
            print(f"Dumped generations to {filename}")

    def _log_rollout_data(
        self, batch: DataProto, reward_extra_infos_dict: dict, timing_raw: dict, rollout_data_dir: str
    ):
        """Log rollout data to disk.
        Args:
            batch (DataProto): The batch containing rollout data
            reward_extra_infos_dict (dict): Additional reward information to log
            timing_raw (dict): Timing information for profiling
            rollout_data_dir (str): Directory path to save the rollout data
        """
        with marked_timer("dump_rollout_generations", timing_raw, color="green"):
            response_mask = batch.batch.get("response_mask")
            if response_mask is None:
                response_length = batch.batch["responses"].shape[-1]
                response_mask = batch.batch["attention_mask"][:, -response_length:]
            response_mask = response_mask.bool()

            prompt_length = batch.batch["prompts"].shape[-1]
            prompt_mask = batch.batch["attention_mask"][:, :prompt_length].bool()
            prompt_id_lists = [
                _masked_row_to_list(row, mask, dtype=torch.long)
                for row, mask in zip(batch.batch["prompts"], prompt_mask, strict=True)
            ]
            response_id_lists = [
                _masked_row_to_list(row, mask, dtype=torch.long)
                for row, mask in zip(batch.batch["responses"], response_mask, strict=True)
            ]
            inputs = self.tokenizer.batch_decode(prompt_id_lists, skip_special_tokens=True)
            outputs = self.tokenizer.batch_decode(response_id_lists, skip_special_tokens=True)

            score_tensor = batch.batch.get("token_level_scores", batch.batch.get("rm_scores"))
            scores = score_tensor.sum(-1).cpu().tolist() if score_tensor is not None else [None] * len(inputs)
            sample_gts = [item.non_tensor_batch.get("reward_model", {}).get("ground_truth", None) for item in batch]

            reward_extra_infos_to_dump = reward_extra_infos_dict.copy()
            if "request_id" in batch.non_tensor_batch:
                reward_extra_infos_dict.setdefault(
                    "request_id",
                    batch.non_tensor_batch["request_id"].tolist(),
                )

            step_maps = batch.batch.get("step_maps")
            log_probs = batch.batch.get("log_probs")
            if log_probs is None:
                log_probs = batch.batch.get("rollout_log_probs")
            rollout_confidence_weights = (
                batch.batch["rollout_confidence_weights"]
                if "rollout_confidence_weights" in batch.batch.keys()
                else None
            )
            if rollout_confidence_weights is None and log_probs is not None:
                rollout_confidence_weights = torch.where(
                    torch.isfinite(log_probs.float()),
                    log_probs.float().exp(),
                    torch.zeros_like(log_probs.float()),
                )
            rollout_step_events = batch.non_tensor_batch.get("rollout_step_events")
            rollout_replay_trace = batch.non_tensor_batch.get("rollout_replay_trace")
            sglang_meta_info = batch.non_tensor_batch.get("sglang_meta_info")
            sglang_sdar_metrics = batch.non_tensor_batch.get("sglang_sdar_metrics")
            sglang_sdar_stats_delta = batch.non_tensor_batch.get("sglang_sdar_stats_delta")
            sdar_trace_map_status = batch.non_tensor_batch.get("sdar_trace_map_status")
            response_uids = batch.non_tensor_batch.get("response_uid")
            acc_values = batch.non_tensor_batch.get("acc")
            dense_noisy_pg_enabled = self.config.actor_rollout_ref.actor.get("dense_noisy_pg", {}).get("enable", False)
            random_token_trace_enabled = self.config.actor_rollout_ref.rollout.engine_kwargs.get(
                "random_token_rollout", False
            )
            compact_dump = (
                os.environ.get("VERL_ROLLOUT_DUMP_MODE", "full").strip().lower()
                == "compact"
            )
            artifacts = []
            for i in range(len(inputs)):
                response_mask_i = response_mask[i]
                if compact_dump:
                    artifact = {"logging_mode": "compact"}
                    if response_uids is not None:
                        artifact["response_uid"] = response_uids[i]
                    if acc_values is not None:
                        artifact["acc"] = acc_values[i]
                    if rollout_step_events is not None:
                        artifact["rollout_tpf_summary"] = (
                            _summarize_rollout_step_events(
                                rollout_step_events[i]
                            )
                        )
                    if sglang_sdar_metrics is not None:
                        artifact["sglang_sdar_tpf_summary"] = (
                            _summarize_sglang_sdar_blocks(
                                sglang_sdar_metrics[i],
                                returned_tokens=int(
                                    response_mask_i.sum().item()
                                ),
                            )
                        )
                    if sdar_trace_map_status is not None:
                        status_i = sdar_trace_map_status[i]
                        if isinstance(status_i, dict):
                            artifact["sdar_trace_map_status"] = {
                                key: status_i.get(key)
                                for key in (
                                    "source",
                                    "exact_tokens",
                                    "synthetic_tokens",
                                    "response_tokens",
                                )
                                if key in status_i
                            }
                    if "mixed_prob_threshold" in batch.non_tensor_batch:
                        artifact["mixed_prob_threshold"] = float(
                            batch.non_tensor_batch["mixed_prob_threshold"][i]
                        )
                    artifacts.append(artifact)
                    continue

                artifact = {
                    "prompt_ids": prompt_id_lists[i],
                    "response_ids": response_id_lists[i],
                }
                if response_uids is not None:
                    artifact["response_uid"] = response_uids[i]
                if acc_values is not None:
                    artifact["acc"] = acc_values[i]
                if step_maps is not None:
                    step_map_values = _masked_row_to_list(step_maps[i], response_mask_i, dtype=torch.long)
                    step_update_counts = _counts_by_int_value(step_map_values)
                    artifact["step_maps"] = step_map_values
                    artifact["token_update_counts_by_step"] = step_update_counts
                    artifact["accepted_token_counts_by_round"] = step_update_counts
                    artifact["accepted_token_total"] = int(sum(step_update_counts.values()))
                if log_probs is not None:
                    artifact["token_logprobs"] = _masked_row_to_list(log_probs[i], response_mask_i, dtype=torch.float32)
                if rollout_confidence_weights is not None:
                    artifact["rollout_confidence_weights"] = _masked_row_to_list(
                        rollout_confidence_weights[i], response_mask_i, dtype=torch.float32
                    )
                if rollout_step_events is not None:
                    events_i = rollout_step_events[i]
                    artifact["rollout_step_events"] = events_i
                    artifact["rollout_tpf_summary"] = _summarize_rollout_step_events(events_i)

                feature_status = {
                    "tpf": "done" if artifact.get("rollout_tpf_summary") else "missing",
                    "token_update_counts": "done" if "token_update_counts_by_step" in artifact else "missing",
                    "accepted_token_counts": "done" if "accepted_token_counts_by_round" in artifact else "missing",
                    "dense_confidence_inclusion": "N/A: dense_noisy_pg disabled",
                    "random_token_trace": "N/A: JetEngine mask-mode baseline has no random-token rollout",
                    "replay_trace": "done" if rollout_replay_trace is not None else "missing",
                    "sglang_sdar_metrics": (
                        "done" if sglang_sdar_stats_delta is not None or sglang_sdar_metrics is not None else "missing"
                    ),
                    "sdar_trace_map": "missing",
                }
                if rollout_replay_trace is not None:
                    artifact["rollout_replay_trace"] = rollout_replay_trace[i]
                if sdar_trace_map_status is not None:
                    status_i = sdar_trace_map_status[i]
                    artifact["sdar_trace_map_status"] = status_i
                    if isinstance(status_i, dict):
                        feature_status["sdar_trace_map"] = status_i.get("source", "unknown")
                if sglang_meta_info is not None:
                    artifact["sglang_meta_info"] = sglang_meta_info[i]
                if sglang_sdar_metrics is not None:
                    artifact["sglang_sdar_metrics"] = sglang_sdar_metrics[i]
                    artifact["sglang_sdar_tpf_summary"] = _summarize_sglang_sdar_blocks(
                        sglang_sdar_metrics[i],
                        returned_tokens=int(response_mask_i.sum().item()),
                    )
                if sglang_sdar_stats_delta is not None:
                    artifact["sglang_sdar_stats_delta"] = sglang_sdar_stats_delta[i]
                    artifact["sglang_sdar_delta_tpf_summary"] = _summarize_sglang_sdar_delta(
                        sglang_sdar_stats_delta[i],
                        returned_tokens=int(response_mask_i.sum().item()),
                    )
                if dense_noisy_pg_enabled and "dense_noisy_labels" in batch.batch:
                    dense_mask = batch.batch["dense_noisy_labels"][i].ne(-100)
                    artifact["dense_confidence_gt_0_1_inclusion_mask"] = _masked_row_to_list(
                        dense_mask, response_mask_i, dtype=torch.bool
                    )
                    feature_status["dense_confidence_inclusion"] = (
                        "partial: dense candidate mask logged; actor confidence threshold aggregates are in "
                        "actor/dense_noisy_pg_* metrics"
                    )
                elif dense_noisy_pg_enabled:
                    artifact["dense_confidence_gt_0_1_inclusion_mask"] = None
                    feature_status["dense_confidence_inclusion"] = "missing: dense_noisy_labels absent"
                else:
                    artifact["dense_confidence_gt_0_1_inclusion_mask"] = None

                if random_token_trace_enabled:
                    artifact["random_token_seed"] = batch.non_tensor_batch.get("random_token_seed", [None] * len(inputs))[i]
                    artifact["random_token_ids"] = batch.non_tensor_batch.get("random_token_ids", [None] * len(inputs))[i]
                    feature_status["random_token_trace"] = (
                        "done" if artifact["random_token_seed"] is not None or artifact["random_token_ids"] is not None else "missing"
                    )
                else:
                    artifact["random_token_seed"] = None
                    artifact["random_token_ids"] = None
                if "mixed_prob_threshold" in batch.non_tensor_batch:
                    artifact["mixed_prob_threshold"] = float(
                        batch.non_tensor_batch["mixed_prob_threshold"][i]
                    )
                artifact["logging_feature_status"] = feature_status
                if os.environ.get("VERL_ROLLOUT_DUMP_IDS", "0") == "1" or bool(
                    self.config.trainer.get("rollout_dump_ids", False)
                ):
                    # Debug aid: dump the raw ids under each mask (prompt region,
                    # attention-mask response region, response_mask) so layout questions --
                    # e.g. why response_length/mean exceeds the engine's token count by
                    # len(prompt) % block_size in the block-aligned SDAR layout -- can be
                    # answered offline. Enable with `+trainer.rollout_dump_ids=true` (the env
                    # var only reaches the driver process, not the Ray TaskRunner).
                    _am = batch.batch["attention_mask"][i].bool()
                    _R = batch.batch["responses"].shape[-1]
                    artifact["dbg_input_ids_attn"] = batch.batch["input_ids"][i][_am].tolist()
                    artifact["dbg_response_ids_attn"] = batch.batch["responses"][i][_am[-_R:]].tolist()
                    artifact["dbg_response_ids_respmask"] = _masked_row_to_list(
                        batch.batch["responses"][i], response_mask_i, dtype=torch.long
                    )
                    artifact["dbg_sums"] = {
                        "attn_total": int(_am.sum().item()),
                        "attn_prompt": int(_am[:-_R].sum().item()),
                        "attn_response": int(_am[-_R:].sum().item()),
                        "response_mask": int(response_mask_i.sum().item()),
                        "input_ids_len": int(batch.batch["input_ids"].shape[-1]),
                        "responses_len": int(_R),
                    }
                artifacts.append(artifact)

            self._dump_generations(
                inputs=inputs,
                outputs=outputs,
                gts=sample_gts,
                scores=scores,
                reward_extra_infos_dict=reward_extra_infos_to_dump,
                dump_path=rollout_data_dir,
                artifacts=artifacts,
            )

    def _maybe_log_val_generations(self, inputs, outputs, scores):
        """Log a table of validation samples to the configured logger (wandb or swanlab)"""

        generations_to_log = self.config.trainer.log_val_generations

        if generations_to_log == 0:
            return

        import numpy as np

        # Create tuples of (input, output, score) and sort by input text
        samples = list(zip(inputs, outputs, scores, strict=True))
        samples.sort(key=lambda x: x[0])  # Sort by input text

        # Use fixed random seed for deterministic shuffling
        rng = np.random.RandomState(42)
        rng.shuffle(samples)

        # Take first N samples after shuffling
        samples = samples[:generations_to_log]

        # Log to each configured logger
        self.validation_generations_logger.log(self.config.trainer.logger, samples, self.global_steps)

    def _get_gen_batch(self, batch: DataProto) -> DataProto:
        reward_keys = set({"data_source", "reward_model", "extra_info", "uid"}) & batch.non_tensor_batch.keys()

        # pop those keys for generation
        batch_keys_to_pop = []
        non_tensor_batch_keys_to_pop = set(batch.non_tensor_batch.keys()) - reward_keys
        gen_batch = batch.pop(
            batch_keys=batch_keys_to_pop,
            non_tensor_batch_keys=list(non_tensor_batch_keys_to_pop),
        )

        # For agent loop, we need reward model keys to compute score.
        gen_batch.non_tensor_batch.update(batch.non_tensor_batch)

        return gen_batch

    def _compute_reward_colocate(self, batch: DataProto) -> tuple[torch.Tensor, dict[str, Any]] | torch.Tensor:
        """
        compute reward use colocate reward model
        """
        assert self.reward_loop_manager is not None, "RewardLoopManager is None"
        batch_reward = self.reward_loop_manager.compute_rm_score(batch)
        return batch_reward

    def _validate(self, merged: bool = False):
        data_source_lst = []
        reward_extra_infos_dict: dict[str, list] = defaultdict(list)

        # Lists to collect samples for the table
        sample_inputs = []
        sample_outputs = []
        sample_gts = []
        sample_scores = []
        sample_turns = []
        sample_uids = []

        for test_data in self.val_dataloader:
            test_batch = DataProto.from_single_dict(test_data)

            if "uid" not in test_batch.non_tensor_batch:
                test_batch.non_tensor_batch["uid"] = np.array(
                    [str(uuid.uuid4()) for _ in range(len(test_batch.batch))], dtype=object
                )

            # repeat test batch
            test_batch = test_batch.repeat(
                repeat_times=self.config.actor_rollout_ref.rollout.val_kwargs.n, interleave=True
            )

            ground_truths = [
                item.non_tensor_batch.get("reward_model", {}).get("ground_truth", None) for item in test_batch
            ]
            sample_gts.extend(ground_truths)

            test_gen_batch = self._get_gen_batch(test_batch)
            test_gen_batch.meta_info = {
                "eos_token_id": self.tokenizer.eos_token_id,
                "pad_token_id": self.tokenizer.pad_token_id,
                "recompute_log_prob": False,
                "do_sample": self.config.actor_rollout_ref.rollout.val_kwargs.do_sample,
                "validate": True,
                "global_steps": self.global_steps,
            }
            print(f"test_gen_batch meta info: {test_gen_batch.meta_info}")

            # pad to be divisible by dp_size
            size_divisor = self.config.actor_rollout_ref.rollout.agent.num_workers
            test_gen_batch_padded, pad_size = pad_dataproto_to_divisor(test_gen_batch, size_divisor)
            test_output_gen_batch_padded = self.async_rollout_manager.generate_sequences(test_gen_batch_padded)
            # print(test_output_gen_batch_padded.meta_info) # _StringKeys(dict_keys(['prompts', 'responses', 'response_mask', 'input_ids', 'attention_mask', 'position_ids', 'rm_scores']))

            if self.use_rm and "rm_scores" not in test_output_gen_batch_padded.batch.keys():
                # for colocate reward models, we need to sleep rollout model
                # to spare GPU memory for reward model
                self.checkpoint_manager.sleep_replicas()
                batch_reward = self._compute_reward_colocate(test_output_gen_batch_padded)
                test_output_gen_batch_padded = test_output_gen_batch_padded.union(batch_reward)
                # wake up rollout model
                # replace with wake_up method once supported
                self.checkpoint_manager.update_weights()

            # unpad
            test_output_gen_batch = unpad_dataproto(test_output_gen_batch_padded, pad_size=pad_size)

            print("validation generation end")

            # Store generated outputs
            output_ids = test_output_gen_batch.batch["responses"]
            output_texts = [self.tokenizer.decode(ids, skip_special_tokens=True) for ids in output_ids]
            sample_outputs.extend(output_texts)

            test_batch = test_batch.union(test_output_gen_batch)
            test_batch.meta_info["validate"] = True

            # Store original inputs
            input_ids = test_batch.batch["prompts"]
            # TODO: Can we keep special tokens except for padding tokens?
            input_texts = [self.tokenizer.decode(ids, skip_special_tokens=True) for ids in input_ids]
            sample_inputs.extend(input_texts)
            sample_uids.extend(test_batch.non_tensor_batch["uid"])

            # evaluate using reward_function
            reward_tensor, reward_extra_info = extract_reward(test_batch)

            scores = reward_tensor.sum(-1).cpu().tolist()
            sample_scores.extend(scores)

            reward_extra_infos_dict["reward"].extend(scores)
            for key, values in reward_extra_info.items():
                if key not in reward_extra_infos_dict:
                    reward_extra_infos_dict[key] = []
                if isinstance(values, np.ndarray):
                    reward_extra_infos_dict[key].extend(values.tolist())
                else:
                    reward_extra_infos_dict[key].extend(values if isinstance(values, list) else [values])

            # collect num_turns of each prompt
            if "__num_turns__" in test_batch.non_tensor_batch:
                sample_turns.append(test_batch.non_tensor_batch["__num_turns__"])

            data_source_lst.append(test_batch.non_tensor_batch.get("data_source", ["unknown"] * reward_tensor.shape[0]))

        self._maybe_log_val_generations(inputs=sample_inputs, outputs=sample_outputs, scores=sample_scores)

        # dump generations
        val_data_dir = self.config.trainer.get("validation_data_dir", None)
        if val_data_dir:
            self._dump_generations(
                inputs=sample_inputs,
                outputs=sample_outputs,
                gts=sample_gts,
                scores=sample_scores,
                reward_extra_infos_dict=reward_extra_infos_dict,
                dump_path=val_data_dir,
            )

        for key_info, lst in reward_extra_infos_dict.items():
            assert len(lst) == 0 or len(lst) == len(sample_scores), f"{key_info}: {len(lst)=}, {len(sample_scores)=}"

        if merged:
            print("_merge_validation_results validate result will be merged")
            return {
                "data_sources": data_source_lst,
                "sample_uids": sample_uids,
                "sample_turns": sample_turns,
                "reward_extra_infos_dict": reward_extra_infos_dict,
            }
        data_sources = np.concatenate(data_source_lst, axis=0)
        return self._val_metrics_update(data_sources, sample_uids, reward_extra_infos_dict, sample_turns)

    def _val_metrics_update(self, data_sources, sample_uids, reward_extra_infos_dict, sample_turns):
        data_src2var2metric2val = process_validation_metrics(data_sources, sample_uids, reward_extra_infos_dict)
        metric_dict = {}
        for data_source, var2metric2val in data_src2var2metric2val.items():
            core_var = "acc" if "acc" in var2metric2val else "reward"
            for var_name, metric2val in var2metric2val.items():
                n_max = max([int(name.split("@")[-1].split("/")[0]) for name in metric2val.keys()])
                for metric_name, metric_val in metric2val.items():
                    if (
                        (var_name == core_var)
                        and any(metric_name.startswith(pfx) for pfx in ["mean", "maj", "best"])
                        and (f"@{n_max}" in metric_name)
                    ):
                        metric_sec = "val-core"
                    else:
                        metric_sec = "val-aux"
                    pfx = f"{metric_sec}/{data_source}/{var_name}/{metric_name}"
                    metric_dict[pfx] = metric_val

        if len(sample_turns) > 0:
            sample_turns = np.concatenate(sample_turns)
            metric_dict["val-aux/num_turns/min"] = sample_turns.min()
            metric_dict["val-aux/num_turns/max"] = sample_turns.max()
            metric_dict["val-aux/num_turns/mean"] = sample_turns.mean()

        return metric_dict

    def _merge_validation_results(self, result_a, result_b):
        if result_a is None and result_b is None:
            return {}
        if result_a is None:
            result_a = {"data_sources": [], "sample_uids": [], "sample_turns": [], "reward_extra_infos_dict": {}}
        if result_b is None:
            result_b = {"data_sources": [], "sample_uids": [], "sample_turns": [], "reward_extra_infos_dict": {}}

        if not result_a.get("data_sources") and not result_b.get("data_sources"):
            return {}

        data_sources = np.concatenate(result_a["data_sources"] + result_b["data_sources"], axis=0)
        sample_uids = result_a["sample_uids"] + result_b["sample_uids"]
        sample_turns = result_a["sample_turns"] + result_b["sample_turns"]

        reward_extra_infos_dict = {}
        all_keys = set(result_a["reward_extra_infos_dict"].keys()) | set(result_b["reward_extra_infos_dict"].keys())
        for key in all_keys:
            list_a = result_a["reward_extra_infos_dict"].get(key, [])
            list_b = result_b["reward_extra_infos_dict"].get(key, [])
            reward_extra_infos_dict[key] = list_a + list_b

        return self._val_metrics_update(data_sources, sample_uids, reward_extra_infos_dict, sample_turns)

    def init_workers(self):
        """Initialize distributed training workers using Ray backend.

        Creates:
        1. Ray resource pools from configuration
        2. Worker groups for each role (actor, critic, etc.)
        """
        self.resource_pool_manager.create_resource_pool()
        split_streaming_cfg = self.config.trainer.get("split_gpu_streaming", {})
        self._split_gpu_streaming_enabled = bool(split_streaming_cfg.get("enable", False))

        self.resource_pool_to_cls = {pool: {} for pool in self.resource_pool_manager.resource_pool_dict.values()}

        # create actor and rollout
        actor_role = Role.ActorRolloutRef if Role.ActorRolloutRef in self.role_worker_mapping else Role.ActorRollout
        if self._split_gpu_streaming_enabled:
            if Role.ActorRolloutRef in self.role_worker_mapping:
                raise NotImplementedError("split_gpu_streaming currently supports actor-only workers, not actor_rollout_ref")
            if actor_role not in self.role_worker_mapping:
                raise RuntimeError(f"split_gpu_streaming requires {actor_role} in role_worker_mapping")
            global_pool = self.resource_pool_manager.get_resource_pool(actor_role)
            actor_gpus = int(split_streaming_cfg.get("actor_gpus", 4))
            rollout_gpus = int(split_streaming_cfg.get("rollout_gpus", 4))
            if actor_gpus <= 0 or rollout_gpus <= 0:
                raise ValueError("split_gpu_streaming actor_gpus and rollout_gpus must be positive")
            if actor_gpus + rollout_gpus != global_pool.world_size:
                raise ValueError(
                    "split_gpu_streaming requires actor_gpus + rollout_gpus to match resource pool world size, "
                    f"got actor={actor_gpus}, rollout={rollout_gpus}, world={global_pool.world_size}"
                )
            if (
                self.config.actor_rollout_ref.rollout.checkpoint_engine.backend == "naive"
                and not bool(split_streaming_cfg.get("skip_weight_sync", False))
            ):
                raise ValueError(
                    "split_gpu_streaming uses standalone rollout replicas and requires a non-naive "
                    "rollout checkpoint engine such as nccl for actor-to-rollout weight sync; "
                    "set trainer.split_gpu_streaming.skip_weight_sync=true only for smoke tests"
                )
            per_node_split = bool(split_streaming_cfg.get("per_node_split", False))
            if per_node_split:
                rollout_resource_pool, actor_resource_pool = split_resource_pool_by_node(
                    global_pool, [rollout_gpus, actor_gpus]
                )
            else:
                rollout_resource_pool, actor_resource_pool = split_resource_pool(global_pool, [rollout_gpus, actor_gpus])
            if bool(split_streaming_cfg.get("node_local_delayed_grad_sync", False)):
                if not per_node_split:
                    raise ValueError(
                        "trainer.split_gpu_streaming.node_local_delayed_grad_sync requires per_node_split=true"
                    )
                node_count = len(global_pool.store)
                if node_count <= 0 or actor_gpus % node_count != 0:
                    raise ValueError(
                        "node_local_delayed_grad_sync requires actor_gpus divisible by node count, "
                        f"got actor_gpus={actor_gpus} node_count={node_count}"
                    )
                local_actor_ranks = actor_gpus // node_count
                with open_dict(self.config):
                    self.config.actor_rollout_ref.actor.fsdp_config.local_shard_group_only = True
                    self.config.actor_rollout_ref.actor.fsdp_config.fsdp_size = local_actor_ranks
                self._split_streaming_log(
                    "local_delayed_grad_sync_config",
                    local_shard_group_only=1,
                    fsdp_size=local_actor_ranks,
                    actor_gpus=actor_gpus,
                    node_count=node_count,
                )
            actor_rollout_cls = RayClassWithInitArgs(
                cls=self.role_worker_mapping[actor_role],
                config=self.config.actor_rollout_ref,
                role=str(Role.Actor),
            )
            self.resource_pool_to_cls[actor_resource_pool] = {str(actor_role): actor_rollout_cls}
            self._split_gpu_streaming_rollout_resource_pool = rollout_resource_pool
            self._split_gpu_streaming_actor_resource_pool = actor_resource_pool

            def format_pool_placement(pool_name, resource_pool):
                pgs = resource_pool.get_placement_groups()
                bundle_indices = getattr(resource_pool, "bundle_indices", None)
                if bundle_indices is None:
                    bundle_indices = range(
                        resource_pool.start_bundle_index,
                        resource_pool.start_bundle_index + resource_pool.world_size,
                    )
                node_ip = {node["NodeID"]: node["NodeManagerAddress"] for node in ray.nodes()}
                placements = []
                for global_bundle_idx in bundle_indices:
                    remaining = int(global_bundle_idx)
                    for pg_idx, pg in enumerate(pgs):
                        if remaining < pg.bundle_count:
                            specs = ray._private.state.state.placement_group_table(pg.id)
                            node_id = specs["bundles_to_node_id"][remaining]
                            placements.append(
                                f"{global_bundle_idx}->pg{pg_idx}:bundle{remaining}@{node_ip.get(node_id, node_id)}"
                            )
                            break
                        remaining -= pg.bundle_count
                return f"{pool_name}_placement=[{', '.join(placements)}]"

            def pool_node_addresses(resource_pool):
                pgs = resource_pool.get_placement_groups()
                bundle_indices = getattr(resource_pool, "bundle_indices", None)
                if bundle_indices is None:
                    bundle_indices = range(
                        resource_pool.start_bundle_index,
                        resource_pool.start_bundle_index
                        + resource_pool.world_size,
                    )
                node_ip = {
                    node["NodeID"]: node["NodeManagerAddress"]
                    for node in ray.nodes()
                }
                addresses = set()
                for global_bundle_idx in bundle_indices:
                    remaining = int(global_bundle_idx)
                    for pg in pgs:
                        if remaining < pg.bundle_count:
                            specs = ray._private.state.state.placement_group_table(
                                pg.id
                            )
                            node_id = specs["bundles_to_node_id"][remaining]
                            addresses.add(str(node_ip.get(node_id, node_id)))
                            break
                        remaining -= pg.bundle_count
                return addresses

            expected_rollout_node = str(
                split_streaming_cfg.get("expected_rollout_node", "") or ""
            ).strip()
            expected_actor_node = str(
                split_streaming_cfg.get("expected_actor_node", "") or ""
            ).strip()
            if expected_rollout_node:
                actual = pool_node_addresses(rollout_resource_pool)
                if actual != {expected_rollout_node}:
                    raise RuntimeError(
                        "split rollout placement mismatch: "
                        f"expected={expected_rollout_node} actual={sorted(actual)}"
                    )
            if expected_actor_node:
                actual = pool_node_addresses(actor_resource_pool)
                if actual != {expected_actor_node}:
                    raise RuntimeError(
                        "split actor placement mismatch: "
                        f"expected={expected_actor_node} actual={sorted(actual)}"
                    )

            print(
                "[RayPPOTrainer] split_gpu_streaming enabled: "
                f"rollout_gpus={rollout_gpus} actor_gpus={actor_gpus} "
                f"per_node_split={per_node_split} "
                f"rollout_process_on_nodes={rollout_resource_pool.store} "
                f"actor_process_on_nodes={actor_resource_pool.store} "
                f"rollout_bundle_indices={getattr(rollout_resource_pool, 'bundle_indices', None)} "
                f"actor_bundle_indices={getattr(actor_resource_pool, 'bundle_indices', None)}",
                flush=True,
            )
            print(
                "[RayPPOTrainer] split_gpu_streaming placement: "
                f"{format_pool_placement('rollout', rollout_resource_pool)} "
                f"{format_pool_placement('actor', actor_resource_pool)}",
                flush=True,
            )
        elif self.hybrid_engine:
            actor_rollout_resource_pool = self.resource_pool_manager.get_resource_pool(actor_role)
            actor_rollout_cls = RayClassWithInitArgs(
                cls=self.role_worker_mapping[actor_role],
                config=self.config.actor_rollout_ref,
                role=str(actor_role),
            )
            self.resource_pool_to_cls[actor_rollout_resource_pool][str(actor_role)] = actor_rollout_cls
        else:
            raise NotImplementedError

        # create critic
        if self.use_critic:
            resource_pool = self.resource_pool_manager.get_resource_pool(Role.Critic)

            from verl.workers.config import CriticConfig

            critic_cfg: CriticConfig = omega_conf_to_dataclass(self.config.critic)

            if self.use_legacy_worker_impl == "disable":
                # convert critic_cfg into TrainingWorkerConfig
                from verl.workers.engine_workers import TrainingWorkerConfig

                orig_critic_cfg = critic_cfg
                if orig_critic_cfg.strategy == "fsdp":
                    engine_config: FSDPEngineConfig = orig_critic_cfg.model.fsdp_config
                    engine_config.infer_max_token_len_per_gpu = critic_cfg.ppo_infer_max_token_len_per_gpu
                    engine_config.max_token_len_per_gpu = critic_cfg.ppo_max_token_len_per_gpu
                else:
                    raise NotImplementedError(f"Unknown strategy {orig_critic_cfg.strategy=}")

                critic_cfg = TrainingWorkerConfig(
                    model_type="value_model",
                    model_config=orig_critic_cfg.model_config,
                    engine_config=engine_config,
                    optimizer_config=orig_critic_cfg.optim,
                    checkpoint_config=orig_critic_cfg.checkpoint,
                )

            critic_cls = RayClassWithInitArgs(cls=self.role_worker_mapping[Role.Critic], config=critic_cfg)
            self.resource_pool_to_cls[resource_pool][str(Role.Critic)] = critic_cls

        # create reference policy if needed
        if self.use_reference_policy and Role.RefPolicy in self.role_worker_mapping:
            resource_pool = self.resource_pool_manager.get_resource_pool(Role.RefPolicy)
            ref_policy_cls = RayClassWithInitArgs(
                self.role_worker_mapping[Role.RefPolicy],
                config=self.config.actor_rollout_ref,
                role=str(Role.RefPolicy),
            )
            self.resource_pool_to_cls[resource_pool][str(Role.RefPolicy)] = ref_policy_cls

        # initialize WorkerGroup
        # NOTE: if you want to use a different resource pool for each role, which can support different parallel size,
        # you should not use `create_colocated_worker_cls`.
        # Instead, directly pass different resource pool to different worker groups.
        # See https://github.com/volcengine/verl/blob/master/examples/ray/tutorial.ipynb for more information.
        all_wg = {}
        wg_kwargs = {}  # Setting up kwargs for RayWorkerGroup
        if OmegaConf.select(self.config.trainer, "ray_wait_register_center_timeout") is not None:
            wg_kwargs["ray_wait_register_center_timeout"] = self.config.trainer.ray_wait_register_center_timeout
        if OmegaConf.select(self.config.global_profiler, "steps") is not None:
            wg_kwargs["profile_steps"] = OmegaConf.select(self.config.global_profiler, "steps")
            # Only require nsight worker options when tool is nsys
            if OmegaConf.select(self.config.global_profiler, "tool") == "nsys":
                assert (
                    OmegaConf.select(self.config.global_profiler.global_tool_config.nsys, "worker_nsight_options")
                    is not None
                ), "worker_nsight_options must be set when using nsys with profile_steps"
                wg_kwargs["worker_nsight_options"] = OmegaConf.to_container(
                    OmegaConf.select(self.config.global_profiler.global_tool_config.nsys, "worker_nsight_options")
                )
        wg_kwargs["device_name"] = self.device_name

        for resource_pool, class_dict in self.resource_pool_to_cls.items():
            if not class_dict:
                continue
            worker_dict_cls = create_colocated_worker_cls(class_dict=class_dict)
            wg_dict = self.ray_worker_group_cls(
                resource_pool=resource_pool,
                ray_cls_with_init=worker_dict_cls,
                **wg_kwargs,
            )
            spawn_wg = wg_dict.spawn(prefix_set=class_dict.keys())
            all_wg.update(spawn_wg)

        if self.use_critic:
            self.critic_wg = all_wg[str(Role.Critic)]
            if self.use_legacy_worker_impl == "disable":
                self.critic_wg.reset()
                # assign critic loss
                from functools import partial

                from verl.workers.utils.losses import value_loss

                value_loss_ = partial(value_loss, config=orig_critic_cfg)
                self.critic_wg.set_loss_fn(value_loss_)
            else:
                self.critic_wg.init_model()

        if self.use_reference_policy and not self.ref_in_actor:
            if str(Role.RefPolicy) in all_wg:
                self.ref_policy_wg = all_wg[str(Role.RefPolicy)]
                self.ref_policy_wg.init_model()
            else:
                # Model engine: ActorRolloutRefWorker
                assert str(Role.ActorRolloutRef) in all_wg, f"{all_wg.keys()=}"
                self.ref_policy_wg = all_wg[str(Role.ActorRolloutRef)]

        # we should create rollout at the end so that vllm can have a better estimation of kv cache memory
        self.actor_rollout_wg = all_wg[str(actor_role)]
        self.actor_rollout_wg.init_model()

        if self.ref_in_actor:
            self.ref_policy_wg = self.actor_rollout_wg

        # create reward loop manager
        from verl.experimental.reward_loop import RewardLoopManager

        # initalize reward loop manager
        # reward model (colocate or standalone): get resource_pool
        # no reward model: resource_pool = None
        resource_pool = self.resource_pool_manager.get_resource_pool(Role.RewardModel) if self.use_rm else None
        self.reward_loop_manager = RewardLoopManager(
            config=self.config,
            rm_resource_pool=resource_pool,
        )

        # create async rollout manager and request scheduler
        # Note: mode is always "async" since sync mode is deprecated
        self.async_rollout_mode = True

        # Support custom AgentLoopManager via config
        manager_class_fqn = self.config.actor_rollout_ref.rollout.get("agent", {}).get("agent_loop_manager_class")
        if manager_class_fqn:
            AgentLoopManager = load_class_from_fqn(manager_class_fqn, "AgentLoopManager")
        else:
            from verl.experimental.agent_loop import AgentLoopManager

        # infrastructure overview: https://verl.readthedocs.io/en/latest/advance/reward_loop.html#architecture-design
        # agent_reward_loop: streaming reward computation with actor rollout
        # two conditions satisfied: (1) no reward model, or (2) reward model with extra resource pool
        enable_agent_reward_loop = not self.use_rm or self.config.reward.reward_model.enable_resource_pool

        # if enable_agent_reward_loop, we directly pass reward_loop_workers to agent loop manager
        # to stream reward computation with actor rollout
        reward_loop_worker_handles = self.reward_loop_manager.reward_loop_workers if enable_agent_reward_loop else None
        self.async_rollout_manager = AgentLoopManager(
            config=self.config,
            worker_group=None if self._split_gpu_streaming_enabled else self.actor_rollout_wg,
            rollout_resource_pool=(
                self._split_gpu_streaming_rollout_resource_pool
                if self._split_gpu_streaming_enabled
                else actor_rollout_resource_pool
            ),
            reward_loop_worker_handles=reward_loop_worker_handles,
        )

        self.checkpoint_manager = CheckpointEngineManager(
            backend=self.config.actor_rollout_ref.rollout.checkpoint_engine.backend,
            trainer=self.actor_rollout_wg,
            replicas=self.async_rollout_manager.rollout_replicas,
        )

        # sleep all replicas to load checkpoint
        self.checkpoint_manager.sleep_replicas()

    def _save_checkpoint(self):
        from verl.utils.fs import local_mkdir_safe

        # path: given_path + `/global_step_{global_steps}` + `/actor`
        local_global_step_folder = os.path.join(
            self.config.trainer.default_local_dir, f"global_step_{self.global_steps}"
        )

        print(f"local_global_step_folder: {local_global_step_folder}")
        actor_local_path = os.path.join(local_global_step_folder, "actor")

        actor_remote_path = (
            None
            if self.config.trainer.default_hdfs_dir is None
            else os.path.join(self.config.trainer.default_hdfs_dir, f"global_step_{self.global_steps}", "actor")
        )

        remove_previous_ckpt_in_save = self.config.trainer.get("remove_previous_ckpt_in_save", False)
        if remove_previous_ckpt_in_save:
            print(
                "Warning: remove_previous_ckpt_in_save is deprecated,"
                + " set max_actor_ckpt_to_keep=1 and max_critic_ckpt_to_keep=1 instead"
            )
        max_actor_ckpt_to_keep = (
            self.config.trainer.get("max_actor_ckpt_to_keep", None) if not remove_previous_ckpt_in_save else 1
        )
        max_critic_ckpt_to_keep = (
            self.config.trainer.get("max_critic_ckpt_to_keep", None) if not remove_previous_ckpt_in_save else 1
        )

        self.actor_rollout_wg.save_checkpoint(
            actor_local_path, actor_remote_path, self.global_steps, max_ckpt_to_keep=max_actor_ckpt_to_keep
        )

        if self.use_critic:
            critic_local_path = os.path.join(local_global_step_folder, str(Role.Critic))
            critic_remote_path = (
                None
                if self.config.trainer.default_hdfs_dir is None
                else os.path.join(
                    self.config.trainer.default_hdfs_dir, f"global_step_{self.global_steps}", str(Role.Critic)
                )
            )
            self.critic_wg.save_checkpoint(
                critic_local_path, critic_remote_path, self.global_steps, max_ckpt_to_keep=max_critic_ckpt_to_keep
            )

        # save dataloader
        local_mkdir_safe(local_global_step_folder)
        dataloader_local_path = os.path.join(local_global_step_folder, "data.pt")
        dataloader_state_dict = self.train_dataloader.state_dict()
        torch.save(dataloader_state_dict, dataloader_local_path)

        # latest checkpointed iteration tracker (for atomic usage)
        if (
            hasattr(self.config.actor_rollout_ref.actor.checkpoint, "async_save")
            and self.config.actor_rollout_ref.actor.checkpoint.async_save
        ) or (
            "async_save" in self.config.actor_rollout_ref.actor.checkpoint
            and self.config.actor_rollout_ref.actor.checkpoint["async_save"]
        ):
            print("skip write latest_checkpointed_iteration.txt when async_save is True")
            return
        local_latest_checkpointed_iteration = os.path.join(
            self.config.trainer.default_local_dir, "latest_checkpointed_iteration.txt"
        )
        with open(local_latest_checkpointed_iteration, "w") as f:
            f.write(str(self.global_steps))

    def _load_checkpoint(self):
        if self.config.trainer.resume_mode == "disable":
            return 0

        # load from hdfs
        if self.config.trainer.default_hdfs_dir is not None:
            raise NotImplementedError("load from hdfs is not implemented yet")
        else:
            checkpoint_folder = self.config.trainer.default_local_dir  # TODO: check path
            if not os.path.isabs(checkpoint_folder):
                working_dir = os.getcwd()
                checkpoint_folder = os.path.join(working_dir, checkpoint_folder)
            global_step_folder = find_latest_ckpt_path(checkpoint_folder)  # None if no latest

        # find global_step_folder
        if self.config.trainer.resume_mode == "auto":
            if global_step_folder is None:
                print("Training from scratch")
                return 0
        else:
            if self.config.trainer.resume_mode == "resume_path":
                assert isinstance(self.config.trainer.resume_from_path, str), "resume ckpt must be str type"
                assert "global_step_" in self.config.trainer.resume_from_path, (
                    "resume ckpt must specify the global_steps"
                )
                global_step_folder = self.config.trainer.resume_from_path
                if not os.path.isabs(global_step_folder):
                    working_dir = os.getcwd()
                    global_step_folder = os.path.join(working_dir, global_step_folder)
        print(f"Load from checkpoint folder: {global_step_folder}")
        # set global step
        self.global_steps = int(global_step_folder.split("global_step_")[-1])

        print(f"Setting global step to {self.global_steps}")
        print(f"Resuming from {global_step_folder}")

        actor_path = os.path.join(global_step_folder, "actor")
        critic_path = os.path.join(global_step_folder, str(Role.Critic))
        # load actor
        self.actor_rollout_wg.load_checkpoint(
            actor_path, del_local_after_load=self.config.trainer.del_local_ckpt_after_load
        )
        # load critic
        if self.use_critic:
            self.critic_wg.load_checkpoint(
                critic_path, del_local_after_load=self.config.trainer.del_local_ckpt_after_load
            )

        # load dataloader,
        # TODO: from remote not implemented yet
        dataloader_local_path = os.path.join(global_step_folder, "data.pt")
        if os.path.exists(dataloader_local_path):
            dataloader_state_dict = torch.load(dataloader_local_path, weights_only=False)
            self.train_dataloader.load_state_dict(dataloader_state_dict)
        else:
            print(f"Warning: No dataloader state found at {dataloader_local_path}, will start from scratch")

    def _start_profiling(self, do_profile: bool) -> None:
        """Start profiling for all worker groups if profiling is enabled."""
        if do_profile:
            self.actor_rollout_wg.start_profile(role="e2e", profile_step=self.global_steps)
            if self.use_reference_policy:
                self.ref_policy_wg.start_profile(profile_step=self.global_steps)
            if self.use_critic:
                self.critic_wg.start_profile(profile_step=self.global_steps)

    def _stop_profiling(self, do_profile: bool) -> None:
        """Stop profiling for all worker groups if profiling is enabled."""
        if do_profile:
            self.actor_rollout_wg.stop_profile()
            if self.use_reference_policy:
                self.ref_policy_wg.stop_profile()
            if self.use_critic:
                self.critic_wg.stop_profile()

    def _get_dp_size(self, worker_group, role: str) -> int:
        """Get data parallel size from worker group dispatch info.

        This method retrieves the data parallel size by querying the dispatch info
        for the specified role. The dispatch info is cached for subsequent calls.

        Args:
            worker_group: The worker group to query dispatch info from.
            role: The role name (e.g., "actor", "critic") to get DP size for.

        Returns:
            The data parallel size (number of DP ranks).
        """
        if role not in worker_group._dispatch_info:
            dp_rank_mapping = worker_group._query_dispatch_info(role)
            worker_group._dispatch_info[role] = dp_rank_mapping
        else:
            dp_rank_mapping = worker_group._dispatch_info[role]
        return max(dp_rank_mapping) + 1

    def _balance_batch(self, batch: DataProto, metrics, logging_prefix="global_seqlen", keep_minibatch=False):
        """Reorder the data on single controller such that each dp rank gets similar total tokens.

        When use_prefix_grouper is enabled, uses group-level balancing to keep samples with
        the same uid together on the same rank for prefix sharing optimization.
        """
        attention_mask = batch.batch["attention_mask"]
        batch_size = attention_mask.shape[0]
        global_seqlen_lst = batch.batch["attention_mask"].view(batch_size, -1).sum(-1)  # (train_batch_size,)
        workload_lst = calculate_workload(global_seqlen_lst)
        # Get dp_size from dispatch info to correctly balance across data parallel ranks
        # Note: world_size may include tensor/pipeline parallel dimensions, but we only want DP
        dp_size = self._get_dp_size(self.actor_rollout_wg, "actor")

        # Use group-level balancing for PrefixGrouper to keep same-uid samples together
        if getattr(self, "use_prefix_grouper", False) and "uid" in batch.non_tensor_batch:
            from verl.utils.seqlen_balancing import get_group_balanced_partitions

            uid_list = list(batch.non_tensor_batch["uid"])
            seqlen_list = global_seqlen_lst.tolist()

            # Count number of uid groups
            num_groups = len(set(uid_list))

            if num_groups % dp_size != 0:
                raise ValueError(
                    f"PrefixGrouper with balance_batch requires num_uid_groups ({num_groups}) "
                    f"% dp_size ({dp_size}) == 0. "
                    f"This ensures each rank gets equal number of groups. "
                    f"Current batch_size={batch_size}, adjust batch_size to be a multiple of "
                    f"dp_size * rollout.n."
                )

            global_partition_lst = get_group_balanced_partitions(
                seqlen_list=seqlen_list,
                uid_list=uid_list,
                k_partitions=dp_size,
            )

        elif keep_minibatch:
            # Decouple the DP balancing and mini-batching.
            minibatch_size = self.config.actor_rollout_ref.actor.get("ppo_mini_batch_size")
            minibatch_num = len(workload_lst) // minibatch_size
            global_partition_lst = [[] for _ in range(dp_size)]
            for i in range(minibatch_num):
                rearrange_minibatch_lst = get_seqlen_balanced_partitions(
                    workload_lst[i * minibatch_size : (i + 1) * minibatch_size],
                    k_partitions=dp_size,
                    equal_size=True,
                )
                for j, part in enumerate(rearrange_minibatch_lst):
                    global_partition_lst[j].extend([x + minibatch_size * i for x in part])
        else:
            global_partition_lst = get_seqlen_balanced_partitions(workload_lst, k_partitions=dp_size, equal_size=True)
        # Place smaller micro-batches at both ends to reduce the bubbles in pipeline parallel.
        # Skip reordering within partitions for PrefixGrouper to maintain uid grouping
        if not getattr(self, "use_prefix_grouper", False):
            for idx, partition in enumerate(global_partition_lst):
                partition.sort(key=lambda x: (workload_lst[x], x))
                ordered_partition = partition[::2] + partition[1::2][::-1]
                global_partition_lst[idx] = ordered_partition

        # reorder based on index. The data will be automatically equally partitioned by dispatch function
        global_idx = torch.tensor([j for partition in global_partition_lst for j in partition])
        batch.reorder(global_idx)
        global_balance_stats = log_seqlen_unbalance(
            seqlen_list=global_seqlen_lst.tolist(), partitions=global_partition_lst, prefix=logging_prefix
        )
        metrics.update(global_balance_stats)

    def _compute_values(self, batch: DataProto) -> DataProto:
        if self.use_legacy_worker_impl == "disable":
            batch_td = batch.to_tensordict()
            # step 2: convert from padding to nopadding
            batch_td = left_right_2_no_padding(batch_td)
            # step 3: add meta info
            tu.assign_non_tensor(batch_td, compute_loss=False)
            output = self.critic_wg.infer_batch(batch_td)
            output = output.get()
            values = tu.get(output, "values")
            values = no_padding_2_padding(values, batch_td)
            values = tu.get_tensordict({"values": values.float()})
            values = DataProto.from_tensordict(values)
        else:
            values = self.critic_wg.compute_values(batch)
        return values

    def _compute_ref_log_prob(self, batch: DataProto) -> DataProto:
        if self.use_legacy_worker_impl == "disable":
            # step 1: convert dataproto to tensordict.
            batch_td = batch.to_tensordict()
            # step 2: convert from padding to nopadding
            batch_td = left_right_2_no_padding(batch_td)
            # step 3: add meta info
            metadata = {"calculate_entropy": False, "compute_loss": False}
            if self.ref_in_actor:
                metadata["no_lora_adapter"] = True
            tu.assign_non_tensor(batch_td, **metadata)
            if self.ref_in_actor:
                output = self.actor_rollout_wg.compute_log_prob(batch_td)
            else:
                output = self.ref_policy_wg.compute_ref_log_prob(batch_td)
            # gather output
            log_probs = tu.get(output, "log_probs")
            # step 4. No padding to padding
            log_probs = no_padding_2_padding(log_probs, batch_td)
            # step 5: rebuild a tensordict and convert to dataproto
            ref_log_prob = tu.get_tensordict({"ref_log_prob": log_probs.float()})
            ref_log_prob = DataProto.from_tensordict(ref_log_prob)
        else:
            ref_log_prob = self.ref_policy_wg.compute_ref_log_prob(batch)

        return ref_log_prob

    def _compute_old_log_prob(self, batch: DataProto):
        if self.use_legacy_worker_impl == "disable":
            # TODO: remove step 1, 2, 4 after we make the whole training tensordict and padding free
            # step 1: convert dataproto to tensordict.
            batch_td = batch.to_tensordict()
            # step 2: convert from padding to nopadding
            batch_td = left_right_2_no_padding(batch_td)
            # step 3: add meta info
            tu.assign_non_tensor(batch_td, calculate_entropy=True, compute_loss=False)
            output = self.actor_rollout_wg.compute_log_prob(batch_td)
            # gather output
            entropy = tu.get(output, "entropy")
            log_probs = tu.get(output, "log_probs")
            old_log_prob_mfu = tu.get(output, "metrics")["mfu"]
            # step 4. No padding to padding
            entropy = no_padding_2_padding(entropy, batch_td)
            log_probs = no_padding_2_padding(log_probs, batch_td)
            # step 5: rebuild a tensordict and convert to dataproto
            old_log_prob = tu.get_tensordict({"old_log_probs": log_probs.float(), "entropys": entropy.float()})
            old_log_prob = DataProto.from_tensordict(old_log_prob)
        else:
            old_log_prob = self.actor_rollout_wg.compute_log_prob(batch)
            old_log_prob_mfu = 0
        return old_log_prob, old_log_prob_mfu

    def _compute_causal_ar_rollout_scores_on_driver(self, batch: DataProto, ar_cfg: dict) -> DataProto:
        """Reference implementation matching the offline causal scorer.

        This is slower than using the FSDP actor worker, but avoids the FSDP
        eval-mask path that currently produces mis-scaled probabilities.
        """
        from transformers import AutoConfig, AutoModelForCausalLM
        from verl.utils.model import update_model_config
        from verl.utils.transformers_compat import ensure_transformers_runtime_compat, repair_sdar_rotary_embedding

        ensure_transformers_runtime_compat()
        device = torch.device(ar_cfg.get("driver_device", "cuda:0"))
        model_path = self.config.actor_rollout_ref.model.path
        override_config = OmegaConf.to_container(
            OmegaConf.create(self.config.actor_rollout_ref.model.get("override_config", {}))
        )
        attn_implementation = override_config.get("attn_implementation", "eager")
        model_config = AutoConfig.from_pretrained(
            model_path,
            trust_remote_code=self.config.actor_rollout_ref.model.get("trust_remote_code", True),
            attn_implementation=attn_implementation,
        )
        override_kwargs = {
            "bos_token_id": self.tokenizer.bos_token_id,
            "eos_token_id": self.tokenizer.eos_token_id,
            "pad_token_id": self.tokenizer.pad_token_id,
        }
        override_kwargs.update(override_config)
        update_model_config(model_config, override_config_kwargs=override_kwargs)
        model = AutoModelForCausalLM.from_pretrained(
            model_path,
            trust_remote_code=self.config.actor_rollout_ref.model.get("trust_remote_code", True),
            dtype=torch.bfloat16,
            config=model_config,
            attn_implementation=attn_implementation,
        ).eval().to(device)
        repair_sdar_rotary_embedding(model)

        prompts = batch.batch["prompts"]
        responses = batch.batch["responses"]
        attention_mask = batch.batch["attention_mask"].bool()
        response_mask = batch.batch["response_mask"].bool()
        prompt_width = prompts.shape[1]
        ar_token_log_probs = torch.zeros_like(responses, dtype=torch.float32)
        ar_token_probs = torch.zeros_like(responses, dtype=torch.float32)
        chunk_size = int(ar_cfg.get("driver_logprob_chunk_size", 128))
        with torch.inference_mode():
            for i in range(responses.shape[0]):
                prompt_ids = prompts[i][attention_mask[i, :prompt_width]]
                resp_ids = responses[i][response_mask[i]]
                if prompt_ids.numel() == 0 or resp_ids.numel() == 0:
                    continue
                compact_ids = torch.cat([prompt_ids, resp_ids], dim=0).to(device).unsqueeze(0)
                total_len = compact_ids.shape[1]
                prompt_len = prompt_ids.numel()
                causal_mask = torch.ones((total_len, total_len), device=device, dtype=torch.bool).tril()
                outputs = model(
                    input_ids=compact_ids,
                    attention_mask=causal_mask,
                    use_cache=False,
                    return_dict=True,
                )
                logits = outputs.logits[:, prompt_len - 1 : total_len - 1, :].squeeze(0)
                targets = resp_ids.to(device)
                sample_lp = torch.zeros((targets.numel(),), device=device, dtype=torch.float32)
                for start in range(0, targets.numel(), chunk_size):
                    end = min(start + chunk_size, targets.numel())
                    chunk_lp = F.log_softmax(logits[start:end].float(), dim=-1).gather(
                        -1,
                        targets[start:end, None],
                    ).squeeze(-1)
                    sample_lp[start:end] = torch.nan_to_num(chunk_lp, nan=-100.0, posinf=0.0, neginf=-100.0)
                sample_probs = sample_lp.exp().clamp_(0.0, 1.0)
                ar_token_log_probs[i, response_mask[i]] = sample_lp.cpu()
                ar_token_probs[i, response_mask[i]] = sample_probs.cpu()
                del outputs, logits, compact_ids, causal_mask
                torch.cuda.empty_cache()

        denom = response_mask.sum(dim=-1).clamp_min(1).to(dtype=torch.float32)
        ar_avg_prob = ar_token_probs.sum(dim=-1) / denom
        del model
        torch.cuda.empty_cache()
        return DataProto.from_dict(
            tensors={
                "ar_token_log_probs": ar_token_log_probs,
                "ar_token_probs": ar_token_probs,
                "ar_avg_prob": ar_avg_prob,
            },
            meta_info={"temperature": self.config.actor_rollout_ref.rollout.temperature},
        )

    def _maybe_compute_causal_ar_prob_advantage(
        self, batch: DataProto, metrics: dict[str, float], timing_raw: dict
    ) -> DataProto:
        ar_cfg = self.config.algorithm.get("ar_prob_advantage", {})
        if not ar_cfg or not ar_cfg.get("enable", False):
            return batch
        if self.use_legacy_worker_impl == "disable":
            raise NotImplementedError("algorithm.ar_prob_advantage is implemented for DataProto/FSDP workers only")

        print("[RayPPOTrainer] Computing causal AR rollout probabilities", flush=True)
        with marked_timer("causal_ar_prob", timing_raw, color="blue"):
            if ar_cfg.get("scorer_backend", "actor") == "driver_hf":
                ar_scores = self._compute_causal_ar_rollout_scores_on_driver(batch, ar_cfg)
            else:
                ar_scores = self.actor_rollout_wg.compute_causal_ar_rollout_scores(batch)
            batch = batch.union(ar_scores)
        if os.environ.get("VERL_CAUSAL_AR_SCORE_DEBUG", "0") == "1":
            try:
                print(
                    "[CausalARScoreDebugTrainer] "
                    f"ar_avg_prob={batch.batch['ar_avg_prob'].detach().float().cpu().tolist()} "
                    f"first_probs={batch.batch['ar_token_probs'][0, :8].detach().float().cpu().tolist()}",
                    flush=True,
                )
            except Exception as exc:
                print(f"[CausalARScoreDebugTrainer] failed: {exc}", flush=True)

        response_mask = batch.batch["response_mask"].bool()
        ar_token_probs = torch.where(
            response_mask,
            torch.nan_to_num(batch.batch["ar_token_probs"].float(), nan=0.0, posinf=1.0, neginf=0.0).clamp(0.0, 1.0),
            torch.zeros_like(batch.batch["ar_token_probs"].float()),
        )
        avg_prob = torch.nan_to_num(batch.batch["ar_avg_prob"].float(), nan=0.0, posinf=1.0, neginf=0.0).clamp(0.0, 1.0)
        mean_prob = avg_prob.mean()
        std_prob = avg_prob.std(unbiased=False)
        eps = float(ar_cfg.get("std_eps", 1e-6))
        std_denom = torch.nan_to_num(std_prob, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(eps)
        seq_adv = torch.nan_to_num((avg_prob - mean_prob) / std_denom, nan=0.0, posinf=0.0, neginf=0.0)
        batch.batch["ar_sequence_advantages"] = seq_adv
        batch.batch["ar_token_probs"] = ar_token_probs

        valid_probs = ar_token_probs[response_mask]
        metrics["ar_prob_advantage/avg_prob_mean"] = float(mean_prob.detach().cpu().item())
        metrics["ar_prob_advantage/avg_prob_std"] = float(std_prob.detach().cpu().item())
        metrics["ar_prob_advantage/adv_mean"] = float(seq_adv.mean().detach().cpu().item())
        metrics["ar_prob_advantage/adv_std"] = float(seq_adv.std(unbiased=False).detach().cpu().item())
        if valid_probs.numel() > 0:
            threshold = float(ar_cfg.get("confidence_threshold", 0.1))
            metrics["ar_prob_advantage/token_prob_mean"] = float(valid_probs.mean().detach().cpu().item())
            metrics["ar_prob_advantage/token_prob_min"] = float(valid_probs.min().detach().cpu().item())
            metrics["ar_prob_advantage/token_prob_max"] = float(valid_probs.max().detach().cpu().item())
            metrics["ar_prob_advantage/token_prob_active_frac"] = float(
                valid_probs.gt(threshold).to(dtype=torch.float32).mean().detach().cpu().item()
            )
        return batch

    def _without_actor_replay_state(self, batch: DataProto) -> DataProto:
        """Return a lightweight view for critic/value paths."""
        if batch.batch is None:
            return batch
        drop = set(self._ACTOR_REPLAY_STATE_KEYS)
        batch_keys = list(batch.batch.keys())
        keep_keys = [key for key in batch_keys if key not in drop]
        if len(keep_keys) == len(batch_keys):
            return batch
        return batch.select(batch_keys=keep_keys)

    def _drop_actor_replay_state_(self, batch: DataProto) -> None:
        if batch.batch is not None:
            drop_keys = [key for key in self._ACTOR_REPLAY_STATE_KEYS if key in batch.batch]
            if drop_keys:
                batch.pop(batch_keys=drop_keys)
        for key in (
            "rollout_self_conditioning",
            "sglang_sdar_replay_tensors",
            "sglang_sdar_replay_tensors_compact",
            "replay_tensors",
            "replay_tensors_compact",
            "compact_replay_tensors",
        ):
            batch.non_tensor_batch.pop(key, None)

    @staticmethod
    def _replay_row_manifest_enabled() -> bool:
        return str(os.environ.get("VERL_REPLAY_ROW_MANIFEST", "0")).strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }

    def _replay_row_manifest_path(self) -> str:
        env_path = os.environ.get("VERL_REPLAY_ROW_MANIFEST_PATH")
        if env_path:
            return str(env_path)
        trainer_cfg = getattr(self.config, "trainer", {})
        for key in ("rollout_data_dir", "default_local_dir"):
            try:
                value = trainer_cfg.get(key, None)
            except AttributeError:
                value = getattr(trainer_cfg, key, None)
            if value:
                return os.path.join(str(value), "replay_row_manifest.jsonl")
        return os.path.join(os.getcwd(), "replay_row_manifest.jsonl")

    def _warn_replay_row_manifest(self, message: str) -> None:
        try:
            if getattr(self, "_replay_row_manifest_warned", False):
                return
            self._replay_row_manifest_warned = True
            print(f"[ReplayRowManifest] warning: {message}", flush=True)
        except Exception:
            pass

    @staticmethod
    def _manifest_mapping_get(mapping: Any, key: str, default: Any = None) -> Any:
        if mapping is None:
            return default
        try:
            return mapping.get(key, default)
        except AttributeError:
            try:
                return mapping[key]
            except Exception:
                return default

    @staticmethod
    def _manifest_json_scalar(value: Any) -> Any:
        try:
            if value is None:
                return None
            if torch.is_tensor(value):
                if int(value.numel()) <= 0:
                    return None
                value = value.detach().cpu().reshape(-1)[0].item()
            if isinstance(value, np.ndarray):
                if int(value.size) <= 0:
                    return None
                value = value.reshape(-1)[0].item()
            if isinstance(value, np.generic):
                value = value.item()
            if isinstance(value, bytes):
                return value.decode("utf-8", errors="replace")
            if isinstance(value, (str, int, float, bool)):
                return value
            return str(value)

        except Exception:
            return None

    @classmethod
    def _manifest_row_value(cls, values: Any, row_index: int) -> Any:
        try:
            if values is None:
                return None
            if torch.is_tensor(values):
                if values.dim() == 0:
                    return cls._manifest_json_scalar(values)
                if row_index < 0 or row_index >= int(values.shape[0]):
                    return None
                return cls._manifest_json_scalar(values[row_index])
            if isinstance(values, np.ndarray):
                if values.ndim == 0:
                    return cls._manifest_json_scalar(values)
                if row_index < 0 or row_index >= len(values):
                    return None
                return cls._manifest_json_scalar(values[row_index])
            if isinstance(values, (list, tuple)):
                if row_index < 0 or row_index >= len(values):
                    return None
                return cls._manifest_json_scalar(values[row_index])
            return cls._manifest_json_scalar(values)
        except Exception:
            return None

    @staticmethod
    def _manifest_int_or_none(value: Any) -> int | None:
        value = RayPPOTrainer._manifest_json_scalar(value)
        if value is None or value == "":
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _manifest_tensor_summary(tensor: torch.Tensor | None, *, head: int = 8, tail: int = 8) -> dict[str, Any]:
        if tensor is None:
            return {"checksum": None, "head": [], "tail": [], "shape": None}
        try:
            row = tensor.detach().cpu().reshape(-1)
            shape = [int(dim) for dim in tensor.shape]
            if int(row.numel()) <= 0:
                return {"checksum": 0, "head": [], "tail": [], "shape": shape}
            if row.dtype == torch.bool:
                checksum_values = row.to(dtype=torch.int64)
                list_values = checksum_values
            elif torch.is_floating_point(row):
                finite = torch.nan_to_num(row.to(dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                checksum_values = torch.round(finite * 1_000_000).to(dtype=torch.int64)
                list_values = finite
            else:
                checksum_values = row.to(dtype=torch.int64)
                list_values = checksum_values
            weights = torch.arange(1, int(checksum_values.numel()) + 1, dtype=torch.int64)
            checksum = int((checksum_values * weights).sum().item())
            return {
                "checksum": checksum,
                "head": _json_safe(list_values[:head]),
                "tail": _json_safe(list_values[-tail:]),
                "shape": shape,
            }
        except Exception:
            return {"checksum": None, "head": [], "tail": [], "shape": None}

    @staticmethod
    def _infer_replay_row_manifest_step_key(
        step_maps_row: torch.Tensor | None,
        label_mask_row: torch.Tensor | None,
    ) -> tuple[int | None, list[int]]:
        try:
            if step_maps_row is None:
                return None, []
            steps = step_maps_row.detach().cpu().reshape(-1).to(dtype=torch.long)
            if label_mask_row is not None:
                mask = label_mask_row.detach().cpu().reshape(-1).bool()
                if int(mask.numel()) == int(steps.numel()):
                    steps = steps[mask]
            steps = steps[steps.ge(0)]
            if int(steps.numel()) <= 0:
                return None, []
            keys = sorted(int(value) for value in torch.unique(steps).tolist())
            return (keys[0] if len(keys) == 1 else None), keys
        except Exception:
            return None, []

    def _dump_replay_row_manifest(
        self,
        tensor_batch: Any,
        *,
        source_type: str,
        non_tensor_batch: dict[str, Any] | None = None,
        row_contexts: list[dict[str, Any]] | None = None,
        global_step: int | None = None,
        extra: dict[str, Any] | None = None,
    ) -> None:
        if not self._replay_row_manifest_enabled():
            return
        try:
            input_ids = self._manifest_mapping_get(tensor_batch, "input_ids")
            responses = self._manifest_mapping_get(tensor_batch, "responses")
            label_mask = self._manifest_mapping_get(tensor_batch, "response_mask")
            position_ids = self._manifest_mapping_get(tensor_batch, "position_ids")
            step_maps = self._manifest_mapping_get(tensor_batch, "step_maps")
            quality_mask = self._manifest_mapping_get(tensor_batch, "rollout_quality_mask")
            if not torch.is_tensor(input_ids) or not torch.is_tensor(responses):
                return
            row_count = int(input_ids.shape[0])
            if row_count <= 0:
                return
            if label_mask is None and torch.is_tensor(responses):
                label_mask = responses.ne(-100)

            tensor_input_shape = [int(dim) for dim in input_ids.shape]
            input_width = int(input_ids.shape[-1]) if input_ids.dim() > 0 else 0
            response_width = int(responses.shape[-1]) if responses.dim() > 0 else 0
            lines: list[str] = []
            for row_index in range(row_count):
                row_context = row_contexts[row_index] if row_contexts and row_index < len(row_contexts) else {}
                input_row = input_ids[row_index]
                label_row = responses[row_index] if torch.is_tensor(responses) else None
                mask_row = label_mask[row_index] if torch.is_tensor(label_mask) else None
                pos_row = position_ids[row_index] if torch.is_tensor(position_ids) else None
                step_row = step_maps[row_index] if torch.is_tensor(step_maps) and row_index < int(step_maps.shape[0]) else None

                inferred_train_step_key, inferred_train_step_keys = self._infer_replay_row_manifest_step_key(
                    step_row,
                    mask_row,
                )
                train_step_key = self._manifest_int_or_none(
                    row_context.get("train_step_key", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if train_step_key is None:
                    train_step_key = self._manifest_int_or_none(
                        self._manifest_row_value(
                            self._manifest_mapping_get(non_tensor_batch, "_replay_train_step_key"),
                            row_index,
                        )
                    )
                if train_step_key is None:
                    train_step_key = inferred_train_step_key

                teacher_step_key = self._manifest_int_or_none(
                    row_context.get("teacher_step_key", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if teacher_step_key is None:
                    teacher_step_key = self._manifest_int_or_none(
                        self._manifest_row_value(
                            self._manifest_mapping_get(non_tensor_batch, "_replay_teacher_step_key"),
                            row_index,
                        )
                    )

                active_count = None
                effective_active_count = None
                target_row = label_row
                target_position_row = None
                if torch.is_tensor(label_row) and torch.is_tensor(mask_row):
                    flat_mask = mask_row.detach().bool().reshape(-1)
                    flat_label = label_row.detach().reshape(-1)
                    if int(flat_mask.numel()) == int(flat_label.numel()):
                        active_count = int(flat_mask.sum().cpu().item())
                        target_row = flat_label[flat_mask]
                        if torch.is_tensor(quality_mask) and row_index < int(quality_mask.shape[0]):
                            q_row = quality_mask[row_index].detach().bool().reshape(-1)
                            if int(q_row.numel()) == int(flat_mask.numel()):
                                effective_active_count = int((flat_mask & q_row).sum().cpu().item())
                        if torch.is_tensor(pos_row) and pos_row.dim() == 1 and response_width > 0:
                            pos_start = int(pos_row.numel()) - response_width
                            active_pos = torch.nonzero(flat_mask, as_tuple=False).reshape(-1)
                            if pos_start >= 0 and int(active_pos.numel()) > 0:
                                target_position_row = pos_row[pos_start + active_pos]
                if active_count is None and torch.is_tensor(label_row):
                    active_count = int(label_row.detach().reshape(-1).ne(-100).sum().cpu().item())
                if effective_active_count is None:
                    effective_active_count = active_count

                label_summary = self._manifest_tensor_summary(label_row)
                target_summary = self._manifest_tensor_summary(target_row)
                mask_summary = self._manifest_tensor_summary(mask_row)
                position_summary = self._manifest_tensor_summary(pos_row)
                target_position_summary = self._manifest_tensor_summary(target_position_row)
                input_summary = self._manifest_tensor_summary(input_row)

                sample_index = self._manifest_int_or_none(
                    row_context.get("sample_index", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if sample_index is None:
                    sample_index = self._manifest_int_or_none(
                        self._manifest_row_value(
                            self._manifest_mapping_get(non_tensor_batch, "_replay_sample_index"),
                            row_index,
                        )
                    )
                request_id = self._manifest_json_scalar(
                    row_context.get("request_id", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if request_id is None:
                    request_id = self._manifest_row_value(
                        self._manifest_mapping_get(non_tensor_batch, "request_id"),
                        row_index,
                    )
                uid = self._manifest_row_value(self._manifest_mapping_get(non_tensor_batch, "uid"), row_index)
                response_uid = self._manifest_json_scalar(
                    row_context.get("response_uid", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if response_uid is None:
                    response_uid = self._manifest_row_value(
                        self._manifest_mapping_get(non_tensor_batch, "response_uid"),
                        row_index,
                    )
                stream_cache_key = self._manifest_json_scalar(
                    row_context.get("stream_cache_key", None)
                    if isinstance(row_context, dict)
                    else None
                )
                sample_hash = self._manifest_json_scalar(
                    row_context.get("sample_hash", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if sample_hash is None:
                    sample_hash = response_uid or uid or stream_cache_key
                if sample_hash is None:
                    sample_hash = f"input_checksum:{input_summary['checksum']}"

                packed_manifest = self._manifest_row_value(
                    self._manifest_mapping_get(
                        non_tensor_batch,
                        "_packed_row_manifests",
                    ),
                    row_index,
                )
                packed_round_index = None
                packed_page_count = None
                packed_block_indices = None
                if isinstance(packed_manifest, dict):
                    packed_round_index = self._manifest_int_or_none(
                        packed_manifest.get("packed_round_index")
                    )
                    packed_pages = packed_manifest.get("pages", [])
                    if isinstance(packed_pages, (list, tuple)):
                        packed_page_count = len(packed_pages)
                        packed_block_indices = sorted(
                            {
                                int(page["block_index"])
                                for page in packed_pages
                                if isinstance(page, dict)
                                and page.get("block_index") is not None
                            }
                        )

                noisy_diff_count = None
                noisy_valid_count = None
                noisy_diff_fraction = None
                if isinstance(extra, dict):
                    manifest_l0 = self._manifest_int_or_none(
                        extra.get("L0")
                    )
                    manifest_l1 = self._manifest_int_or_none(
                        extra.get("L1")
                    )
                    if (
                        manifest_l0 is not None
                        and manifest_l1 is not None
                        and manifest_l0 >= 0
                        and manifest_l1 > 0
                        and int(input_row.numel())
                        >= manifest_l0 + 2 * manifest_l1
                    ):
                        clean_slice = input_row[
                            manifest_l0 : manifest_l0 + manifest_l1
                        ]
                        noisy_slice = input_row[
                            manifest_l0
                            + manifest_l1 : manifest_l0
                            + 2 * manifest_l1
                        ]
                        valid_slice = torch.ones_like(
                            clean_slice,
                            dtype=torch.bool,
                        )
                        if torch.is_tensor(mask_row):
                            valid_flat = mask_row.detach().bool().reshape(-1)
                            if int(valid_flat.numel()) == manifest_l1:
                                valid_slice = valid_flat
                        noisy_valid_count = int(
                            valid_slice.sum().cpu().item()
                        )
                        noisy_diff_count = int(
                            (
                                clean_slice.ne(noisy_slice)
                                & valid_slice
                            ).sum().cpu().item()
                        )
                        noisy_diff_fraction = (
                            float(noisy_diff_count)
                            / float(noisy_valid_count)
                            if noisy_valid_count > 0
                            else 0.0
                        )

                source = self._manifest_json_scalar(
                    row_context.get("source", None)
                    if isinstance(row_context, dict)
                    else None
                )
                if source is None:
                    source = self._manifest_row_value(
                        self._manifest_mapping_get(non_tensor_batch, "data_source"),
                        row_index,
                    )

                train_step_keys = (
                    [int(train_step_key)]
                    if train_step_key is not None and not inferred_train_step_keys
                    else inferred_train_step_keys
                )
                record = {
                    "schema": "verl_replay_row_manifest_v1",
                    "path": source_type,
                    "source_type": source_type,
                    "source": source,
                    "global_step": global_step,
                    "trainer_step": global_step,
                    "sample_index": sample_index,
                    "sample_hash": sample_hash,
                    "request_id": request_id,
                    "uid": uid,
                    "response_uid": response_uid,
                    "stream_cache_key": stream_cache_key,
                    "packed_round_index": packed_round_index,
                    "packed_page_count": packed_page_count,
                    "packed_block_indices": packed_block_indices,
                    "noisy_diff_count": noisy_diff_count,
                    "noisy_valid_count": noisy_valid_count,
                    "noisy_diff_fraction": noisy_diff_fraction,
                    "row_index": int(row_context.get("row_index", row_index)) if isinstance(row_context, dict) else row_index,
                    "train_step_key": train_step_key,
                    "train_step_keys": train_step_keys,
                    "teacher_step_key": teacher_step_key,
                    "active_count": int(active_count or 0),
                    "effective_active_count": int(effective_active_count or 0),
                    "label_checksum": label_summary["checksum"],
                    "label_head": label_summary["head"],
                    "label_tail": label_summary["tail"],
                    "label_shape": label_summary["shape"],
                    "target_checksum": target_summary["checksum"],
                    "target_head": target_summary["head"],
                    "target_tail": target_summary["tail"],
                    "target_shape": target_summary["shape"],
                    "label_mask_checksum": mask_summary["checksum"],
                    "label_mask_head": mask_summary["head"],
                    "label_mask_tail": mask_summary["tail"],
                    "label_mask_shape": mask_summary["shape"],
                    "position_ids_checksum": position_summary["checksum"],
                    "position_ids_head": position_summary["head"],
                    "position_ids_tail": position_summary["tail"],
                    "position_ids_shape": position_summary["shape"],
                    "target_position_ids_checksum": target_position_summary["checksum"],
                    "target_position_ids_head": target_position_summary["head"],
                    "target_position_ids_tail": target_position_summary["tail"],
                    "input_width": input_width,
                    "input_shape": tensor_input_shape,
                    "input_row_shape": [int(dim) for dim in input_row.shape],
                    "input_ids_checksum": input_summary["checksum"],
                    "input_ids_head": input_summary["head"],
                    "input_ids_tail": input_summary["tail"],
                    "response_width": response_width,
                }
                if isinstance(row_context, dict):
                    for key in (
                        "context",
                        "chunk_index",
                        "queue_index",
                        "future_offset",
                        "base_future_offset",
                        "dst_start",
                        "copy_len",
                        "full_L1",
                        "prompt_length",
                        "prompt_tail_length",
                        "response_length",
                        "response_token_count",
                        "tail_length",
                        "response_start",
                        "response_end",
                        "local_tail_start",
                        "local_tail_end",
                        "L0",
                        "L1",
                        "line_i",
                        "trace_step_event_count",
                        "trace_active_positions_count",
                        "trace_active_label_mask_applied",
                        "trace_future_block_level_final_flush",
                    ):
                        if key in row_context:
                            record[key] = self._manifest_json_scalar(row_context.get(key))
                if extra:
                    for key, value in extra.items():
                        record[key] = self._manifest_json_scalar(value)
                lines.append(json.dumps(record, ensure_ascii=False))

            if not lines:
                return
            path = self._replay_row_manifest_path()
            os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
            lock = getattr(self, "_replay_row_manifest_lock", None)
            if lock is None:
                lock = threading.Lock()
                self._replay_row_manifest_lock = lock
            with lock:
                with open(path, "a", encoding="utf-8") as f:
                    f.write("\n".join(lines) + "\n")
        except Exception as exc:
            self._warn_replay_row_manifest(f"failed to dump row manifest: {exc!r}")

    @staticmethod
    def _gemma_replay_row_value(values: Any, row_index: int) -> Any:
        if isinstance(values, np.ndarray):
            return values.reshape(-1)[row_index]
        if isinstance(values, (list, tuple)):
            return values[row_index]
        return values

    def _build_gemma_replay_tensor_batch(self, batch: DataProto) -> dict[str, torch.Tensor]:
        payload_values = batch.non_tensor_batch.get("gemma_intermediate_replay")
        if payload_values is None:
            raise RuntimeError(
                "DiffusionGemma full intermediate replay requires producer schema "
                "gemma_intermediate_replay_v1, but no finalized replay payload was delivered. "
                "The consumer is ready; enable the Gemma SGLang capture producer."
            )
        responses = batch.batch["responses"]
        response_mask = batch.batch["response_mask"].bool()
        response_length = int(self.config.actor_rollout_ref.rollout.response_length)
        if int(responses.shape[-1]) != response_length:
            raise RuntimeError(
                "DiffusionGemma replay response width does not match rollout.response_length: "
                f"batch={int(responses.shape[-1])} config={response_length}"
            )
        block_size = int(self.config.actor_rollout_ref.actor.get("block_length", 256) or 256)
        prompt_width = int(batch.batch["input_ids"].shape[-1]) - response_length
        if prompt_width <= 0:
            raise RuntimeError("DiffusionGemma replay batch is missing its prompt prefix")
        prompt_ids = batch.batch["input_ids"][:, :prompt_width]
        prompt_mask = batch.batch["attention_mask"][:, :prompt_width].bool()

        gemma_grpo_enabled = self._gemma_nostream_grpo_enabled()
        gemma_correct_only_baseline = (
            self._gemma_correct_only_baseline_enabled()
        )
        if gemma_correct_only_baseline:
            self._validate_gemma_correct_only_baseline()
        gemma_grpo_config = (
            self._gemma_nostream_grpo_config()
            if gemma_grpo_enabled
            else None
        )
        samples: list[GemmaReplaySample] = []
        correctness: list[float] = []
        response_rewards: dict[str, float] = {}
        prompt_by_response: dict[str, str] = {}
        block_summaries: list[dict[str, Any]] = []
        token_scores = batch.batch.get("token_level_scores")
        if gemma_correct_only_baseline and token_scores is None:
            raise RuntimeError(
                "DiffusionGemma correct-only baseline requires final strict "
                "verifier scores before replay materialization"
            )
        for row_index in range(int(responses.shape[0])):
            payload = self._gemma_replay_row_value(payload_values, row_index)
            request_uid_value = self._gemma_replay_row_value(
                batch.non_tensor_batch.get("request_uid"),
                row_index,
            )
            sample_uid_value = self._gemma_replay_row_value(
                batch.non_tensor_batch.get(
                    "sample_uid",
                    batch.non_tensor_batch.get("uid"),
                ),
                row_index,
            )
            response_uid_value = self._gemma_replay_row_value(
                batch.non_tensor_batch.get("response_uid"),
                row_index,
            )
            if isinstance(payload, dict):
                request_uid_value = request_uid_value or payload.get("request_uid")
                sample_uid_value = sample_uid_value or payload.get("sample_uid")
                response_uid_value = response_uid_value or payload.get("response_uid")
            request_uid = str(request_uid_value or f"request-{row_index}")
            sample_uid = str(sample_uid_value or request_uid)
            response_uid = str(response_uid_value or request_uid)
            if gemma_correct_only_baseline:
                correctness.append(
                    float(
                        token_scores[row_index]
                        .detach()
                        .float()
                        .sum()
                        .cpu()
                        .item()
                    )
                )
            if gemma_grpo_enabled:
                payload = materialize_gemma_replay_payload(payload)
                if not isinstance(payload, dict):
                    raise RuntimeError(
                        "Gemma no-stream GRPO requires a materialized "
                        "gemma_intermediate_replay_v1 payload"
                    )
                prompt_uid = self._gemma_replay_row_value(
                    batch.non_tensor_batch.get("uid"),
                    row_index,
                )
                if prompt_uid is None:
                    raise RuntimeError(
                        "Gemma no-stream GRPO requires prompt uid metadata"
                    )
                if response_uid in response_rewards:
                    raise RuntimeError(
                        f"Gemma no-stream GRPO received duplicate response_uid={response_uid!r}"
                    )
                token_scores = batch.batch.get("token_level_scores")
                if token_scores is None:
                    raise RuntimeError(
                        "Gemma no-stream GRPO requires final rule reward scores"
                    )
                response_rewards[response_uid] = float(
                    token_scores[row_index].detach().float().sum().cpu().item()
                )
                prompt_by_response[response_uid] = str(prompt_uid)
                blocks = payload.get("blocks")
                if blocks is None:
                    blocks = [payload]
                if not isinstance(blocks, (list, tuple)):
                    raise RuntimeError(
                        "Gemma no-stream GRPO replay payload blocks must be a sequence"
                    )
                for block in blocks:
                    if not isinstance(block, dict):
                        raise RuntimeError(
                            "Gemma no-stream GRPO replay block must be a mapping"
                        )
                    block_index = int(block.get("block_index", -1))
                    denoise_forwards = int(
                        block.get(
                            "denoise_forwards",
                            block.get("steps_used", block.get("captured_rows", 0)),
                        )
                        or 0
                    )
                    new_accept_tokens = int(
                        block.get(
                            "new_accept_tokens",
                            block.get("valid_token_count", 0),
                        )
                        or 0
                    )
                    if block_index < 0 or denoise_forwards <= 0 or new_accept_tokens <= 0:
                        raise RuntimeError(
                            "Gemma no-stream GRPO requires exact positive block TPF "
                            f"metadata, got block={block_index} "
                            f"new_accept_tokens={new_accept_tokens} "
                            f"denoise_forwards={denoise_forwards}"
                        )
                    block_summaries.append(
                        {
                            "response_uid": response_uid,
                            "block_index": block_index,
                            "new_accept_tokens": new_accept_tokens,
                            "denoise_forwards": denoise_forwards,
                        }
                    )
            samples.append(
                GemmaReplaySample(
                    payload=payload,
                    prompt_ids=prompt_ids[row_index][prompt_mask[row_index]],
                    response_ids=responses[row_index],
                    response_mask=response_mask[row_index],
                    request_uid=request_uid,
                    sample_uid=sample_uid,
                    response_uid=response_uid,
                )
            )

        baseline_selection = None
        if gemma_correct_only_baseline:
            baseline_selection = select_correct_gemma_replay_samples(
                samples,
                correctness,
            )
            samples = list(baseline_selection.samples)
            if baseline_selection.kept_responses <= 0:
                raise _ZeroSignalGRPOBatch(
                    {
                        "gemma_correct_only_baseline/enabled": 1.0,
                        "gemma_correct_only_baseline/source_responses": float(
                            baseline_selection.source_responses
                        ),
                        "gemma_correct_only_baseline/kept_responses": 0.0,
                        "gemma_correct_only_baseline/dropped_responses": float(
                            baseline_selection.dropped_responses
                        ),
                        "gemma_correct_only_baseline/zero_signal_batch": 1.0,
                    }
                )

        replay = build_gemma_replay_tensor_batch(
            samples,
            response_length=response_length,
            block_size=block_size,
            delivery=self._gemma_replay_delivery(),
            pad_token_id=int(batch.meta_info.get("pad_token_id", 0) or 0),
        )
        if gemma_grpo_config is not None:
            grpo_result = compute_gemma_nostream_grpo_from_replay(
                replay,
                response_rewards=response_rewards,
                prompt_by_response=prompt_by_response,
                block_summaries=block_summaries,
                config=gemma_grpo_config,
            )
            replay = restrict_tensor_batch_to_selected_rows(replay, grpo_result)
            replay.metrics["gemma_nostream_grpo/end_to_end_actor_ready"] = 1.0
        if baseline_selection is not None:
            replay.metrics.update(
                {
                    "gemma_correct_only_baseline/enabled": 1.0,
                    "gemma_correct_only_baseline/source_responses": float(
                        baseline_selection.source_responses
                    ),
                    "gemma_correct_only_baseline/kept_responses": float(
                        baseline_selection.kept_responses
                    ),
                    "gemma_correct_only_baseline/dropped_responses": float(
                        baseline_selection.dropped_responses
                    ),
                    "gemma_correct_only_baseline/keep_fraction": (
                        float(baseline_selection.kept_responses)
                        / float(max(baseline_selection.source_responses, 1))
                    ),
                    "gemma_correct_only_baseline/zero_signal_batch": 0.0,
                    "gemma_correct_only_baseline/grpo_enabled": 0.0,
                    "gemma_correct_only_baseline/tpf_weighting_enabled": 0.0,
                    "gemma_replay/clean_filter_enabled": 1.0,
                    "gemma_replay/reward_gating_enabled": 1.0,
                }
            )
        self._last_gemma_replay_metrics = replay.metrics
        self._last_gemma_replay_row_manifest = replay.row_manifest
        self._last_gemma_replay_block_manifest = replay.block_manifest
        return replay.tensors

    @staticmethod
    def _is_gemma_stream_replay_item(item: Any) -> bool:
        if not isinstance(item, dict) or item.get("format") != "sglang_sdar_stream_chunk_v1":
            return False
        compact = item.get("sglang_sdar_replay_tensors_compact")
        return isinstance(compact, dict) and compact.get("format") in {
            "gemma_intermediate_replay_v1",
            "gemma_intermediate_replay_table_handle_v1",
        }

    @staticmethod
    def _env_flag(name: str, default: bool = False) -> bool:
        value = os.environ.get(name)
        if value is None:
            return bool(default)
        return str(value).strip().lower() in {"1", "true", "yes", "on"}

    def _gemma_stream_wave_aligned_pack_enabled(self, split_streaming_cfg: Any | None = None) -> bool:
        if split_streaming_cfg is None:
            split_streaming_cfg = self.config.trainer.get("split_gpu_streaming", {})
        enabled = split_streaming_cfg.get("gemma_stream_wave_aligned_pack", None)
        if enabled is None:
            return self._env_flag("VERL_GEMMA_STREAM_WAVE_ALIGNED_PACK", False)
        return bool(enabled)

    def _build_gemma_stream_wave_packer(
        self,
        split_streaming_cfg: Any,
    ) -> GemmaStreamWaveAlignedPacker:
        response_length = int(self.config.actor_rollout_ref.rollout.response_length)
        block_size = int(self.config.actor_rollout_ref.actor.get("block_length", 256) or 256)
        if response_length <= 0 or block_size <= 0 or response_length % block_size != 0:
            raise RuntimeError(
                "DiffusionGemma wave-aligned stream packing requires response_length "
                f"divisible by block_length, got {response_length}/{block_size}"
            )
        expected_blocks = int(
            split_streaming_cfg.get("gemma_stream_wave_aligned_block_count", 0)
            or (response_length // block_size)
        )
        expected_samples = int(
            split_streaming_cfg.get("gemma_stream_wave_aligned_sample_count", 0)
            or split_streaming_cfg.get("gemma_stream_expected_sample_count", 0)
            or 8
        )
        return GemmaStreamWaveAlignedPacker(
            expected_sample_count=expected_samples,
            expected_block_count=expected_blocks,
            allow_out_of_order=bool(
                split_streaming_cfg.get("gemma_stream_wave_aligned_allow_out_of_order", False)
            ),
        )

    @staticmethod
    def _accumulate_gemma_stream_wave_metrics(
        state: dict[str, Any],
        metrics: dict[str, float],
    ) -> None:
        for key, value in metrics.items():
            metric_name = key.split("/", 1)[1] if key.startswith("gemma_stream_wave_aligned/") else key
            state_key = f"gemma_stream_wave_aligned_{metric_name.replace('/', '_')}"
            numeric = float(value)
            if metric_name in {
                "buffered_peak_blocks",
                "buffered_peak_bytes",
                "wait_seconds_max",
                "final_coverage",
                "expected_responses",
                "expected_blocks",
                "enabled",
                "dedup_count",
                "out_of_order_arrivals",
            } or metric_name.endswith("_bucket_size"):
                state[state_key] = max(float(state.get(state_key, 0.0) or 0.0), numeric)
            else:
                state[state_key] = float(state.get(state_key, 0.0) or 0.0) + numeric

    def _build_gemma_streaming_tensor_batch(
        self,
        stream_items: list[dict[str, Any]],
    ) -> tuple[dict[str, torch.Tensor], dict[str, float]]:
        response_length = int(self.config.actor_rollout_ref.rollout.response_length)
        block_size = int(self.config.actor_rollout_ref.actor.get("block_length", 256) or 256)
        pad_token_id = int(getattr(self.tokenizer, "pad_token_id", 0) or 0)
        samples: list[GemmaReplaySample] = []
        for item_index, raw in enumerate(stream_items):
            compact = raw.get("sglang_sdar_replay_tensors_compact")
            payload = materialize_gemma_replay_payload(compact)
            if isinstance(payload, (list, tuple)):
                if len(payload) != 1:
                    raise RuntimeError(
                        "DiffusionGemma block streaming expects one replay block per queue item"
                    )
                payload = payload[0]
            if not isinstance(payload, dict) or payload.get("format") != "gemma_intermediate_replay_v1":
                raise RuntimeError(
                    "DiffusionGemma stream queue item did not materialize gemma_intermediate_replay_v1"
                )

            prompt_values = payload.get("prompt_ids", raw.get("prompt_ids", []))
            output_values = raw.get("output_ids", [])
            prompt = torch.as_tensor(prompt_values, dtype=torch.long).view(-1)
            output = torch.as_tensor(output_values, dtype=torch.long).view(-1)
            if int(output.numel()) > response_length:
                raise RuntimeError(
                    f"DiffusionGemma streamed response exceeds configured length: "
                    f"{int(output.numel())} > {response_length}"
                )
            response = torch.full((response_length,), pad_token_id, dtype=torch.long)
            response_mask = torch.zeros((response_length,), dtype=torch.bool)
            if int(output.numel()) > 0:
                response[: output.numel()] = output
                response_mask[: output.numel()] = True

            context = dict(raw.get("stream_context") or {})
            request_uid = str(
                payload.get("request_uid")
                or context.get("request_uid")
                or raw.get("request_id")
                or f"request-{item_index}"
            )
            sample_uid = str(
                payload.get("sample_uid")
                or context.get("sample_uid")
                or request_uid
            )
            response_uid = str(
                payload.get("response_uid")
                or context.get("response_uid")
                or request_uid
            )
            samples.append(
                GemmaReplaySample(
                    payload=payload,
                    prompt_ids=prompt,
                    response_ids=response,
                    response_mask=response_mask,
                    request_uid=request_uid,
                    sample_uid=sample_uid,
                    response_uid=response_uid,
                )
            )

        replay = build_gemma_replay_tensor_batch(
            samples,
            response_length=response_length,
            block_size=block_size,
            delivery="block_stream",
            pad_token_id=pad_token_id,
        )
        self._last_gemma_replay_metrics = replay.metrics
        self._last_gemma_replay_row_manifest = replay.row_manifest
        self._last_gemma_replay_block_manifest = replay.block_manifest
        return replay.tensors, replay.metrics

    def _build_t5_replay_tensor_batch(self, batch: DataProto) -> dict[str, torch.Tensor]:
        if batch.batch is None:
            raise RuntimeError("split_gpu_streaming tensor replay requires a tensor batch")
        if self._gemma_denoise_ce_enabled() and self._gemma_replay_delivery() in {
            "final_response",
            "block_stream",
        }:
            return self._build_gemma_replay_tensor_batch(batch)
        required_keys = {
            "responses",
            "response_mask",
            "input_ids",
            "attention_mask",
            "position_ids",
        }
        requires_source_hidden = self._t5_replay_requires_logits_source_hidden()
        missing = sorted(key for key in required_keys if key not in batch.batch.keys())
        if requires_source_hidden and not (
            "rollout_logits_source_hidden" in batch.batch.keys()
            or "rollout_logits_source_hidden_block_values"
            in batch.batch.keys()
        ):
            missing.append(
                "rollout_logits_source_hidden or "
                "rollout_logits_source_hidden_block_values"
            )
        if missing:
            raise RuntimeError(f"split_gpu_streaming tensor replay missing required batch keys: {missing}")
        self._attach_streaming_response_level_weights(batch)
        tensor_batch = {
            key: batch.batch[key]
            for key in self._T5_REPLAY_TENSOR_KEYS
            if key in batch.batch.keys()
        }
        for key in (
            GEMMA_SELECTED_BLOCK_INDICES,
            GEMMA_AVAILABLE_BLOCK_COUNTS,
            GEMMA_DENOISE_NOISE_SEEDS,
        ):
            if key in batch.batch.keys():
                tensor_batch[key] = batch.batch[key]
        self._ensure_gemma_block_selection(tensor_batch)
        return tensor_batch

    def _attach_streaming_response_level_weights(self, batch: DataProto) -> None:
        # Response-level CE/AEC weights are normally built by dp_actor on the
        # assembled PPO batch, but streamed t5 chunks bypass that path and the
        # bare tensor chunks carry no response_uid to rebuild from. Both
        # weightings normalize strictly within one response (1/N tokens,
        # 1/N pairs), and hold-until-tail guarantees each flush contains whole
        # responses, so building them here is exact; the weight tensors then
        # ride the chunks like any other row-aligned tensor.
        jsd_cfg = self.config.actor_rollout_ref.actor.get("generation_consistency_jsd", {}) or {}
        ce_enable = bool((jsd_cfg.get("response_level_ce", {}) or {}).get("enable", False))
        aec_cfg = jsd_cfg.get("adjacent_entropy_contraction", {}) or {}
        aec_enable = bool(aec_cfg.get("enable", False)) and bool(
            aec_cfg.get("response_level", False)
        )
        if not (ce_enable or aec_enable):
            return
        batch_keys = set(batch.batch.keys())
        need_ce = ce_enable and "response_level_ce_token_count" not in batch_keys
        need_aec = aec_enable and "response_level_aec_pair_count" not in batch_keys
        if not (need_ce or need_aec):
            return
        ntb = batch.non_tensor_batch or {}
        uid_col = ntb.get("response_uid")
        if uid_col is None:
            uid_col = ntb.get("uid")
        if uid_col is None:
            raise RuntimeError(
                "streaming response-level weighting requires response_uid rows "
                "on the consumer flush batch"
            )
        response_uids = list(np.asarray(uid_col).reshape(-1))
        # Carry per-row COUNT scalars, not [N, L] weight tensors: a positional
        # tensor must survive row permutation/slicing/shm in perfect alignment
        # with five mask tensors (the chunk_size>1 finite-positive failures);
        # a per-row scalar is alignment-proof and the worker rebuilds the exact
        # 1/count weights from the chunk's own masks at ingestion.
        if need_ce:
            token_per_row = batch.batch["response_mask"].to(dtype=torch.float32).sum(dim=-1)
            ce_totals: dict[Any, float] = {}
            for row, uid in enumerate(response_uids):
                ce_totals[uid] = ce_totals.get(uid, 0.0) + float(token_per_row[row])
            if any(total <= 0.0 for total in ce_totals.values()):
                raise RuntimeError(
                    "streaming response-level CE found a zero-active-token response"
                )
            batch.batch["response_level_ce_token_count"] = torch.tensor(
                [[ce_totals[uid]] for uid in response_uids], dtype=torch.float32
            )
        if need_aec:
            for required in ("adjacent_entropy_pair_mask", "adjacent_entropy_pair_ids"):
                if required not in batch_keys:
                    raise RuntimeError(
                        f"streaming response-level AEC weighting is missing {required}"
                    )
            pair_mask = batch.batch["adjacent_entropy_pair_mask"]
            pair_ids = batch.batch["adjacent_entropy_pair_ids"]
            valid = pair_mask.bool() & pair_ids.ge(0)
            pair_sets: dict[Any, set[int]] = {}
            for row, uid in enumerate(response_uids):
                row_ids = pair_ids[row][valid[row]].detach().cpu().unique().tolist()
                if row_ids:
                    pair_sets.setdefault(uid, set()).update(int(v) for v in row_ids)
            batch.batch["response_level_aec_pair_count"] = torch.tensor(
                [[float(len(pair_sets.get(uid, ())))] for uid in response_uids],
                dtype=torch.float32,
            )

    def _t5_replay_requires_logits_source_hidden(self) -> bool:
        jsd_cfg = self.config.actor_rollout_ref.actor.get("generation_consistency_jsd", {})
        if not bool(jsd_cfg.get("enable", False)):
            return False
        probe_cfg = jsd_cfg.get("entropy_gated_rkl_probe", {}) or {}
        objective_cfg = jsd_cfg.get("entropy_gated_rkl", {}) or {}
        if bool(probe_cfg.get("enable", False)) or bool(
            objective_cfg.get("enable", False)
        ):
            return True
        if str(jsd_cfg.get("objective", "full_jsd")) != "trace_future_ce":
            return False
        return not bool(jsd_cfg.get("trace_future_hard_label_ce", False))

    def _count_t5_replay_active_tokens(self, tensor_batch: dict[str, torch.Tensor]) -> int:
        if GEMMA_REPLAY_SCHEMA_KEY in tensor_batch:
            required = {
                "gemma_replay_row_valid",
                "gemma_replay_valid_masks",
                "response_mask",
            }
            missing = sorted(required - tensor_batch.keys())
            if missing:
                raise RuntimeError(f"DiffusionGemma replay tensor batch missing {missing}")
            row_valid = tensor_batch["gemma_replay_row_valid"].bool()
            valid_masks = tensor_batch["gemma_replay_valid_masks"].bool()
            response_mask = tensor_batch["response_mask"].bool()
            if valid_masks.shape[:2] != row_valid.shape or valid_masks.shape[::2] != response_mask.shape:
                raise RuntimeError(
                    "DiffusionGemma replay row/token mask shapes are inconsistent: "
                    f"rows={tuple(row_valid.shape)} valid={tuple(valid_masks.shape)} "
                    f"targets={tuple(response_mask.shape)}"
                )
            active = valid_masks & row_valid.unsqueeze(-1) & response_mask.unsqueeze(1)
            return int(active.sum().detach().cpu().item())
        responses = tensor_batch["responses"]
        attention_response_mask = tensor_batch["attention_mask"][:, -responses.shape[-1]:]
        active = attention_response_mask.bool() & responses.ge(0)
        if "response_mask" in tensor_batch:
            active &= tensor_batch["response_mask"].bool()
        if self._gemma_denoise_ce_enabled():
            self._ensure_gemma_block_selection(tensor_batch)
            selected_mask = gemma_selected_token_mask(
                active,
                tensor_batch[GEMMA_SELECTED_BLOCK_INDICES],
                int(self.config.actor_rollout_ref.actor.get("block_length", 256) or 256),
            )
            return int(selected_mask.sum().detach().cpu().item())
        source_hidden = tensor_batch.get("rollout_logits_source_hidden")
        if self._t5_replay_requires_logits_source_hidden() and source_hidden is not None:
            active = active & source_hidden.detach().float().abs().sum(dim=-1).gt(0)
        elif self._t5_replay_requires_logits_source_hidden():
            source_active = self._t5_sparse_logits_source_active_mask(tensor_batch, active.shape)
            if source_active is not None:
                active = active & source_active
        quality_mask = tensor_batch.get("rollout_quality_mask")
        if quality_mask is not None:
            active = active & quality_mask.bool()
        return int(active.sum().detach().cpu().item())

    @classmethod
    def _t5_sparse_logits_source_active_mask(
        cls,
        tensor_batch: dict[str, torch.Tensor],
        shape: torch.Size | tuple[int, int],
    ) -> torch.Tensor | None:
        values = tensor_batch.get("rollout_logits_source_hidden_sparse_values")
        rows = tensor_batch.get("rollout_logits_source_hidden_sparse_rows")
        positions = tensor_batch.get("rollout_logits_source_hidden_sparse_positions")
        if not (torch.is_tensor(values) and torch.is_tensor(rows) and torch.is_tensor(positions)):
            return None
        row_count = int(shape[0])
        response_len = int(shape[1])
        active = torch.zeros((row_count, response_len), dtype=torch.bool)
        if int(values.shape[0]) <= 0:
            return active
        rows_cpu = rows.detach().cpu().long().view(-1)
        positions_cpu = positions.detach().cpu().long().view(-1)
        if int(rows_cpu.numel()) != int(values.shape[0]) or int(positions_cpu.numel()) != int(values.shape[0]):
            raise RuntimeError(
                "sparse rollout_logits_source_hidden index count mismatch: "
                f"values={tuple(values.shape)} rows={tuple(rows.shape)} positions={tuple(positions.shape)}"
            )
        valid = rows_cpu.ge(0) & rows_cpu.lt(row_count) & positions_cpu.ge(0) & positions_cpu.lt(response_len)
        if not bool(valid.all()):
            raise RuntimeError(
                "sparse rollout_logits_source_hidden indices out of range: "
                f"target_shape={(row_count, response_len)}"
            )
        if int(rows_cpu.numel()) > 0:
            linear = rows_cpu * int(response_len) + positions_cpu
            if int(torch.unique(linear).numel()) != int(rows_cpu.numel()):
                raise RuntimeError("sparse rollout_logits_source_hidden contains duplicate row/position entries")
            active[rows_cpu, positions_cpu] = True
        return active

    def _validate_forced_streaming_t5_tensor_batch(
        self,
        tensor_batch: dict[str, torch.Tensor],
        *,
        force_trace_replay_step_keys: set[int],
        row_contexts: list[dict[str, Any]] | None = None,
    ) -> None:
        if not force_trace_replay_step_keys:
            return
        responses = tensor_batch["responses"]
        attention_response_mask = tensor_batch["attention_mask"][:, -responses.shape[-1]:]
        active = attention_response_mask.bool() & responses.ge(0)
        quality_mask = tensor_batch.get("rollout_quality_mask")
        if quality_mask is not None:
            active = active & quality_mask.bool()
        active_count = int(active.sum().detach().cpu().item())
        step_keys = sorted(int(k) for k in force_trace_replay_step_keys)
        if active_count <= 0:
            return
        if not self._t5_replay_requires_logits_source_hidden():
            return
        source_hidden = tensor_batch.get("rollout_logits_source_hidden")
        if source_hidden is None:
            nonzero_source = self._t5_sparse_logits_source_active_mask(tensor_batch, active.shape)
            if nonzero_source is None:
                raise RuntimeError(
                    "split_gpu_streaming forced chunk missing rollout_logits_source_hidden "
                    f"for train_step_keys={step_keys}"
                )
        else:
            if source_hidden.shape[:2] != active.shape:
                raise RuntimeError(
                    "split_gpu_streaming forced chunk logits_source_hidden shape mismatch: "
                    f"hidden_shape={tuple(source_hidden.shape)} active_shape={tuple(active.shape)}"
                )
            nonzero_source = source_hidden.detach().float().abs().sum(dim=-1).gt(0)
        missing_source = active & nonzero_source.logical_not()
        missing_count = int(missing_source.sum().detach().cpu().item())
        if missing_count > 0:
            row_details: list[str] = []
            row_missing = missing_source.sum(dim=1).detach().cpu().long().view(-1)
            row_active = active.sum(dim=1).detach().cpu().long().view(-1)
            source_active = active & nonzero_source
            row_nonzero = source_active.sum(dim=1).detach().cpu().long().view(-1)
            contexts = row_contexts or []
            for row_idx, missing_i in enumerate(row_missing.tolist()):
                if int(missing_i) <= 0:
                    continue
                ctx = contexts[row_idx] if row_idx < len(contexts) and isinstance(contexts[row_idx], dict) else {}
                row_details.append(
                    "row="
                    f"{row_idx}"
                    f" train={ctx.get('train_step_key', 'n/a')}"
                    f" teacher={ctx.get('teacher_step_key', 'n/a')}"
                    f" missing={int(missing_i)}/{int(row_active[row_idx].item())}"
                    f" nonzero={int(row_nonzero[row_idx].item())}"
                    f" dst={ctx.get('dst_start', 'n/a')}"
                    f" copy={ctx.get('copy_len', 'n/a')}"
                    f" local=({ctx.get('local_tail_start', 'n/a')},{ctx.get('local_tail_end', 'n/a')})"
                    f" L1={ctx.get('L1', 'n/a')}"
                    f" prompt_tail={ctx.get('prompt_tail_length', 'n/a')}"
                )
                if len(row_details) >= 8:
                    break
            raise RuntimeError(
                "split_gpu_streaming forced chunk is missing rollout_logits_source_hidden "
                f"on active t5 label positions; missing={missing_count}/{active_count} "
                f"for train_step_keys={step_keys}; "
                f"rows={row_details}"
            )

    def _iter_t5_replay_tensor_chunks(self, tensor_batch: dict[str, torch.Tensor], chunk_size: int):
        total_rows = int(tensor_batch["input_ids"].shape[0])
        sparse_values = tensor_batch.get("rollout_logits_source_hidden_sparse_values")
        sparse_rows = tensor_batch.get("rollout_logits_source_hidden_sparse_rows")
        sparse_positions = tensor_batch.get("rollout_logits_source_hidden_sparse_positions")
        sparse_shape = tensor_batch.get("rollout_logits_source_hidden_sparse_shape")
        if (
            torch.is_tensor(sparse_values)
            and torch.is_tensor(sparse_rows)
            and torch.is_tensor(sparse_positions)
            and torch.is_tensor(sparse_shape)
        ):
            shape = sparse_shape.detach().cpu().long().view(-1)
            if int(shape.numel()) != 3:
                raise RuntimeError(
                    "rollout_logits_source_hidden_sparse_shape must have 3 elements, "
                    f"got shape={tuple(sparse_shape.shape)}"
                )
            if int(shape[0].item()) != total_rows:
                raise RuntimeError(
                    "rollout_logits_source_hidden_sparse_shape row count mismatch before chunking: "
                    f"sparse_rows={int(shape[0].item())} total_rows={total_rows}"
                )
            value_count = int(sparse_values.shape[0])
            rows_flat = sparse_rows.detach().cpu().long().view(-1)
            positions_flat = sparse_positions.detach().cpu().long().view(-1)
            if int(rows_flat.numel()) != value_count or int(positions_flat.numel()) != value_count:
                raise RuntimeError(
                    "sparse rollout_logits_source_hidden index count mismatch before chunking: "
                    f"values={tuple(sparse_values.shape)} rows={tuple(sparse_rows.shape)} "
                    f"positions={tuple(sparse_positions.shape)}"
                )
            response_len = int(shape[1].item())
            valid = rows_flat.ge(0) & rows_flat.lt(total_rows) & positions_flat.ge(0) & positions_flat.lt(response_len)
            if not bool(valid.all()):
                raise RuntimeError(
                    "sparse rollout_logits_source_hidden indices out of range before chunking: "
                    f"sparse_shape={tuple(int(x.item()) for x in shape)}"
                )
            if value_count > 0:
                linear = rows_flat * int(response_len) + positions_flat
                if int(torch.unique(linear).numel()) != value_count:
                    raise RuntimeError("sparse rollout_logits_source_hidden contains duplicate row/position entries")
        for start in range(0, total_rows, chunk_size):
            end = min(start + chunk_size, total_rows)
            chunk = {}
            for key, value in tensor_batch.items():
                if key in self._T5_SPARSE_LOGITS_SOURCE_KEYS:
                    continue
                chunk[key] = value[start:end].contiguous()
            if (
                torch.is_tensor(sparse_values)
                and torch.is_tensor(sparse_rows)
                and torch.is_tensor(sparse_positions)
                and torch.is_tensor(sparse_shape)
            ):
                row_mask = sparse_rows.ge(start) & sparse_rows.lt(end)
                selected = torch.nonzero(row_mask, as_tuple=False).flatten()
                chunk["rollout_logits_source_hidden_sparse_values"] = sparse_values.index_select(0, selected).contiguous()
                chunk["rollout_logits_source_hidden_sparse_rows"] = (
                    sparse_rows.index_select(0, selected) - int(start)
                ).contiguous()
                chunk["rollout_logits_source_hidden_sparse_positions"] = sparse_positions.index_select(0, selected).contiguous()
                shape = sparse_shape.detach().cpu().long().view(-1).clone()
                if int(shape.numel()) != 3:
                    raise RuntimeError(
                        "rollout_logits_source_hidden_sparse_shape must have 3 elements, "
                        f"got shape={tuple(sparse_shape.shape)}"
                    )
                shape[0] = int(end - start)
                chunk["rollout_logits_source_hidden_sparse_shape"] = shape
            if self._count_t5_replay_active_tokens(chunk) <= 0:
                continue
            yield chunk

    @staticmethod
    def _estimate_tensor_chunk_bytes(tensor_chunk: dict[str, torch.Tensor]) -> int:
        total_bytes = 0
        for value in tensor_chunk.values():
            if torch.is_tensor(value):
                total_bytes += int(value.numel()) * int(value.element_size())
        return total_bytes

    def _actor_sparse_logits_source_hidden_enabled(self, split_streaming_cfg: Any | None = None) -> bool:
        if split_streaming_cfg is None:
            split_streaming_cfg = self.config.trainer.get("split_gpu_streaming", {})
        return (
            bool(split_streaming_cfg.get("actor_sparse_logits_source_hidden", False))
            and self._t5_replay_requires_logits_source_hidden()
        )

    def _maybe_compress_t5_logits_source_hidden(
        self,
        tensor_batch: dict[str, torch.Tensor],
        *,
        split_streaming_cfg: Any | None = None,
    ) -> dict[str, float]:
        metrics = {
            "actor_sparse_logits_source_hidden_enabled": 0.0,
            "actor_sparse_logits_source_hidden_batches": 0.0,
            "actor_sparse_logits_source_hidden_values": 0.0,
            "actor_sparse_logits_source_hidden_dense_bytes": 0.0,
            "actor_sparse_logits_source_hidden_sparse_bytes": 0.0,
            "actor_sparse_logits_source_hidden_saved_bytes": 0.0,
            "actor_sparse_logits_source_hidden_compress_seconds": 0.0,
        }
        if not self._actor_sparse_logits_source_hidden_enabled(split_streaming_cfg):
            return metrics
        source_hidden = tensor_batch.get("rollout_logits_source_hidden")
        if not torch.is_tensor(source_hidden):
            return metrics
        compress_start = time.perf_counter()
        if source_hidden.dim() != 3:
            raise RuntimeError(
                "rollout_logits_source_hidden must be [rows, response_len, hidden] "
                f"before sparse compression, got shape={tuple(source_hidden.shape)}"
            )
        row_count, response_len, hidden_size = (int(dim) for dim in source_hidden.shape)
        nonzero = source_hidden.detach().float().abs().sum(dim=-1).gt(0)
        responses = tensor_batch.get("responses")
        if torch.is_tensor(responses):
            attention_response_mask = tensor_batch.get("attention_mask")
            if torch.is_tensor(attention_response_mask):
                attention_response_mask = attention_response_mask[:, -int(responses.shape[-1]) :]
            if torch.is_tensor(attention_response_mask) and tuple(attention_response_mask.shape) == tuple(nonzero.shape):
                active = attention_response_mask.bool() & responses.ge(0)
                quality_mask = tensor_batch.get("rollout_quality_mask")
                if torch.is_tensor(quality_mask) and tuple(quality_mask.shape) == tuple(active.shape):
                    active = active & quality_mask.bool()
                nonzero = nonzero & active
        indices = torch.nonzero(nonzero, as_tuple=False)
        if int(indices.numel()) > 0:
            rows = indices[:, 0].to(dtype=torch.long).contiguous()
            positions = indices[:, 1].to(dtype=torch.long).contiguous()
            values = source_hidden[rows, positions].contiguous()
        else:
            rows = torch.empty((0,), dtype=torch.long)
            positions = torch.empty((0,), dtype=torch.long)
            values = torch.empty((0, hidden_size), dtype=source_hidden.dtype)
        shape = torch.tensor([row_count, response_len, hidden_size], dtype=torch.long)
        dense_bytes = int(source_hidden.numel()) * int(source_hidden.element_size())
        sparse_bytes = (
            int(values.numel()) * int(values.element_size())
            + int(rows.numel()) * int(rows.element_size())
            + int(positions.numel()) * int(positions.element_size())
            + int(shape.numel()) * int(shape.element_size())
        )
        tensor_batch.pop("rollout_logits_source_hidden", None)
        tensor_batch["rollout_logits_source_hidden_sparse_values"] = values
        tensor_batch["rollout_logits_source_hidden_sparse_rows"] = rows
        tensor_batch["rollout_logits_source_hidden_sparse_positions"] = positions
        tensor_batch["rollout_logits_source_hidden_sparse_shape"] = shape
        metrics.update(
            {
                "actor_sparse_logits_source_hidden_enabled": 1.0,
                "actor_sparse_logits_source_hidden_batches": 1.0,
                "actor_sparse_logits_source_hidden_values": float(values.shape[0]),
                "actor_sparse_logits_source_hidden_dense_bytes": float(dense_bytes),
                "actor_sparse_logits_source_hidden_sparse_bytes": float(sparse_bytes),
                "actor_sparse_logits_source_hidden_saved_bytes": float(max(0, dense_bytes - sparse_bytes)),
                "actor_sparse_logits_source_hidden_compress_seconds": float(time.perf_counter() - compress_start),
            }
        )
        return metrics

    @staticmethod
    def _normalize_actor_tensor_chunk_store(store: Any) -> str:
        store = str(store or "tensor").strip().lower()
        if store in {"", "tensor"}:
            return "tensor"
        if store in {"shm", "shared_memory"}:
            return "shm"
        raise ValueError(
            "trainer.split_gpu_streaming.actor_tensor_chunk_store must be one of "
            f"tensor|shm, got {store!r}"
        )

    def _actor_tensor_chunk_store_mode(self, split_streaming_cfg: Any | None = None) -> str:
        if split_streaming_cfg is None:
            split_streaming_cfg = self.config.trainer.get("split_gpu_streaming", {})
        return self._normalize_actor_tensor_chunk_store(
            split_streaming_cfg.get("actor_tensor_chunk_store", "tensor")
        )

    def _validate_gemma_replay_transport(self, split_streaming_cfg: Any) -> dict[str, float]:
        store = self._actor_tensor_chunk_store_mode(split_streaming_cfg)
        if store != "tensor":
            raise RuntimeError(
                "DiffusionGemma cross-node replay forbids actor_tensor_chunk_store=shm; "
                "use tensor/Ray object transport"
            )
        metrics = {
            "gemma_replay/transport_ray_tensor": 1.0,
            "gemma_replay/transport_shm": 0.0,
            "gemma_replay/transport_tcp": 0.0,
        }
        nnodes = int(self.config.trainer.get("nnodes", 1) or 1)
        if nnodes <= 1:
            return metrics
        interface_values = {
            "NCCL_SOCKET_IFNAME": os.environ.get("NCCL_SOCKET_IFNAME", ""),
            "GLOO_SOCKET_IFNAME": os.environ.get("GLOO_SOCKET_IFNAME", ""),
        }
        interface_sets = {
            key: frozenset(item.strip() for item in str(value).split(",") if item.strip())
            for key, value in interface_values.items()
        }
        interfaces_ok = all(interface_sets.values()) and len(set(interface_sets.values())) == 1
        ib_disabled = str(os.environ.get("NCCL_IB_DISABLE", "0")).strip().lower()
        if not interfaces_ok or ib_disabled not in {"1", "true", "yes", "on"}:
            raise RuntimeError(
                "DiffusionGemma cross-node replay requires the validated TCP path: "
                "NCCL_SOCKET_IFNAME and GLOO_SOCKET_IFNAME set to the same interface "
                "and NCCL_IB_DISABLE=1: "
                f"interfaces={interface_values} "
                f"NCCL_IB_DISABLE={ib_disabled!r}"
            )
        metrics["gemma_replay/transport_tcp"] = 1.0
        return metrics

    @staticmethod
    def _normalize_actor_tensor_chunk_dispatch(mode: Any) -> str:
        mode = str(mode or "dp").strip().lower()
        if mode in {"dp", "shard", "sharded", "data_parallel"}:
            return "dp"
        if mode in {"one_to_all", "all", "replicate", "replicated"}:
            return "one_to_all"
        raise ValueError(
            "trainer.split_gpu_streaming.actor_tensor_chunk_dispatch must be one of "
            f"dp|one_to_all, got {mode!r}"
        )

    def _actor_tensor_chunk_dispatch_mode(self, split_streaming_cfg: Any | None = None) -> str:
        if split_streaming_cfg is None:
            split_streaming_cfg = self.config.trainer.get("split_gpu_streaming", {})
        return self._normalize_actor_tensor_chunk_dispatch(
            split_streaming_cfg.get("actor_tensor_chunk_dispatch", "dp")
        )

    def _zero_loss_t5_tensor_shard_from_template(self, tensor_chunk: dict[str, torch.Tensor]) -> dict[str, torch.Tensor]:
        total_rows = int(tensor_chunk["input_ids"].shape[0])
        if total_rows > 0:
            shard = self._slice_t5_tensor_chunk_rows(tensor_chunk, 0, 1)
        else:
            shard = {}
            for key, value in tensor_chunk.items():
                if key in self._T5_SPARSE_LOGITS_SOURCE_KEYS:
                    continue
                if torch.is_tensor(value) and value.dim() > 0:
                    shard[key] = torch.zeros((1, *tuple(value.shape[1:])), dtype=value.dtype)
                else:
                    shard[key] = value.clone() if torch.is_tensor(value) else value

        for key in ("response_mask", "rollout_quality_mask"):
            value = shard.get(key)
            if torch.is_tensor(value):
                shard[key] = torch.zeros_like(value, dtype=value.dtype)
        for key in (
            "gemma_replay_row_valid",
            "gemma_replay_valid_masks",
            "gemma_replay_done_masks",
            "gemma_replay_self_conditioning_present",
            "gemma_replay_block_real",
            "gemma_replay_reward_ready",
        ):
            value = shard.get(key)
            if torch.is_tensor(value):
                shard[key] = torch.zeros_like(value, dtype=value.dtype)
        for key in ("rollout_self_conditioning_signal", "rollout_logits_source_hidden"):
            value = shard.get(key)
            if torch.is_tensor(value):
                shard[key] = torch.zeros_like(value)
        value = shard.get("gemma_replay_self_conditioning_signal")
        if torch.is_tensor(value):
            shard["gemma_replay_self_conditioning_signal"] = torch.zeros_like(value)
        responses = shard.get("responses")
        if torch.is_tensor(responses):
            shard["responses"] = torch.full_like(responses, -100)
        for key, fill_value in (
            (GEMMA_SELECTED_BLOCK_INDICES, 0),
            (GEMMA_AVAILABLE_BLOCK_COUNTS, 1),
            (GEMMA_DENOISE_NOISE_SEEDS, 0),
        ):
            value = shard.get(key)
            if torch.is_tensor(value):
                shard[key] = torch.full_like(value, fill_value)
        sparse_shape = tensor_chunk.get("rollout_logits_source_hidden_sparse_shape")
        if torch.is_tensor(sparse_shape):
            shape = sparse_shape.detach().cpu().long().view(-1).clone()
            if int(shape.numel()) == 3:
                shape[0] = 1
            shard["rollout_logits_source_hidden_sparse_shape"] = shape
            values = tensor_chunk.get("rollout_logits_source_hidden_sparse_values")
            hidden = int(shape[2].item()) if int(shape.numel()) == 3 else 0
            dtype = values.dtype if torch.is_tensor(values) else torch.bfloat16
            shard["rollout_logits_source_hidden_sparse_values"] = torch.empty((0, hidden), dtype=dtype)
            shard["rollout_logits_source_hidden_sparse_rows"] = torch.empty((0,), dtype=torch.long)
            shard["rollout_logits_source_hidden_sparse_positions"] = torch.empty((0,), dtype=torch.long)
        shard["_t5_tensor_real_rows"] = torch.zeros((1,), dtype=torch.long)
        return shard

    def _slice_t5_tensor_chunk_rows(
        self,
        tensor_chunk: dict[str, torch.Tensor],
        start: int,
        end: int,
    ) -> dict[str, torch.Tensor]:
        total_rows = int(tensor_chunk["input_ids"].shape[0])
        start = max(0, min(int(start), total_rows))
        end = max(start, min(int(end), total_rows))
        shard: dict[str, torch.Tensor] = {}
        for key, value in tensor_chunk.items():
            if key in self._T5_SPARSE_LOGITS_SOURCE_KEYS:
                continue
            if torch.is_tensor(value) and value.dim() > 0 and int(value.shape[0]) == total_rows:
                shard[key] = value[start:end].contiguous()
            else:
                shard[key] = value.clone() if torch.is_tensor(value) else value

        sparse_values = tensor_chunk.get("rollout_logits_source_hidden_sparse_values")
        sparse_rows = tensor_chunk.get("rollout_logits_source_hidden_sparse_rows")
        sparse_positions = tensor_chunk.get("rollout_logits_source_hidden_sparse_positions")
        sparse_shape = tensor_chunk.get("rollout_logits_source_hidden_sparse_shape")
        if (
            torch.is_tensor(sparse_values)
            and torch.is_tensor(sparse_rows)
            and torch.is_tensor(sparse_positions)
            and torch.is_tensor(sparse_shape)
        ):
            row_mask = sparse_rows.ge(start) & sparse_rows.lt(end)
            selected = torch.nonzero(row_mask, as_tuple=False).flatten()
            shard["rollout_logits_source_hidden_sparse_values"] = (
                sparse_values.index_select(0, selected).contiguous()
            )
            shard["rollout_logits_source_hidden_sparse_rows"] = (
                sparse_rows.index_select(0, selected) - int(start)
            ).contiguous()
            shard["rollout_logits_source_hidden_sparse_positions"] = (
                sparse_positions.index_select(0, selected).contiguous()
            )
            shape = sparse_shape.detach().cpu().long().view(-1).clone()
            if int(shape.numel()) == 3:
                shape[0] = int(end - start)
            shard["rollout_logits_source_hidden_sparse_shape"] = shape
        if GEMMA_REPLAY_SCHEMA_KEY in shard:
            row_valid = shard.get("gemma_replay_row_valid")
            if not torch.is_tensor(row_valid):
                raise RuntimeError("DiffusionGemma replay shard is missing gemma_replay_row_valid")
            real_rows = int(row_valid.detach().cpu().bool().sum().item())
        else:
            real_rows = int(end - start)
        shard["_t5_tensor_real_rows"] = torch.tensor([real_rows], dtype=torch.long)
        return shard

    def _index_t5_tensor_chunk_rows(
        self,
        tensor_chunk: dict[str, torch.Tensor],
        row_indices: list[int],
    ) -> dict[str, torch.Tensor]:
        """Select arbitrary replay rows and remap sparse COO row indices."""
        total_rows = int(tensor_chunk["input_ids"].shape[0])
        selected_rows = torch.as_tensor(row_indices, dtype=torch.long)
        if selected_rows.numel() and bool(
            (
                selected_rows.lt(0)
                | selected_rows.ge(total_rows)
            ).any()
        ):
            raise RuntimeError(
                f"packed replay row indices out of range for rows={total_rows}"
            )
        shard: dict[str, torch.Tensor] = {}
        for key, value in tensor_chunk.items():
            if key in self._T5_SPARSE_LOGITS_SOURCE_KEYS:
                continue
            if (
                torch.is_tensor(value)
                and value.dim() > 0
                and int(value.shape[0]) == total_rows
            ):
                shard[key] = value.index_select(
                    0,
                    selected_rows.to(device=value.device),
                ).contiguous()
            else:
                shard[key] = value.clone() if torch.is_tensor(value) else value

        sparse_values = tensor_chunk.get(
            "rollout_logits_source_hidden_sparse_values"
        )
        sparse_rows = tensor_chunk.get(
            "rollout_logits_source_hidden_sparse_rows"
        )
        sparse_positions = tensor_chunk.get(
            "rollout_logits_source_hidden_sparse_positions"
        )
        sparse_shape = tensor_chunk.get(
            "rollout_logits_source_hidden_sparse_shape"
        )
        if all(
            torch.is_tensor(value)
            for value in (
                sparse_values,
                sparse_rows,
                sparse_positions,
                sparse_shape,
            )
        ):
            old_to_new = torch.full(
                (total_rows,),
                -1,
                dtype=torch.long,
                device=sparse_rows.device,
            )
            if selected_rows.numel():
                old_to_new[
                    selected_rows.to(device=sparse_rows.device)
                ] = torch.arange(
                    selected_rows.numel(),
                    dtype=torch.long,
                    device=sparse_rows.device,
                )
            remapped_rows = old_to_new[sparse_rows.long()]
            keep = remapped_rows.ge(0)
            selected = torch.nonzero(keep, as_tuple=False).flatten()
            shard[
                "rollout_logits_source_hidden_sparse_values"
            ] = sparse_values.index_select(0, selected).contiguous()
            shard[
                "rollout_logits_source_hidden_sparse_rows"
            ] = remapped_rows.index_select(0, selected).contiguous()
            shard[
                "rollout_logits_source_hidden_sparse_positions"
            ] = sparse_positions.index_select(0, selected).contiguous()
            shape = sparse_shape.detach().cpu().long().view(-1).clone()
            if int(shape.numel()) == 3:
                shape[0] = int(selected_rows.numel())
            shard["rollout_logits_source_hidden_sparse_shape"] = shape
        shard["_t5_tensor_real_rows"] = torch.tensor(
            [int(selected_rows.numel())],
            dtype=torch.long,
        )
        return shard

    def _pad_gemma_replay_tensor_shard(
        self,
        tensor_chunk: dict[str, torch.Tensor],
        shard: dict[str, torch.Tensor],
        target_block_slots: int,
    ) -> dict[str, torch.Tensor]:
        current_slots = int(shard["input_ids"].shape[0])
        target_block_slots = max(int(target_block_slots), 1)
        if current_slots >= target_block_slots:
            return shard
        padding = self._zero_loss_t5_tensor_shard_from_template(tensor_chunk)
        pad_slots = target_block_slots - current_slots
        padded: dict[str, torch.Tensor] = {}
        for key, value in shard.items():
            if key == "_t5_tensor_real_rows":
                padded[key] = value
                continue
            pad_value = padding.get(key)
            if (
                torch.is_tensor(value)
                and torch.is_tensor(pad_value)
                and value.dim() > 0
                and int(value.shape[0]) == current_slots
                and int(pad_value.shape[0]) == 1
            ):
                repeats = (pad_slots, *([1] * (pad_value.dim() - 1)))
                padded[key] = torch.cat((value, pad_value.repeat(repeats)), dim=0).contiguous()
            else:
                padded[key] = value
        if current_slots == 0:
            for key, pad_value in padding.items():
                if key in padded or key == "_t5_tensor_real_rows":
                    continue
                if torch.is_tensor(pad_value) and pad_value.dim() > 0 and int(pad_value.shape[0]) == 1:
                    repeats = (target_block_slots, *([1] * (pad_value.dim() - 1)))
                    padded[key] = pad_value.repeat(repeats).contiguous()
                else:
                    padded[key] = pad_value
        padded["_t5_tensor_real_rows"] = shard.get(
            "_t5_tensor_real_rows",
            torch.zeros((1,), dtype=torch.long),
        )
        return padded

    def _split_t5_tensor_chunk_for_actor_dp(
        self,
        tensor_chunk: dict[str, torch.Tensor],
        world_size: int,
    ) -> list[dict[str, torch.Tensor]]:
        world_size = max(int(world_size), 1)
        total_rows = int(tensor_chunk["input_ids"].shape[0])
        if GEMMA_REPLAY_SCHEMA_KEY in tensor_chunk:
            # FSDP ranks must execute identical prefix-cache, decoder-forward,
            # and backward counts. Give every rank ceil(blocks/world) block
            # slots and zero-loss pad the final shards.
            slots_per_rank = max(1, (total_rows + world_size - 1) // world_size)
            shards = []
            for rank_idx in range(world_size):
                start = min(rank_idx * slots_per_rank, total_rows)
                end = min(start + slots_per_rank, total_rows)
                if end > start:
                    shard = self._slice_t5_tensor_chunk_rows(tensor_chunk, start, end)
                else:
                    shard = self._zero_loss_t5_tensor_shard_from_template(tensor_chunk)
                    shard = {
                        key: value[:0].contiguous()
                        if torch.is_tensor(value)
                        and value.dim() > 0
                        and key != "_t5_tensor_real_rows"
                        and int(value.shape[0]) == 1
                        else value
                        for key, value in shard.items()
                    }
                    shard["_t5_tensor_real_rows"] = torch.zeros((1,), dtype=torch.long)
                shards.append(
                    self._pad_gemma_replay_tensor_shard(
                        tensor_chunk,
                        shard,
                        slots_per_rank,
                    )
                )
            padded_slot_counts = {int(shard["input_ids"].shape[0]) for shard in shards}
            if padded_slot_counts != {slots_per_rank}:
                raise RuntimeError(
                    "DiffusionGemma FSDP replay shard padding is asymmetric: "
                    f"slot_counts={sorted(padded_slot_counts)} expected={slots_per_rank}"
                )
            return shards
        row_cost = tensor_chunk.get("_packed_row_cost")
        if (
            torch.is_tensor(row_cost)
            and int(row_cost.numel()) == total_rows
            and total_rows > 0
        ):
            # Direct tensor RPCs may carry uneven row counts because each rank
            # performs one actor call. Unlike contiguous DataProto.chunk
            # dispatch, no fixed per-rank capacity is required here.
            costs = row_cost.detach().cpu().double().view(-1)
            assignments: list[list[int]] = [
                [] for _ in range(world_size)
            ]
            assigned_costs = [0.0] * world_size
            for row_index in sorted(
                range(total_rows),
                key=lambda index: (-float(costs[index].item()), index),
            ):
                rank_index = min(
                    range(world_size),
                    key=lambda rank: (
                        assigned_costs[rank],
                        len(assignments[rank]),
                        rank,
                    ),
                )
                assignments[rank_index].append(int(row_index))
                assigned_costs[rank_index] += float(
                    costs[row_index].item()
                )
            shards = []
            for indices_for_rank in assignments:
                if indices_for_rank:
                    shard = self._index_t5_tensor_chunk_rows(
                        tensor_chunk,
                        indices_for_rank,
                    )
                else:
                    shard = self._zero_loss_t5_tensor_shard_from_template(
                        tensor_chunk
                    )
                shard["_packed_rank_cost"] = torch.tensor(
                    [
                        sum(
                            float(costs[index].item())
                            for index in indices_for_rank
                        )
                    ],
                    dtype=torch.float64,
                )
                shards.append(shard)
            return shards
        base = total_rows // world_size
        remainder = total_rows % world_size
        if self._gemma_denoise_ce_enabled() and base > 0 and remainder:
            raise RuntimeError(
                "DiffusionGemma tensor replay rows must be smaller than actor DP size or divisible by it; "
                f"got rows={total_rows} actor_dp_size={world_size}. Uneven per-rank row loops would break "
                "FSDP collective symmetry."
            )
        shards: list[dict[str, torch.Tensor]] = []
        start = 0
        for rank_idx in range(world_size):
            size = base + (1 if rank_idx < remainder else 0)
            end = start + size
            if size > 0:
                shards.append(self._slice_t5_tensor_chunk_rows(tensor_chunk, start, end))
            else:
                shards.append(self._zero_loss_t5_tensor_shard_from_template(tensor_chunk))
            start = end
        return shards

    @staticmethod
    def _aggregate_t5_tensor_chunk_send_records(records: list[dict[str, Any]]) -> dict[str, Any]:
        return {
            "store": "shm",
            "dispatch": "dp",
            "ray_put_used": False,
            "shard_records": records,
            "shm_chunks": sum(int(record.get("shm_chunks", 0) or 0) for record in records),
            "shm_items": sum(int(record.get("shm_items", 0) or 0) for record in records),
            "shm_bytes": sum(int(record.get("shm_bytes", 0) or 0) for record in records),
            "shm_create_seconds": sum(float(record.get("shm_create_seconds", 0.0) or 0.0) for record in records),
            "shm_unlink_errors": 0,
            "shm_unlinked": False,
        }

    def _build_t5_tensor_chunk_shm_payload(
        self,
        tensor_chunk: dict[str, torch.Tensor],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        create_start = time.perf_counter()
        tensors: dict[str, dict[str, Any]] = {}
        non_tensors: dict[str, Any] = {}
        shm_names: list[str] = []
        total_bytes = 0
        try:
            for key, value in tensor_chunk.items():
                if not torch.is_tensor(value):
                    non_tensors[key] = value
                    continue

                tensor = value.detach()
                if tensor.device.type != "cpu":
                    tensor = tensor.cpu()
                if not tensor.is_contiguous():
                    tensor = tensor.contiguous()
                nbytes = int(tensor.numel()) * int(tensor.element_size())
                shm = SharedMemory(create=True, size=max(nbytes, 1))
                shm_names.append(shm.name)
                try:
                    if nbytes > 0:
                        raw_np = np.ndarray((nbytes,), dtype=np.uint8, buffer=shm.buf)
                        raw_t = torch.from_numpy(raw_np)
                        raw_t.copy_(tensor.view(torch.uint8).reshape(-1))
                finally:
                    shm.close()

                tensors[str(key)] = {
                    "key": str(key),
                    "name": shm.name,
                    "shape": tuple(int(dim) for dim in tensor.shape),
                    "dtype": str(tensor.dtype),
                    "nbytes": nbytes,
                }
                total_bytes += nbytes
        except Exception:
            for name in shm_names:
                try:
                    shm = SharedMemory(name=name)
                except FileNotFoundError:
                    continue
                try:
                    shm.unlink()
                except FileNotFoundError:
                    pass
                finally:
                    shm.close()
            raise

        payload = {
            "format": self._T5_TENSOR_CHUNK_SHM_FORMAT,
            "tensors": tensors,
            "non_tensors": non_tensors,
        }
        create_seconds = time.perf_counter() - create_start
        record = {
            "store": "shm",
            "ray_put_used": False,
            "shm_payload": payload,
            "shm_chunks": 1,
            "shm_items": len(tensors),
            "shm_bytes": total_bytes,
            "shm_create_seconds": create_seconds,
            "shm_unlink_errors": 0,
            "shm_unlinked": False,
        }
        return payload, record

    @classmethod
    def _unlink_t5_tensor_chunk_shm_payload(cls, payload: Any) -> int:
        if not (
            isinstance(payload, dict)
            and payload.get("format") == cls._T5_TENSOR_CHUNK_SHM_FORMAT
        ):
            return 0
        tensors = payload.get("tensors", {})
        if not isinstance(tensors, dict):
            return 0
        errors = 0
        for handle in tensors.values():
            if not isinstance(handle, dict) or "name" not in handle:
                continue
            shm = None
            try:
                shm = SharedMemory(name=str(handle["name"]))
                shm.unlink()
            except FileNotFoundError:
                pass
            except Exception:
                errors += 1
            finally:
                if shm is not None:
                    try:
                        shm.close()
                    except Exception:
                        errors += 1
        return errors

    def _unlink_t5_tensor_chunk_send_record(self, send_record: dict[str, Any] | None) -> int:
        if not send_record or send_record.get("store") != "shm" or send_record.get("shm_unlinked"):
            return 0
        shard_records = send_record.get("shard_records")
        if isinstance(shard_records, list):
            errors = 0
            for shard_record in shard_records:
                errors += self._unlink_t5_tensor_chunk_send_record(shard_record)
        else:
            errors = self._unlink_t5_tensor_chunk_shm_payload(send_record.get("shm_payload"))
        send_record["shm_unlink_errors"] = int(send_record.get("shm_unlink_errors", 0) or 0) + errors
        send_record["shm_unlinked"] = True
        return errors

    @staticmethod
    def _split_streaming_metric_float(metrics: dict[str, Any], *keys: str) -> float | None:
        for key in keys:
            value = metrics.get(key)
            if value is None:
                continue
            if isinstance(value, list):
                value = sum(
                    float(item.detach().cpu().item() if torch.is_tensor(item) else item)
                    for item in value
                    if item is not None
                )
            elif torch.is_tensor(value):
                value = value.detach().cpu().item()
            try:
                return float(value)
            except (TypeError, ValueError):
                continue
        return None

    @classmethod
    def _iter_actor_consume_metric_dicts(cls, value: Any):
        if value is None:
            return
        if isinstance(value, dict):
            yield value
            return
        if isinstance(value, DataProto):
            metrics = value.meta_info.get("metrics", {})
            if isinstance(metrics, dict):
                yield metrics
            return
        if isinstance(value, (list, tuple)):
            for item in value:
                yield from cls._iter_actor_consume_metric_dicts(item)

    @staticmethod
    def _accumulate_seconds_metric(
        state: dict[str, Any],
        prefix: str,
        seconds: float,
        *,
        calls: int = 1,
    ) -> None:
        seconds = max(0.0, float(seconds or 0.0))
        calls = int(calls)
        if calls <= 0:
            return
        state[f"{prefix}_calls"] = int(state.get(f"{prefix}_calls", 0) or 0) + calls
        state[f"{prefix}_seconds"] = float(state.get(f"{prefix}_seconds", 0.0) or 0.0) + seconds
        state[f"{prefix}_seconds_max"] = max(
            float(state.get(f"{prefix}_seconds_max", 0.0) or 0.0),
            seconds,
        )

    def _accumulate_actor_tensor_chunk_metrics(
        self,
        state: dict[str, Any],
        *,
        rows: int,
        active_tokens: int,
        tensor_bytes: int,
    ) -> None:
        state["actor_tensor_chunk_chunks"] = int(state.get("actor_tensor_chunk_chunks", 0) or 0) + 1
        state["actor_tensor_chunk_rows"] = int(state.get("actor_tensor_chunk_rows", 0) or 0) + int(rows)
        state["actor_tensor_chunk_active_tokens"] = int(
            state.get("actor_tensor_chunk_active_tokens", 0) or 0
        ) + int(active_tokens)
        state["actor_tensor_chunk_bytes"] = int(state.get("actor_tensor_chunk_bytes", 0) or 0) + int(tensor_bytes)
        state["actor_tensor_chunk_bytes_max"] = max(
            int(state.get("actor_tensor_chunk_bytes_max", 0) or 0),
            int(tensor_bytes),
        )

    def _init_actor_tensor_chunk_transport_metrics(
        self,
        state: dict[str, Any],
        split_streaming_cfg: Any | None = None,
    ) -> None:
        store = self._actor_tensor_chunk_store_mode(split_streaming_cfg)
        state["actor_tensor_chunk_store"] = store
        if store == "shm":
            state["ray_put_tensor_chunks"] = False
        state.setdefault("actor_tensor_chunk_shm_chunks", 0)
        state.setdefault("actor_tensor_chunk_shm_items", 0)
        state.setdefault("actor_tensor_chunk_shm_bytes", 0)
        state.setdefault("actor_tensor_chunk_shm_create_seconds", 0.0)
        state.setdefault("actor_tensor_chunk_shm_create_seconds_max", 0.0)
        state.setdefault("actor_tensor_chunk_shm_unlink_errors", 0)
        state.setdefault("actor_tensor_chunk_shm_materialize_chunks", 0)
        state.setdefault("actor_tensor_chunk_shm_materialize_items", 0)
        state.setdefault("actor_tensor_chunk_shm_materialize_bytes", 0)
        state.setdefault("actor_tensor_chunk_shm_materialize_seconds", 0.0)
        state.setdefault("actor_tensor_chunk_shm_materialize_seconds_max", 0.0)
        state.setdefault("actor_tensor_chunk_payload_split_seconds", 0.0)
        state.setdefault("actor_tensor_chunk_payload_split_seconds_max", 0.0)
        state.setdefault("actor_tensor_chunk_remote_call_seconds", 0.0)
        state.setdefault("actor_tensor_chunk_remote_call_seconds_max", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_enabled", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_batches", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_values", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_dense_bytes", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_sparse_bytes", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_saved_bytes", 0.0)
        state.setdefault("actor_sparse_logits_source_hidden_compress_seconds", 0.0)
        for _, prefix in self._ACTOR_T5_REPLAY_SECONDS_METRICS:
            state.setdefault(f"{prefix}_calls", 0)
            state.setdefault(f"{prefix}_seconds", 0.0)
            state.setdefault(f"{prefix}_seconds_max", 0.0)

    @staticmethod
    def _accumulate_actor_tensor_chunk_shm_unlink_metrics(
        state: dict[str, Any],
        unlink_errors: int,
    ) -> None:
        state["actor_tensor_chunk_shm_unlink_errors"] = int(
            state.get("actor_tensor_chunk_shm_unlink_errors", 0) or 0
        ) + int(unlink_errors or 0)

    def _accumulate_actor_tensor_chunk_send_metrics(
        self,
        state: dict[str, Any],
        send_record: dict[str, Any] | None,
    ) -> None:
        if not send_record:
            return
        store = self._normalize_actor_tensor_chunk_store(send_record.get("store", "tensor"))
        state["actor_tensor_chunk_store"] = store
        dispatch = self._normalize_actor_tensor_chunk_dispatch(send_record.get("dispatch", "one_to_all"))
        state["actor_tensor_chunk_dispatch"] = dispatch
        split_seconds = max(0.0, float(send_record.get("payload_split_seconds", 0.0) or 0.0))
        state["actor_tensor_chunk_payload_split_seconds"] = float(
            state.get("actor_tensor_chunk_payload_split_seconds", 0.0) or 0.0
        ) + split_seconds
        state["actor_tensor_chunk_payload_split_seconds_max"] = max(
            float(state.get("actor_tensor_chunk_payload_split_seconds_max", 0.0) or 0.0),
            split_seconds,
        )
        remote_call_seconds = max(0.0, float(send_record.get("remote_call_seconds", 0.0) or 0.0))
        state["actor_tensor_chunk_remote_call_seconds"] = float(
            state.get("actor_tensor_chunk_remote_call_seconds", 0.0) or 0.0
        ) + remote_call_seconds
        state["actor_tensor_chunk_remote_call_seconds_max"] = max(
            float(state.get("actor_tensor_chunk_remote_call_seconds_max", 0.0) or 0.0),
            remote_call_seconds,
        )
        if store != "shm":
            return
        state["actor_tensor_chunk_shm_chunks"] = int(
            state.get("actor_tensor_chunk_shm_chunks", 0) or 0
        ) + int(send_record.get("shm_chunks", 0) or 0)
        state["actor_tensor_chunk_shm_items"] = int(
            state.get("actor_tensor_chunk_shm_items", 0) or 0
        ) + int(send_record.get("shm_items", 0) or 0)
        state["actor_tensor_chunk_shm_bytes"] = int(
            state.get("actor_tensor_chunk_shm_bytes", 0) or 0
        ) + int(send_record.get("shm_bytes", 0) or 0)
        create_seconds = max(0.0, float(send_record.get("shm_create_seconds", 0.0) or 0.0))
        state["actor_tensor_chunk_shm_create_seconds"] = float(
            state.get("actor_tensor_chunk_shm_create_seconds", 0.0) or 0.0
        ) + create_seconds
        state["actor_tensor_chunk_shm_create_seconds_max"] = max(
            float(state.get("actor_tensor_chunk_shm_create_seconds_max", 0.0) or 0.0),
            create_seconds,
        )

